window.ALL_AUDIT_DATA = {"Chu_Thuat_Su_Dung_Gia": {"novel_name": "Chu_Thuat_Su_Dung_Gia", "novel_key": "Chu_Thuat_Su_Dung_Gia", "timestamp": "2026-08-28 23:44:34", "total_scanned": 289, "total_modified": 24, "total_replaces": 468, "chapters": [{"ep": 212, "title": "Tập 212: Thành quả tu luyện (1)", "filename": "chuong_212_thanh_qua_tu_luyen_1.md", "replaces": 27, "changes": [{"line": 9, "old": "Lăn lộn trên nền đất là cặp bài trùng Ueta và Nakai.", "new": "Đang lăn lộn trên nền đất là cặp bài trùng Ueta và Nakai."}, {"line": 13, "old": "Và người vừa một tay đánh lui cả hai cậu chàng cùng lúc không ai khác chính là cô bạn 『Cuồng Chiến Binh』 của chúng tôi — Mei.", "new": "Và người vừa một tay đánh lui cả hai cậu chàng cùng lúc không ai khác chính là cô bạn 『Cuồng Chiến Binh』 của chúng tôi — Mei-chan."}, {"line": 25, "old": "Yamada với tư cách là Phó ban Chăn Nuôi đã đi đến khu vực đảo hoang để chăm sóc đàn gia súc Ja-Ja.", "new": "Yamada với tư cách là Phó ban Chăn Nuôi đã đi đến khu vực đảo hoang để chăm sóc đàn gia súc Jaaja."}, {"line": 29, "old": "Tu luyện tuy quan trọng, nhưng những công việc để duy trì đời sống sinh hoạt cho cả nhóm vẫn là ưu tiên không thể bỏ qua.", "new": "Tu luyện tuy quan trọng, nhưng những công việc nhằm duy trì đời sống sinh hoạt cho cả nhóm vẫn là ưu tiên không thể bỏ qua."}, {"line": 33, "old": "Thế nhưng, khi tận mắt chứng kiến cảnh họ bị Mei — người chẳng cần dùng đến bất kỳ chiêu thức phức tạp nào — hạ gục dễ dàng, Souma không khỏi lộ ra vẻ mặt phức tạp.", "new": "Thế nhưng, khi tận mắt chứng kiến cảnh họ bị Mei-chan — người chẳng cần dùng đến bất kỳ chiêu thức phức tạp nào — hạ gục dễ dàng, Souma không khỏi lộ ra vẻ mặt phức tạp."}, {"line": 41, "old": "Mei tham gia tập luyện cùng mọi người không phải chỉ để cho vui.", "new": "Mei-chan tham gia tập luyện cùng mọi người không phải chỉ để cho vui."}, {"line": 47, "old": "Chỉ mới ba ngày trôi qua, nhưng Mei đã hoàn toàn tiếp thu được tất cả những kỹ thuật mà Souma truyền dạy. Việc cô ấy không cần dùng đến chiêu thức cầu kỳ nào trong trận đấu tập với Ueta và Nakai chính là minh chứng rõ ràng nhất cho sự chênh lệch đó.", "new": "Chỉ mới ba ngày trôi qua, nhưng Mei-chan đã hoàn toàn tiếp thu được tất cả những kỹ thuật mà Souma truyền dạy. Việc cô ấy không cần dùng đến chiêu thức cầu kỳ nào trong trận đấu tập với Ueta và Nakai chính là minh chứng rõ ràng nhất cho sự chênh lệch đó."}, {"line": 59, "old": "Mei trong bộ đồ thể thao, tay cầm thanh gỗ lớn có kích thước tương đương một thanh đại kiếm mà không cần vào tư thế thủ thế cầu kỳ. Đối thủ đứng trước mặt cô ấy là Nakajima Haruma, người đang cầm hai thanh mộc kiếm trên tay.", "new": "Mei-chan trong bộ đồ thể thao, tay cầm thanh gỗ lớn có kích thước tương đương một thanh đại kiếm mà không cần vào thế thủ cầu kỳ. Đối thủ đứng trước mặt cô ấy là Nakajima Haruma, người đang cầm hai thanh mộc kiếm trên tay."}, {"line": 81, "old": "Ngược lại, Mei vẫn đứng thong thả — thế nhưng, trước khi kịp nhận ra, thanh đại kiếm gỗ của cô ấy đã được vung ra một đường ngang tàn khốc với tốc độ kinh hoàng.", "new": "Ngược lại, Mei-chan vẫn đứng thong thả — thế nhưng, trước khi kịp nhận ra, thanh đại kiếm gỗ của cô ấy đã được vung ra một đường ngang tàn khốc với tốc độ kinh hoàng."}, {"line": 87, "old": "Nakajima nghiến răng, gương mặt biến dạng vì phải dốc toàn lực để đỡ lấy cú vung kiếm của Mei.", "new": "Nakajima nghiến răng, gương mặt biến dạng vì phải dốc toàn lực để đỡ lấy cú vung kiếm của Mei-chan."}, {"line": 95, "old": "Nakajima bắt chéo hai thanh mộc kiếm để triệt tiêu đòn tấn công của Mei. Cậu ta không chỉ đơn thuần là dùng kiếm để chặn đường đi của đòn đánh. Nếu chỉ làm vậy, cậu ta sẽ bị áp đảo hoàn toàn về mặt lực lượng và bị hất văng như Ueta hay Nakai ngay lập tức.", "new": "Nakajima bắt chéo hai thanh mộc kiếm để triệt tiêu đòn tấn công của Mei-chan. Cậu ta không chỉ đơn thuần là dùng kiếm để chặn đường đi của đòn đánh. Nếu chỉ làm vậy, cậu ta sẽ bị áp đảo hoàn toàn về mặt lực lượng và bị hất văng như Ueta hay Nakai ngay lập tức."}, {"line": 107, "old": "Thế nhưng, Nakajima lúc này chỉ riêng việc giữ vững tư thế bắt chéo kiếm đã là quá giới hạn. Dù đã thành công chặn đứng đòn đánh của Mei, cậu ta hoàn toàn không có khoảng trống nào để chuyển sang phản công.", "new": "Thế nhưng, Nakajima lúc này chỉ riêng việc giữ vững tư thế bắt chéo kiếm đã là quá giới hạn. Dù đã thành công chặn đứng đòn đánh của Mei-chan, cậu ta hoàn toàn không có khoảng trống nào để chuyển sang phản công."}, {"line": 113, "old": "Trong khoảng thời gian đó, nếu là thực chiến thì Mei đã có thể bồi thêm một đòn để dứt điểm, nhưng cô ấy đã chủ động dừng lại. Dù sao đây cũng là đấu tập chứ không phải sinh tử chiến. Việc kéo dài trận đấu để giúp đối phương làm quen với áp lực sẽ tốt hơn cho cả hai.", "new": "Trong khoảng thời gian đó, nếu là thực chiến thì Mei-chan đã có thể bồi thêm một đòn để dứt điểm, nhưng cô ấy đã chủ động dừng lại. Dù sao đây cũng là đấu tập chứ không phải sinh tử chiến. Việc kéo dài trận đấu để giúp đối phương làm quen với áp lực sẽ tốt hơn cho cả hai."}, {"line": 123, "old": "Nói đoạn, Mei thản nhiên giơ cao thanh mộc kiếm lên quá đầu.", "new": "Nói đoạn, Mei-chan thản nhiên giơ cao thanh mộc kiếm lên quá đầu."}, {"line": 131, "old": "Dù chỉ bằng một tay, nhưng khi nhìn thấy Mei giơ cao thanh kiếm, gương mặt Nakajima trong thoáng chốc đã có chút căng thẳng.", "new": "Dù chỉ bằng một tay, nhưng khi nhìn thấy Mei-chan giơ cao thanh kiếm, gương mặt Nakajima trong thoáng chốc đã có chút căng thẳng."}, {"line": 153, "old": "Cùng lúc đó, nhát chém của Mei cũng đã bổ xuống.", "new": "Cùng lúc đó, nhát chém của Mei-chan cũng đã bổ xuống."}, {"line": 159, "old": "Thanh mộc kiếm của Mei bổ thẳng xuống chỉ chém vào khoảng không.", "new": "Thanh mộc kiếm của Mei-chan bổ thẳng xuống chỉ chém vào khoảng không."}, {"line": 163, "old": "Mei lúc này đã vung hết đà kiếm. Ngược lại, Nakajima dù đang mất thăng bằng nhưng hai thanh kiếm của cậu ta đã ở tư thế sẵn sàng vung ra.", "new": "Mei-chan lúc này đã vung hết đà kiếm. Ngược lại, Nakajima dù đang mất thăng bằng nhưng hai thanh kiếm của cậu ta đã ở tư thế sẵn sàng vung ra."}, {"line": 165, "old": "Trước khi ngã xuống đất theo quán tính, cậu ta hoàn toàn có đủ thời gian để tung ra hai nhát chém liên tiếp vào người Mei.", "new": "Trước khi ngã xuống đất theo quán tính, cậu ta hoàn toàn có đủ thời gian để tung ra hai nhát chém liên tiếp vào người Mei-chan."}, {"line": 181, "old": "Ngay cả tôi cũng không ngờ rằng Mei chỉ bằng lực đập thanh mộc kiếm xuống đất lại có thể tạo ra một luồng chấn động thổi bay cả một nam sinh.", "new": "Ngay cả tôi cũng không ngờ rằng Mei-chan chỉ bằng lực đập thanh mộc kiếm xuống đất lại có thể tạo ra một luồng chấn động thổi bay cả một nam sinh."}, {"line": 189, "old": "Có lẽ ngay từ đầu Mei đã không nhắm chính xác vào Nakajima. Cô ấy biết thừa chỉ cần chấn động là đủ để làm mất thăng bằng đối phương, nên mới thẳng tay nện kiếm xuống đất.", "new": "Có lẽ ngay từ đầu Mei-chan đã không nhắm chính xác vào Nakajima. Cô ấy biết thừa chỉ cần chấn động là đủ để làm mất thăng bằng đối phương, nên mới thẳng tay nện kiếm xuống đất."}, {"line": 195, "old": "Sau khi cúi đầu chào theo đúng lễ nghi đấu tập, Mei lon ton chạy về phía chúng tôi.", "new": "Sau khi cúi đầu chào theo đúng lễ nghi đấu tập, Mei-chan lon ton chạy về phía chúng tôi."}, {"line": 203, "old": "Tôi biết Mei rất mạnh và đã làm rất tốt, nhưng mục tiêu hàng đầu lúc này là nâng cao thực lực cho những người khác cơ mà.", "new": "Tôi biết Mei-chan rất mạnh và đã làm rất tốt, nhưng mục tiêu hàng đầu lúc này là nâng cao thực lực cho những người khác cơ mà."}, {"line": 241, "old": "Dù vừa bị Mei đánh bại, kiếm sĩ Ueta đã nhanh chóng hồi phục tinh thần. Nghĩ rằng đây là một đối thủ nhẹ ký, cậu ta hào hứng xung phong ngay lập tức.", "new": "Dù vừa bị Mei-chan đánh bại, kiếm sĩ Ueta đã nhanh chóng hồi phục tinh thần. Nghĩ rằng đây là một đối thủ nhẹ ký, cậu ta hào hứng xung phong ngay lập tức."}, {"line": 251, "old": "Đúng vậy, hai thanh tiểu đao này là vũ khí có kích thước phù hợp nhất để tôi điều khiển bằng 『Hắc Phát Phược』.", "new": "Đúng vậy, hai thanh tiểu đao này là vũ khí có kích thước phù hợp nhất để tôi điều khiển bằng 『Tóc Đen Trói Buộc』."}, {"line": 307, "old": "Mei giờ đây đã thay đổi ngoại hình và trở thành một cô gái nổi bật, nhưng tính cách hòa nhã xung quanh cô ấy vẫn rất dễ mến. Cô ấy luôn mỉm cười thân thiện, và nấu ăn rất ngon. Dù hiểu được sức mạnh đáng sợ của 『Cuồng Chiến Binh』, Nakajima vẫn không thể nào hình dung ra được dáng vẻ đáng sợ của cô ấy.", "new": "Mei-chan giờ đây đã thay đổi ngoại hình và trở thành một cô gái nổi bật, nhưng tính cách hòa nhã xung quanh cô ấy vẫn rất dễ mến. Cô ấy luôn mỉm cười thân thiện, và nấu ăn rất ngon. Dù hiểu được sức mạnh đáng sợ của 『Cuồng Chiến Binh』, Nakajima vẫn không thể nào hình dung ra được dáng vẻ đáng sợ của cô ấy."}, {"line": 323, "old": "Lúc dùng thế 『Đỡ Chồng Kiếm』 để chặn đòn đánh đầu tiên của Mei, cả hai cánh tay cậu ta đã tê dại đi. Việc không để rơi kiếm lúc đó đã là một nỗ lực lớn rồi.", "new": "Lúc dùng thế 『Đỡ Chồng Kiếm』 để chặn đòn đánh đầu tiên của Mei-chan, cả hai cánh tay cậu ta đã tê dại đi. Việc không để rơi kiếm lúc đó đã là một nỗ lực lớn rồi."}]}, {"ep": 219, "title": "Tập 219: Cuộc diễn tập tổng hợp (1)", "filename": "chuong_219_cuoc_dien_tap_tong_hop_1.md", "replaces": 1, "changes": [{"line": 21, "old": "Chiến trường vốn dĩ vô cùng rộng lớn, nên việc tạo ra một vòng chiến hào khép kín đòi hỏi sự hỗ trợ rất lớn từ Thổ ma pháp của Randou-san.", "new": "Chiến trường vốn dĩ vô cùng rộng lớn, nên việc tạo ra một vòng chiến hào khép kín đòi hỏi sự hỗ trợ rất lớn từ Thổ ma thuật của Randou-san."}]}, {"ep": 221, "title": "Tập 221: Thành quả diễn tập", "filename": "chuong_221_thanh_qua_dien_tap.md", "replaces": 2, "changes": [{"line": 71, "old": "Nếu ngọn núi chỉ là đất đá thông thường, Randou có thể dùng Thổ ma pháp để đào bới... Nhưng lớp vỏ bao bọc bản thể lại là một phần cơ thể của ma vật, khả năng cao là Thổ ma pháp sẽ vô dụng.", "new": "Nếu ngọn núi chỉ là đất đá thông thường, Randou có thể dùng Thổ ma thuật để đào bới... Nhưng lớp vỏ bao bọc bản thể lại là một phần cơ thể của ma vật, khả năng cao là Thổ ma thuật sẽ vô dụng."}, {"line": 263, "old": "Để duy trì phong ấn lên ba cái đầu, cần có sự phối hợp nhịp nhàng giữa Thổ ma pháp, Băng ma pháp và dây cáp cường lực.", "new": "Để duy trì phong ấn lên ba cái đầu, cần có sự phối hợp nhịp nhàng giữa Thổ ma thuật, Băng ma thuật và dây cáp cường lực."}]}, {"ep": 233, "title": "Tập 233: Chiến dịch thảo phạt Yamata no Orochi - Giai đoạn bốn", "filename": "chuong_233_chien_dich_thao_phat_yamata_no_orochi_giai_doan_bon.md", "replaces": 6, "changes": [{"line": 23, "old": "Thiết kế cốt lõi của ma pháp trận được mô phỏng theo trận pháp màu cam rực sáng như tia lửa đầu nòng mỗi khi Randou bắn Thổ ma pháp từ khẩu súng lục ổ quay của mình.", "new": "Thiết kế cốt lõi của ma pháp trận được mô phỏng theo trận pháp màu cam rực sáng như tia lửa đầu nòng mỗi khi Randou bắn Thổ ma thuật từ khẩu súng lục ổ quay của mình."}, {"line": 35, "old": "Trong suốt quá trình đào hào và đắp boongke, đây là Thổ ma pháp vận hành hiệu quả nhất và có tần suất sử dụng vượt trội nhất trong mọi hạng mục công trình. Dạo gần đây, độ thuần thục của Randou đối với ma pháp này cũng tăng lên vùn vụt.", "new": "Trong suốt quá trình đào hào và đắp boongke, đây là Thổ ma thuật vận hành hiệu quả nhất và có tần suất sử dụng vượt trội nhất trong mọi hạng mục công trình. Dạo gần đây, độ thuần thục của Randou đối với ma pháp này cũng tăng lên vùn vụt."}, {"line": 37, "old": "Bằng cách sử dụng Thổ ma pháp quen tay nhất kết hợp với sự hỗ trợ từ ma pháp trận, hiệu suất đào sâu xuống lòng đất sẽ được tối ưu hóa đến mức tối đa.", "new": "Bằng cách sử dụng Thổ ma thuật quen tay nhất kết hợp với sự hỗ trợ từ ma pháp trận, hiệu suất đào sâu xuống lòng đất sẽ được tối ưu hóa đến mức tối đa."}, {"line": 57, "old": "Tuy nhiên, đây không phải là Thổ ma pháp trận, mà là 『Nhãn Lục Mang Tinh』 quen thuộc của tôi.", "new": "Tuy nhiên, đây không phải là Thổ ma thuật trận, mà là 『Nhãn Lục Mang Tinh』 quen thuộc của tôi."}, {"line": 243, "old": "『Hắc Thiết Hoàn』: Thanh kiếm do Takanashi rèn đúc, sử dụng cùng loại nguyên liệu với 『Phong Ấn Thương - Hắc Kim』. Lưỡi kiếm đen tuyền này tuy có phần đầm tay và nặng nề, nhưng Thổ ma pháp kích hoạt từ nó lại mạnh đến mức có thể hóa sắt.", "new": "『Hắc Thiết Hoàn』: Thanh kiếm do Takanashi rèn đúc, sử dụng cùng loại nguyên liệu với 『Phong Ấn Thương - Hắc Kim』. Lưỡi kiếm đen tuyền này tuy có phần đầm tay và nặng nề, nhưng Thổ ma thuật kích hoạt từ nó lại mạnh đến mức có thể hóa sắt."}, {"line": 251, "old": "Và trên thân 『Phong Ấn Thương - Hắc Kim』 có khắc một hiệu ứng bổ trợ: nếu có Thổ ma pháp cùng chất liệu sắt đen xuất hiện ở cự ly gần, nó sẽ tự động hấp thụ để tự phục hồi và gia cố bản thân.", "new": "Và trên thân 『Phong Ấn Thương - Hắc Kim』 có khắc một hiệu ứng bổ trợ: nếu có Thổ ma thuật cùng chất liệu sắt đen xuất hiện ở cự ly gần, nó sẽ tự động hấp thụ để tự phục hồi và gia cố bản thân."}]}, {"ep": 236, "title": "Tập 236: Trận chiến chinh phạt Yamata no Orochi - Sụp đổ", "filename": "chuong_236_tran_chien_chinh_phat_yamata_no_orochi_sup_do.md", "replaces": 1, "changes": [{"line": 109, "old": "Vừa dùng Hỏa ma pháp hất văng cái đầu Orochi đang nhe nanh múa vuốt, Ryuuichi vừa hét lớn để xốc lại tinh thần cho người bạn thân đang đứng chôn chân.", "new": "Vừa dùng Hỏa ma thuật hất văng cái đầu Orochi đang nhe nanh múa vuốt, Ryuuichi vừa hét lớn để xốc lại tinh thần cho người bạn thân đang đứng chôn chân."}]}, {"ep": 251, "title": "Tập 251: Khu vực khởi đầu hoài niệm", "filename": "chuong_251_khu_vuc_khoi_dau_hoai_niem.md", "replaces": 2, "changes": [{"line": 233, "old": "Khi thiếu vắng cả Mei-chan lẫn Souma, tuyến đầu của chúng tôi khó lòng có thể coi là áp đảo tuyệt đối. Vào những thời khắc sinh tử, chỗ dựa đáng tin cậy nhất chính là Thổ ma pháp của Kyouko. Đó là sự kết hợp giữa sức công phá hủy diệt của ma pháp tấn công cấp cao, cùng với bức tường phòng ngự kiên cố bằng đá tảng được tôi luyện qua hàng loạt công trình xây dựng với tốc độ dựng lũy thần tốc.", "new": "Khi thiếu vắng cả Mei-chan lẫn Souma, tuyến đầu của chúng tôi khó lòng có thể coi là áp đảo tuyệt đối. Vào những thời khắc sinh tử, chỗ dựa đáng tin cậy nhất chính là Thổ ma thuật của Kyouko. Đó là sự kết hợp giữa sức công phá hủy diệt của ma pháp tấn công cấp cao, cùng với bức tường phòng ngự kiên cố bằng đá tảng được tôi luyện qua hàng loạt công trình xây dựng với tốc độ dựng lũy thần tốc."}, {"line": 235, "old": "Dù cho quân địch có đông đến mức tràn qua cả hàng tiên phong, hay khi chúng tôi bị đánh úp tập kích từ phía sau dẫn đến thế gọng kìm, chỉ cần có bức tường kiên cố của Thổ ma pháp che chở, chúng tôi vẫn thừa sức lật ngược tình thế.", "new": "Dù cho quân địch có đông đến mức tràn qua cả hàng tiên phong, hay khi chúng tôi bị đánh úp tập kích từ phía sau dẫn đến thế gọng kìm, chỉ cần có bức tường kiên cố của Thổ ma thuật che chở, chúng tôi vẫn thừa sức lật ngược tình thế."}]}, {"ep": 252, "title": "Tập 252: Chuyển hướng", "filename": "chuong_252_chuyen_huong.md", "replaces": 1, "changes": [{"line": 25, "old": "Vì bản đồ này có vẻ được chiếu bằng Quang ma pháp hay thứ gì đó tương tự, nên dĩ nhiên khi chạm vào sẽ chẳng có cảm giác gì.", "new": "Vì bản đồ này có vẻ được chiếu bằng Quang ma thuật hay thứ gì đó tương tự, nên dĩ nhiên khi chạm vào sẽ chẳng có cảm giác gì."}]}, {"ep": 266, "title": "Tập 266: Chú thuật sư VS Thực nhân quỷ (1)", "filename": "chuong_266_chu_thuat_su_vs_thuc_nhan_quy_1.md", "replaces": 124, "changes": [{"line": 5, "old": "Hayama đã gục ngã.", "new": "Hayama đổ gục xuống."}, {"line": 7, "old": "Dù có muốn phủ nhận thế nào, tôi cũng buộc phải hiểu rằng tình thế đã vô phương cứu chữa. Bản thân tôi cũng từng trải qua cảm giác kiệt quệ ma lực đến mức ngất đi rồi. Thứ đó thực sự không phải là thứ có thể vượt qua bằng ý chí hay quyết tâm đơn thuần.", "new": "Dù có muốn phủ nhận thế nào, tôi cũng buộc phải hiểu rằng tình thế đã vô phương cứu vãn. Bản thân tôi cũng từng nếm trải cảm giác kiệt quệ ma lực đến mức bất tỉnh nhân sự rồi. Thứ đó thực sự không phải là thứ có thể vượt qua bằng ý chí hay quyết tâm đơn thuần."}, {"line": 9, "old": "Thốt ra được lời cuối cùng đó đã là một nỗ lực phi thường của Hayama rồi.", "new": "Thốt ra được câu nói sau cùng ấy đã là một nỗ lực phi thường của Hayama rồi."}, {"line": 15, "old": "Tỏa ra luồng sáng tương tự như lúc hóa thành Linh thú, cơ thể của Kinako và Beniwo nhanh chóng co lại.", "new": "Tỏa ra luồng sáng tương tự như lúc hóa thành Linh thú, cơ thể của Kinako và Beniwo nhanh chóng co rút lại."}, {"line": 17, "old": "Trong chớp mắt, chúng trở lại hình dáng ban đầu rồi đổ rụp xuống đất ngay cạnh chủ nhân của mình.", "new": "Trong chớp mắt, chúng trở về hình dáng ban đầu rồi đổ rụp xuống nền đất ngay cạnh chủ nhân của mình."}, {"line": 19, "old": "Có lẽ bản thân Linh thú cũng phải chịu một gánh nặng không hề nhỏ. Một khi hết thời gian hiệu lực, chúng sẽ lập tức gục ngã mà không có ngoại lệ — quả là một thanh gươm hai lưỡi.", "new": "Có lẽ bản thân Linh thú cũng phải gánh chịu một phản phệ không hề nhỏ. Một khi hết thời gian duy trì, chúng sẽ lập tức ngã quỵ mà không có ngoại lệ — quả thực là một con dao hai lưỡi."}, {"line": 21, "old": "“Phù... Phù... Hộc, hơ hơ hơ... Gục rồi sao, lũ vô dụng hèn nhát này.”", "new": "“Phù... Phù... Hộc, hơ hơ hơ... Gục cả rồi sao, lũ tép riu hèn nhát này.”"}, {"line": 23, "old": "Yokomichi, kẻ đang đẫm máu sau khi hứng chịu cơn mưa đòn từ Linh thú, vẫn rung lắc thân hình khổng lồ còn đứng vững của mình mà cười lớn.", "new": "Yokomichi, kẻ toàn thân đẫm máu sau khi hứng trọn cơn mưa đòn từ Linh thú, vẫn rung lắc thân hình đồ sộ còn gượng đứng vững của mình mà cười the thé."}, {"line": 25, "old": "Gương mặt heo khổng lồ bị nát một bên mắt, răng nanh gãy vụn, chiếc mũi lớn cũng bị xé toạc một nửa há hốc miệng ra. Từ đầu lưỡi của nó, Yokomichi thò đầu ra nhìn xuống tôi.", "new": "Gương mặt heo khổng lồ bị nát một bên mắt, răng nanh gãy vụn, chiếc mũi lớn cũng bị xé toạc một nửa, há hốc hoác ra. Từ đầu lưỡi của con quái vật, Yokomichi thò đầu ra nhìn xuống tôi."}, {"line": 27, "old": "“Thế là... cuối cùng lũ cản đường cũng biến mất rồi... Chỉ còn hai ta thôi nhé, Kotarou-kyun~”", "new": "“Thế là... cuối cùng lũ cản đường cũng biến mất cả rồi... Giờ chỉ còn hai ta thôi nhé, Kotarou-kyun~”"}, {"line": 29, "old": "Nguy rồi, vẫn chưa hạ gục được hắn. Tôi cứ nghĩ đòn vừa rồi chắc chắn sẽ thành công chứ.", "new": "Nguy rồi, vẫn chưa hạ gục được hắn. Tôi cứ ngỡ đòn vừa rồi chắc chắn đã kết liễu được rồi chứ."}, {"line": 31, "old": "Dù hắn có đang đầy rẫy thương tích, tôi vẫn không có đủ sức tấn công để kết liễu một Yokomichi ở trạng thái 『Hoàn Toàn Biến Thái』. Chỉ một quả lựu đạn ném vào chắc chắn không đủ để làm hắn ngã xuống.", "new": "Dù hắn đang mang đầy thương tích, tôi vẫn không có đủ hỏa lực để dứt điểm một Yokomichi ở trạng thái 『Biến Thái Hoàn Toàn』. Chỉ một hai quả lựu đạn ném vào chắc chắn không đủ để đánh sập hắn."}, {"line": 33, "old": "L-Làm sao bây giờ... Dùng đến át chủ bài cuối cùng, chiến thuật phản đòn bằng 『Phản Phục Thống Khổ』 chăng? Nếu có thể trả lại vết thương một cách hoàn hảo, Yokomichi sẽ gục ngã, còn tôi thì có thể trị liệu để hồi sinh.", "new": "L-Làm sao bây giờ... Dùng đến quân bài tẩy cuối cùng, chiến thuật phản đòn bằng 『Phản Phục Thống Khổ』 chăng? Nếu có thể trả ngược toàn bộ vết thương một cách hoàn hảo, Yokomichi sẽ gục ngã, còn tôi thì có thể được trị liệu để hồi sinh."}, {"line": 35, "old": "Không, bất khả thi. Tôi tự tin rằng mình sẽ bị hắn ngoạm một miếng chết tươi trước khi kịp làm gì.", "new": "Không, bất khả thi. Tôi dám chắc mình sẽ bị hắn ngoạm một phát chết tươi trước khi kịp kích hoạt bất cứ thứ gì."}, {"line": 37, "old": "Được rồi, chạy thôi.", "new": "Được rồi, rút lui thôi."}, {"line": 41, "old": "Ngay khoảnh khắc hắn bước lên một bước về phía tôi.", "new": "Ngay khoảnh khắc hắn vừa bước lên một bước về phía tôi."}, {"line": 45, "old": "Cơ thể khổng lồ mất thăng bằng, đổ nghiêng.", "new": "Thân hình khổng lồ mất thăng bằng, đổ nghiêng sang một bên."}, {"line": 47, "old": "Kèm theo tiếng da thịt rách toạc giòn giã, từ những vết cào sâu hoắm mà Kinako để lại trên bụng hắn, máu thịt bắt đầu trào ra ồ ạt.", "new": "Kèm theo tiếng da thịt rách toạc ghê rợn, từ những vết cào sâu hoắm mà Kinako để lại trên bụng hắn, máu thịt bắt đầu trào ra cuồn cuộn."}, {"line": 49, "old": "“Ngư-a-a-a-a-a-a!? Ọe-e-e-e-e-e————”", "new": "“Ngư-a-a-a-a-a-a!? Ọe-e-e-e-e-e————!”"}, {"line": 51, "old": "Chắc chắn cơ thể của Yokomichi cũng đã vượt quá giới hạn từ lâu rồi.", "new": "Quả nhiên, cơ thể của Yokomichi cũng đã vượt quá giới hạn chịu đựng từ lâu rồi."}, {"line": 53, "old": "Từ khắp nơi trên người hắn, những tia máu liên tục phun ra. Con quái vật gầm lên đau đớn rồi đổ sụp xuống đất.", "new": "Từ khắp nơi trên người hắn, những tia máu liên tục bắn ra xối xả. Con quái vật gầm rú trong đau đớn cùng cực rồi sụp đổ hoàn toàn xuống mặt đất."}, {"line": 55, "old": "Máu chảy thành sông, nội tạng nhớp nhúa tuôn ra từ vết thương hở hoác.", "new": "Máu chảy thành sông, nội tạng nhớp nhúa tuôn trào từ vết thương hở toác."}, {"line": 57, "old": "Gương mặt heo gớm ghiếc phun ra huyết lệ và máu mũi. Từ cái miệng há rộng, cùng với bãi bọt máu như thác đổ, Yokomichi bị nôn ra ngoài.", "new": "Gương mặt heo gớm ghiếc ứa ra huyết lệ cùng máu mũi. Từ cái miệng há rộng, hòa cùng bãi bọt máu trào dâng như thác đổ, Yokomichi bị nôn thốc nôn tháo ra ngoài."}, {"line": 59, "old": "Yokomichi, bám đầy những mảnh thịt lưỡi đỏ thẫm, trở lại hình dạng con người và rơi xuống vũng máu do chính mình tạo ra.", "new": "Yokomichi, toàn thân bết dính những mảnh thịt lưỡi đỏ thẫm, trở lại hình dạng con người và rơi tõm xuống vũng máu do chính mình nôn ra."}, {"line": 63, "old": "Hắn lảo đảo đứng dậy. Thân hình nhớp nhúa máu thịt đỏ ngầu trông như một đứa trẻ quái thai vừa được sinh ra từ bụng của một con quái vật.", "new": "Hắn lảo đảo gượng dậy. Thân thể nhớp nhúa máu thịt đỏ ngầu trông chẳng khác nào một quái thai vừa chui ra từ bụng của một con ma vật."}, {"line": 67, "old": "Yokomichi gào thét.", "new": "Yokomichi gào thét điên cuồng."}, {"line": 69, "old": "Cơ thể của 『Hoàn Toàn Biến Thái』 đã hoàn toàn sụp đổ, nhưng có vẻ bản thể của hắn vẫn còn đủ sức để lao vào cắn xé con mồi.", "new": "Thể xác của 『Biến Thái Hoàn Toàn』 đã hoàn toàn sụp đổ, nhưng dường như bản thể của hắn vẫn còn đủ sức để lao vào cắn xé con mồi."}, {"line": 71, "old": "Nhưng giờ đây, khi hắn đã bị bào mòn đến mức mất đi phần lớn sức mạnh, chỉ một mình tôi cũng đủ để kết liễu hắn!", "new": "Thế nhưng giờ đây, khi hắn đã bị bào mòn đến mức mất đi phần lớn sức mạnh, chỉ riêng một mình tôi cũng đủ sức kết liễu hắn!"}, {"line": 77, "old": "Con Loyrops gầm rú, lao thẳng về phía Yokomichi với tốc độ tối đa. Với kích thước con người hiện tại của hắn, cú húc đó sẽ mang một sức tàn phá khủng khiếp.", "new": "Con Loyrops gầm rú, lao thẳng về phía Yokomichi với tốc độ tối đa. Với thể trọng con người hiện tại của hắn, cú húc bọc thép đó sẽ mang sức tàn phá khủng khiếp."}, {"line": 81, "old": "Nhưng ngay cả khi đã trở lại dạng người, sức mạnh phi nhân loại của Yokomichi vẫn chưa cạn kiệt.", "new": "Nhưng dẫu đã trở lại dạng người, sức mạnh phi nhân tính của Yokomichi vẫn chưa hề cạn kiệt."}, {"line": 83, "old": "Hắn trực diện đỡ lấy cú húc. Dù bị đẩy lùi sền sệt trên mặt đất, hắn vẫn cản lại được cú va chạm một cách ngoạn mục.", "new": "Hắn trực diện giơ tay chặn đứng cú húc. Dù bị đẩy lùi lê dài trên mặt đất, hắn vẫn cản phá được cú va chạm một cách kinh ngạc."}, {"line": 85, "old": "Bí mật của sức mạnh đó chắc chắn là do trong bụng hắn vẫn còn sót lại vài con mồi. Từ vai và hông của Yokomichi mọc ra thêm những cánh tay người thô kệch, biến hắn thành một kẻ có 6 tay để giữ chặt lấy Loyrops.", "new": "Bí mật đằng sau sức mạnh quái dị đó hẳn là do trong bụng hắn vẫn còn tích trữ vài con mồi chưa tiêu hóa hết. Từ vai và hông của Yokomichi mọc ra thêm những cánh tay người thô kệch, biến hắn thành một kẻ có 6 cánh tay để bóp nghẹt lấy Loyrops."}, {"line": 89, "old": "Thay cho câu trả lời, một tiếng xé gió sắc lẹm vang lên.", "new": "Đáp lại lời tôi là một tiếng xé gió sắc lẹm."}, {"line": 91, "old": "Mũi tên bắn ra từ 『Hắc Giác Cung』 lao thẳng về phía Yokomichi — và lần này, mũi tên đã cắm phập vào da thịt hắn.", "new": "Mũi tên phóng ra từ 『Hắc Giác Cung』 lao thẳng tới Yokomichi — và lần này, mũi tên đã cắm phập vào da thịt hắn."}, {"line": 93, "old": "“Á-a-a!? Đừng có coi thường tao! Mày nghĩ đến nước này rồi mà mấy mũi tên cỏn con đó còn có tác dụng sao!”", "new": "“Á-a-a!? Đừng có coi thường tao! Mày nghĩ đến nước này rồi mà mấy mũi tên cỏn con đó còn xi nhê gì sao!”"}, {"line": 95, "old": "Yokomichi hứng trọn mũi tên thứ hai, thứ ba liên tiếp bắn ra từ cây cung cứng. Hắn dùng 6 cánh tay che chắn như những tấm khiên. Dù tên cắm đầy người, hắn vẫn không hề có dấu hiệu ngã xuống.", "new": "Yokomichi hứng trọn mũi tên thứ hai, thứ ba liên tiếp bắn ra từ cây cung lớn. Hắn dùng 6 cánh tay đan lại che chắn như những tấm khiên thịt. Dù tên cắm chi chít khắp người, hắn vẫn không hề có dấu hiệu ngã xuống."}, {"line": 97, "old": "*Chậc, chỉ dùng cung tên thì không thể kết liễu được hắn sao.*", "new": "*Chậc, chỉ bằng cung tên thì không thể dứt điểm được hắn sao.*"}, {"line": 99, "old": "Nếu vậy, tôi sẽ dội lên đầu hắn những đòn tấn công đủ sức kết liễu.", "new": "Nếu vậy, tôi sẽ dội lên đầu hắn những đòn tấn công đủ sức tiễn hắn về cõi chết."}, {"line": 101, "old": "“Tao không bỏ cuộc đâu... Chắc chắn tao sẽ không bỏ cuộc... Dù có phải vắt kiệt chút sức lực và ý chí cuối cùng, tao cũng phải ăn thịt Kotarou-kyun!”", "new": "“Tao không bỏ cuộc đâu... Chắc chắn tao sẽ không bỏ cuộc... Dù có phải vắt kiệt chút tàn lực và ý chí cuối cùng, tao cũng phải ăn thịt bằng được Kotarou-kyun!”"}, {"line": 103, "old": "Cơ thể đang gào thét của Yokomichi lại bắt đầu biến đổi tiếp.", "new": "Cơ thể đang gào thét của Yokomichi lại bắt đầu biến dạng tiếp."}, {"line": 105, "old": "*Này này, tha cho tôi đi chứ. Hắn vẫn còn đủ sức để biến hình nữa sao?*", "new": "*Này này, tha cho tôi đi chứ. Hắn vẫn còn đủ sức để biến hình nữa à?*"}, {"line": 107, "old": "Tiếng xương thịt chuyển động răng rắc vang lên. Lông thú và lớp giáp xác bắt đầu hình thành trên 6 cánh tay mới mọc. Chúng biến đổi, mọc ra những chiếc móng vuốt dài hoặc trông như chân nhện.", "new": "Tiếng xương thịt vặn vẹo răng rắc vang lên chói tai. Lông thú rậm rạp và lớp giáp xác bắt đầu hình thành trên 6 cánh tay mới mọc. Chúng biến đổi, mọc ra những chiếc móng vuốt sắc nhọn hoặc khoằm lại như chân nhện."}, {"line": 109, "old": "Hơn nữa, từ trên đầu hắn, những xúc tu giun đất bắt đầu ngoe nguẩy mọc ra, trông không khác gì cái đầu đầy rắn của Medusa.", "new": "Chưa hết, từ trên đỉnh đầu hắn, những xúc tu giun đất bắt đầu ngoe nguẩy trồi ra, trông chẳng khác nào mái đầu đầy rắn độc của Medusa."}, {"line": 111, "old": "Và điều kinh tởm nhất là, từ chiếc quần lót sịp nam không hiểu sao vẫn còn nguyên vẹn kia, một con rắn khổng lồ màu tím bò ra. *Này, con rắn đó là bộ phận nào biến hình thành thế hả?!*", "new": "Và điều tởm lợm nhất là, từ chiếc quần lót nam không hiểu sao vẫn còn nguyên vẹn kia, một con rắn khổng lồ màu tím ngắt ngóc đầu bò ra. *Này, con rắn đó là bộ phận nào biến hình thành thế hả?!*"}, {"line": 113, "old": "Trước sự biến đổi cực kỳ kinh tởm đến tận phút cuối cùng của Yokomichi, tôi một lần nữa đưa ra quyết định.", "new": "Trước màn biến dị cực kỳ kinh tởm đến tận phút chót của Yokomichi, tôi một lần nữa đưa ra quyết định dứt khoát."}, {"line": 115, "old": "“Không thể hạ gục hắn lúc này được. Rút lui thôi!”", "new": "“Hiện tại không thể hạ gục hắn được. Rút lui thôi!”"}, {"line": 117, "old": "Không chút do dự, tôi ném quả bom khói vừa lấy ra về phía Yokomichi, kẻ vừa hoàn thành dạng biến hình cuối cùng.", "new": "Không chút do dự, tôi ném phắt quả bom khói vừa lấy ra về phía Yokomichi, kẻ vừa hoàn thành dạng biến hình cuối cùng."}, {"line": 119, "old": "“— Chậc, lại là khói à.”", "new": "“— Chậc, lại trò tung khói à.”"}, {"line": 121, "old": "Trước màn sương khói dày đặc, Yokomichi đảo mắt nhìn quanh với ánh nhìn sắc lạnh.", "new": "Trước màn sương khói dày đặc, Yokomichi đảo tròng mắt nhìn quanh với ánh nhìn sắc lạnh."}, {"line": 123, "old": "“Tao tuyệt đối không để mày thoát...”", "new": "“Tao tuyệt đối sẽ không để mày thoát...”"}, {"line": 125, "old": "Giác quan từng nhạy bén vô cùng của hắn giờ đây đã trở nên cực kỳ cùn mòn. Cứ như thể hắn đã quay trở lại làm bản thân của ngày xưa vậy.", "new": "Giác quan từng nhạy bén phi thường của hắn giờ đây đã trở nên cực kỳ cùn mòn. Cứ như thể hắn đã bị kéo tụt trở lại làm một kẻ tầm thường như ngày xưa."}, {"line": 127, "old": "Thị lực như chim ưng nhìn xa vạn dặm, khứu giác nhạy bén săn lùng con mồi. Thính giác không bỏ sót một tiếng bước chân nhỏ nhất, xúc giác cảm nhận được cả sự chuyển động của luồng không khí. Thậm chí cả những khả năng nằm ngoài ngũ quan của con người như cảm biến nhiệt hay dò tìm bằng sóng siêu âm, Yokomichi đều từng sở hữu.", "new": "Thị lực như chim ưng nhìn xa ngàn dặm, khứu giác tinh tường săn lùng con mồi. Thính giác không bỏ sót một tiếng bước chân khẽ khàng nhất, xúc giác cảm nhận được cả sự chuyển dịch của luồng không khí. Thậm chí cả những năng lực vượt ngoài ngũ quan của nhân loại như cơ quan cảm biến nhiệt hay dò tìm bằng sóng siêu âm, Yokomichi đều từng sở hữu."}, {"line": 129, "old": "Thế nhưng, sau khi cắt bỏ hoàn toàn nửa thân quái vật, lại thêm việc trạng thái 『Hoàn Toàn Biến Thái』 bị sụp đổ, vô số kỹ năng săn mồi hỗ trợ cho Yokomichi đã biến mất. Lượng con mồi tích trữ trong chiếc 『Dạ Dày Không Đáy』 vốn đã ăn bao nhiêu nay cũng sắp cạn kiệt.", "new": "Thế nhưng, sau khi tự cắt bỏ hoàn toàn nửa thân quái vật, lại thêm việc trạng thái 『Biến Thái Hoàn Toàn』 bị sụp đổ, vô số kỹ năng săn mồi hỗ trợ cho Yokomichi đã tan biến sạch sẽ. Lượng con mồi tích trữ trong chiếc 『Dạ Dày Không Đáy』 vốn dĩ ăn bao nhiêu cũng không đầy, nay đã cạn kiệt đến đáy."}, {"line": 133, "old": "Vì đã mất đi quá nhiều thứ, cơn đói mà hắn cảm nhận được lúc này là cơn đói cồn cào nhất kể từ khi biến thành 『Thực Nhân Quỷ』.", "new": "Vì đã đánh mất quá nhiều thứ, cơn đói cào xé ruột gan mà hắn cảm nhận lúc này là cơn đói dữ dội nhất kể từ khi biến thành 『Thực Nhân Quỷ』."}, {"line": 135, "old": "Không đủ. Thịt không đủ. Máu không đủ. Ma lực, sinh mệnh lực, sức mạnh, tất cả mọi thứ đều không đủ.", "new": "Không đủ. Thịt không đủ. Máu không đủ. Ma lực, sinh mệnh lực, sức mạnh, tất cả mọi thứ đều thiếu thốn trầm trọng."}, {"line": 137, "old": "Dù đang phải chịu đựng cơn đói cồn cào đến mức sắp phát điên, trong lòng Yokomichi lại trào dâng một cảm giác gần như là hân hoan. Bởi vì con mồi thượng hạng mà hắn cất công dồn vào chân tường đang ở ngay trước mắt.", "new": "Dù đang bị dày vò bởi cơn đói cồn cào đến mức phát điên, sâu trong thâm tâm Yokomichi lại trào dâng một cảm giác hân hoan tột cùng. Bởi vì con mồi thượng hạng mà hắn cất công dồn vào chân tường đang ở ngay trước mắt."}, {"line": 141, "old": "Khoảnh khắc nếm thử giọt máu đó, thế giới của hắn đã hoàn toàn thay đổi.", "new": "Khoảnh khắc nếm thử giọt máu ấy, cả thế giới của hắn đã hoàn toàn đảo lộn."}, {"line": 143, "old": "Một cú sốc đủ sức đập tan mọi giá trị quan từ trước đến nay. Một khoái cảm tột đỉnh mà dù có cộng tất cả những hạnh phúc trong cuộc đời lại cũng không thể nào sánh bằng.", "new": "Một cơn địa chấn đủ sức nghiền nát mọi giá trị quan từ trước đến nay. Một khoái cảm tột đỉnh mà dẫu có gom góp tất thảy mọi hạnh phúc trên cõi đời này lại cũng không thể nào sánh bằng."}, {"line": 145, "old": "Phải, đó chính là thứ không thể gọi bằng gì khác ngoài hai chữ \"vận mệnh\".", "new": "Phải, đó chính là thứ không thể gọi bằng danh từ nào khác ngoài hai chữ \"định mệnh\"."}, {"line": 147, "old": "Vì thế, hắn đã tìm kiếm. Hắn đã luôn khao khát tìm kiếm.", "new": "Bởi vậy, hắn đã không ngừng tìm kiếm. Hắn luôn khao khát săn lùng bằng mọi giá."}, {"line": 149, "old": "Những con mồi khác suy cho cùng cũng chỉ là thức ăn để duy trì sự sống. So với hương vị của Kotarou, mọi xương thịt khác đều trở nên vô vị và nhạt nhẽo.", "new": "Những con mồi khác suy cho cùng cũng chỉ là rác rưởi để duy trì sự sống. So với phong vị của Kotarou, mọi xương thịt trần gian đều trở nên nhạt nhẽo và vô vị."}, {"line": 151, "old": "“Cho tao ăn... Cho tao ăn đi mà...”", "new": "“Cho tao ăn... Mau cho tao ăn đi mà...”"}, {"line": 153, "old": "Dù năng lực đã mất đi quá nhiều và các giác quan đã trở nên cùn mòn, Yokomichi vẫn lần theo chút dao động ma lực yếu ớt để tiến bước.", "new": "Dẫu năng lực đã rơi rụng quá nhiều và các giác quan đã cùn mòn, Yokomichi vẫn lần theo chút dao động ma lực mong manh để cất bước."}, {"line": 155, "old": "Kotarou không chạy đi đâu xa.", "new": "Kotarou không thể chạy đi đâu xa được."}, {"line": 157, "old": "Hắn biết rõ cậu ta đang hướng về phía Quảng trường Tinh Linh bên trong tòa nhà giống như nhà thờ này.", "new": "Hắn thừa biết cậu ta đang hướng về phía Quảng Trường Tinh Linh nằm sâu bên trong công trình tựa như nhà thờ này."}, {"line": 159, "old": "Nếu vậy thì không còn đường chạy nữa rồi. Hắn chắc chắn đã dồn cậu ta vào đường cùng.", "new": "Nếu vậy thì hết đường chạy rồi. Hắn chắc chắn đã dồn cậu ta vào ngõ cụt."}, {"line": 163, "old": "Giữa lúc hắn đang bước đi đầy tự tin, con Raptor màu đỏ gầm rú lao ra từ trong làn khói.", "new": "Giữa lúc hắn đang sải bước đầy tự tin, con Raptor màu đỏ gầm rú lao vút ra từ trong màn khói."}, {"line": 165, "old": "Một kẻ quen mặt. Kẻ mà hắn vừa nhìn thấy lúc nãy.", "new": "Một gương mặt quen thuộc. Chính là thứ hắn vừa trông thấy lúc nãy."}, {"line": 167, "old": "Con Raptor đỏ mà Kotarou đã cưỡi. Có lẽ là một loại triệu hoán thú hay thứ gì đó tương tự.", "new": "Con Raptor đỏ mà Kotarou từng cưỡi. Có lẽ là một dạng sứ ma hay thứ gì đó tương tự."}, {"line": 169, "old": "“Cái gọi là kháng cự vô ích... chính là để chỉ việc này đây.”", "new": "“Cái gọi là kháng cự vô vọng... chính là để chỉ trò này đây.”"}, {"line": 171, "old": "Hắn đỡ lấy chiếc đuôi dạng cưa đang quất tới với tốc độ cao, rồi chặn đứng toàn bộ móng vuốt và răng nanh đang lao đến tiếp theo.", "new": "Hắn giơ tay đỡ phăng chiếc đuôi dạng cưa đang quất tới xé gió, rồi tiện tay khóa chặt toàn bộ móng vuốt cùng răng nanh đang chồm tới tiếp theo."}, {"line": 173, "old": "Dù có mất đi bao nhiêu sức mạnh, hắn cũng chưa yếu đến mức để một đối thủ tầm này làm khó dễ.", "new": "Dù có hao tổn bao nhiêu sức mạnh, hắn cũng chưa suy đồi đến mức để một con súc sinh tầm này làm khó dễ."}, {"line": 175, "old": "“Tránh ra! Tao đang đói lắm rồi!!!”", "new": "“Tránh đường! Tao đang đói chết đi được đây này!!!”"}, {"line": 177, "old": "Sử dụng 6 cánh tay đấm túi bụi. Hắn đập nát lớp vảy của con thú, tóm lấy đuôi nó rồi quăng mạnh đi.", "new": "Sử dụng cả 6 cánh tay đấm túi bụi, hắn đập vỡ vụn lớp vảy của con thú, tóm chặt lấy đuôi nó rồi quăng quật thẳng tay."}, {"line": 179, "old": "Hắn không rảnh để kết liễu nó. Hắn có thừa sức để giết nó, nhưng tâm trí hắn lúc này không thể bận tâm đến bất cứ việc gì khác ngoài việc ăn thịt Kotarou.", "new": "Hắn chẳng rảnh hơi đâu mà bận tâm kết liễu nó. Hắn thừa sức xé xác nó ra, nhưng tâm trí hắn lúc này không thể dung nạp thêm bất cứ thứ gì khác ngoài việc nuốt chửng Kotarou."}, {"line": 181, "old": "Phải rồi, khi đứng trước cậu ta, mọi chuyện khác đều phải gác lại phía sau.", "new": "Phải rồi, khi đứng trước con mồi ấy, mọi chuyện trên đời đều phải dẹp sang một bên."}, {"line": 185, "old": "Vừa thoát khỏi màn khói, hắn đã đứng ngay bên trong nhà thờ.", "new": "Vừa xé toạc màn khói bước ra, hắn đã đứng sừng sững bên trong gian nhà thờ."}, {"line": 187, "old": "Đó là một sảnh lớn giống như lối vào, phía sâu bên trong có thể thấy Quảng trường Tinh Linh đang trải rộng, nhưng Yokomichi không hề bận tâm đến cảnh tượng đó.", "new": "Đó là một đại sảnh thênh thang giống như lối vào tiền sảnh, phía sâu bên trong có thể thấy Quảng Trường Tinh Linh đang trải rộng, nhưng Yokomichi chẳng thèm liếc mắt lấy một lần."}, {"line": 189, "old": "Thứ duy nhất phản chiếu trong đôi mắt đục ngầu vì dục vọng của hắn là bóng hình của một thiếu niên duy nhất.", "new": "Thứ duy nhất in hằn trong đôi mắt đục ngầu vì dục vọng của hắn là bóng hình của một thiếu niên duy nhất."}, {"line": 193, "old": "Ngay chính giữa sảnh lớn. Không thể nào nhìn lầm được. Momokawa Kotarou đang đứng đó, tay cầm một thanh kiếm duy nhất, như thể đang muốn đường đường chính chính quyết đấu một chọi một.", "new": "Ngay chính giữa sảnh lớn. Không thể nào lầm lẫn vào đâu được. Momokawa Kotarou đang đứng đó, tay cầm một thanh kiếm trơ trọi, tựa như đang muốn đường đường chính chính quyết đấu một mất một còn."}, {"line": 195, "old": "“A-a-a-a, vui quá đi mất, Kotarou-kyun lại chủ động mời gọi tao thế này cơ chứ!”", "new": "“A-a-a-a, sướng quá đi mất, Kotarou-kyun lại chủ động dâng hiến mời gọi tao thế này cơ chứ!”"}, {"line": 197, "old": "Sức sống lại tràn trề trong cơ thể đang đói khát của hắn.", "new": "Sức sống lại sôi trào mãnh liệt trong cơ thể đang khô héo vì đói khát của hắn."}, {"line": 199, "old": "Ôi, không thể chịu nổi nữa rồi. Mọi thứ của cậu phản chiếu trong đôi mắt này đều thật đáng yêu.", "new": "Ôi, không thể nào kìm chế nổi nữa rồi. Mọi đường nét của cậu in trong đôi mắt này đều đáng yêu đến nghẹt thở."}, {"line": 201, "old": "Mái tóc đen mượt mà óng ả. Vẻ đẹp trung tính với đôi mắt như mắt mèo ẩn chứa một nét đẹp vượt qua cả khái niệm giới tính.", "new": "Mái tóc đen mượt mà óng ả. Nét đẹp phi giới tính với đôi mắt mèo ma mị ẩn chứa một vẻ quyến rũ vượt khỏi ranh giới nam nữ thông thường."}, {"line": 203, "old": "Cơ thể nhỏ nhắn, mảnh khảnh như thể đang lưu giữ vĩnh viễn khoảnh khắc kỳ diệu giao thoa giữa một đứa trẻ và một người trưởng thành.", "new": "Vóc dáng nhỏ nhắn, thanh mảnh như thể đang vĩnh viễn lưu giữ khoảnh khắc giao thoa diệu kỳ giữa một đứa trẻ và một thiếu niên trưởng thành."}, {"line": 205, "old": "Chỉ cần nhìn vào chiếc cổ trắng ngần, thon thả lộ ra sau cổ áo học sinh kia thôi cũng đủ khiến hắn nuốt nước bọt ực ực vì thèm thuồng không chịu nổi.", "new": "Chỉ cần nhìn vào chiếc cổ trắng ngần, thon thả lộ ra sau cổ áo đồng phục kia thôi cũng đủ khiến hắn phải ực nước bọt liên hồi vì thèm thuồng đến phát điên."}, {"line": 207, "old": "Hắn cảm nhận được dòng máu nóng hổi đang chảy rần rần, dồn thẳng vào con rắn khổng lồ đầy kiêu hãnh mọc ra từ vùng đáy chậu của mình.", "new": "Hắn cảm nhận rõ mồn một dòng máu nóng hổi đang sùng sục chảy rần rần, dồn thẳng vào con rắn khổng lồ đầy kiêu hãnh đang ngóc đầu dậy từ đũng quần của mình."}, {"line": 211, "old": "Hồi còn ở trong lớp, hắn chỉ nghĩ cậu ta là một thằng lùn tịt bình thường, nhưng giờ đây sao lại quyến rũ đến thế này.", "new": "Hồi còn ở trong lớp, hắn chỉ nghĩ cậu ta là một thằng lùn tịt mờ nhạt, nhưng cớ sao giờ đây lại mê hoặc đến nhường này."}, {"line": 213, "old": "Một thiếu niên đẹp đẽ đến mức thiêng liêng. Khi đã biết xương thịt của cậu ta mang lại khoái cảm tột đỉnh vượt qua mọi mỹ vị trên đời, hắn làm sao có thể kiềm chế được nữa. Cũng chẳng việc gì phải kiềm chế.", "new": "Một thiếu niên đẹp đẽ đến mức thần thánh. Khi đã biết rõ xương thịt của cậu ta sẽ mang lại khoái cảm tột cùng vượt qua mọi mỹ vị nhân gian, làm sao hắn có thể kiềm lòng được nữa. Mà cũng chẳng có lý do gì để phải kiềm chế."}, {"line": 215, "old": "Bởi vì kể từ khoảnh khắc biết đến hương vị của giọt máu đó, hắn sống trên đời này chỉ vì một mục đích duy nhất: ăn thịt Momokawa Kotarou.", "new": "Bởi vì kể từ khoảnh khắc biết đến hương vị của giọt máu đó, hắn tồn tại trên cõi đời này chỉ vì một mục đích tối thượng duy nhất: ăn thịt Momokawa Kotarou."}, {"line": 217, "old": "“Ta... ăn... đây... y-y-y-y-y-y-y-y-y!”", "new": "“Taaaa... ănnn... đâââyyy... y-y-y-y-y-y-y-y-y!”"}, {"line": 219, "old": "Cái miệng đầy răng nanh sắc nhọn cùng đôi càng lớn của Yokomichi há rộng thành một 『Đại Khẩu』 chực chờ ngoạm lấy cơ thể Kotarou.", "new": "Cái miệng lởm chởm răng nanh sắc nhọn cùng đôi càng lớn của Yokomichi banh rộng thành một 『Đại Khẩu』 chực chờ cắn nát ngấu nghiến cơ thể Kotarou."}, {"line": 221, "old": "Không chỉ vậy. Cái đầu giun đất cuối cùng mọc trên đầu hắn cũng đang chực chờ hút lấy dù chỉ một giọt máu, và con rắn khổng lồ dưới háng thì đang lồng lộn như sắp nổ tung.", "new": "Không chỉ có thế. Cái đầu giun đất trồi ra trên đầu hắn cũng há mồm chực chờ hút lấy từng giọt máu tươi, và con rắn khổng lồ dưới háng thì đang lồng lộn như muốn nổ tung."}, {"line": 223, "old": "Không để thoát. Không nhường cho ai hết. Một cảm xúc giống như sự độc chiếm trỗi dậy, hắn dùng cả 6 cánh tay ôm chặt lấy cơ thể mảnh mai kia bằng tất cả sức lực.", "new": "Không để thoát. Tuyệt đối không nhường cho bất kỳ ai. Một dục vọng chiếm hữu điên cuồng bùng cháy, hắn dùng trọn vẹn 6 cánh tay ôm siết lấy thân hình mảnh khảnh kia bằng tất cả bình sinh tàn lực."}, {"line": 225, "old": "Vì hắn lao thẳng vào ôm lấy Kotarou đang thủ thế kiếm, mũi kiếm của cậu đã đâm xuyên qua thân mình hắn, nhưng một nhát kiếm cỏn con như thế giờ đây chẳng đáng để hắn bận tâm.", "new": "Vì hắn lao thẳng vào ôm chầm lấy Kotarou đang trong thế thủ kiếm, mũi kiếm của cậu đã đâm xuyên qua lồng ngực hắn, nhưng một nhát kiếm cỏn con như thế vào lúc này chẳng đáng để hắn bận tâm dù chỉ nửa phần."}, {"line": 227, "old": "Hắn đã ăn được Kotarou rồi.", "new": "Hắn đã ngoạm được Kotarou rồi."}, {"line": 229, "old": "So với sự thật đó, mọi thứ khác đều chỉ là chuyện vặt vãnh—", "new": "So với sự thật ngập tràn đê mê đó, mọi thứ khác đều chỉ là rác rưởi—"}, {"line": 233, "old": "Thứ đầu tiên hắn cảm nhận được là hương vị.", "new": "Thứ đầu tiên đánh thức tri giác của hắn là mùi vị."}, {"line": 235, "old": "Cái gì thế này. Hương vị này giống như thể hắn vừa nhai phải một thứ hoàn toàn không có vị, thậm chí còn chẳng phải là đồ ăn. Yokomichi chợt nhớ lại hồi nhỏ, khi hắn từng cố ăn một món đồ chơi bằng nhựa vì tưởng là đồ ăn thật.", "new": "Cái quái gì thế này? Hương vị này chẳng khác nào hắn vừa nhai phải một thứ hoàn toàn vô vị, thậm chí còn chẳng phải là thực phẩm. Yokomichi chợt nhớ lại hồi còn thơ ấu, khi hắn từng cố nhét một món đồ chơi bằng nhựa vào mồm vì tưởng nhầm là kẹo ngọt."}, {"line": 237, "old": "Rõ ràng... là người thật mà.", "new": "Rõ ràng... là người thật cơ mà."}, {"line": 239, "old": "Hắn đã nhìn thấy con mồi giả làm mồi nhử trước đó. Ngoại hình và mùi hương giống hệt người thật, nhưng vì ma lực quá yếu nên hắn biết đó là giả. Hắn hiểu đó chỉ là một phân thân được tạo ra bằng cách chia sẻ một phần ma lực của bản thể.", "new": "Hắn đã từng nhìn thấy con mồi giả làm bia đỡ đạn trước đó. Ngoại hình và mùi hương giống hệt người thật, nhưng vì ma lực quá đỗi mờ nhạt nên hắn biết tỏng đó là đồ giả. Hắn hiểu đó chỉ là một phân thân được tạo ra bằng cách chia sẻ một phần ma lực ít ỏi từ bản thể."}, {"line": 241, "old": "Chính vì thế, dựa vào lượng ma lực đậm đặc tỏa ra từ Kotarou đang đứng đây, hắn mới khẳng định đây là người thật. Hắn cảm nhận được một lượng ma lực rõ ràng mà phân thân mồi nhử không thể nào có được.", "new": "Chính vì thế, dựa vào lượng ma lực đậm đặc cuồn cuộn tỏa ra từ Kotarou đang đứng sờ sờ ở đây, hắn mới dám đinh ninh đây đích thị là người thật. Hắn cảm nhận được một lượng ma lực rõ mồn một mà phân thân mồi nhử tuyệt đối không thể nào sở hữu."}, {"line": 245, "old": "Đây cũng là giả. Một thứ giống như mô hình đồ ăn giả được làm cực kỳ tinh xảo để mô phỏng món ăn thượng hạng mang tên Kotarou.", "new": "Đây cũng là giả. Một thứ chẳng khác nào mô hình đồ ăn giả bằng sáp được chế tác cực kỳ tinh vi để mô phỏng lại món mỹ vị thượng hạng mang tên Kotarou."}, {"line": 247, "old": "Dù có giống đến mức nào đi nữa, bên trong vẫn là một thứ hoàn toàn khác. Một dị vật thậm chí còn không phải là đồ ăn.", "new": "Dù bề ngoài có giống đến từng chân tơ kẽ tóc, bản chất bên trong vẫn là một thứ hoàn toàn xa lạ. Một dị vật thậm chí còn không được tính là thức ăn."}, {"line": 249, "old": "Dị vật đó bắt đầu tan chảy ra, để lộ lớp vỏ bọc thật sự bên dưới.", "new": "Dị vật đó bắt đầu nhũn ra và tan chảy, để lộ lớp vỏ bọc thật sự ẩn giấu bên dưới."}, {"line": 251, "old": "“Mày là đứa quái nào hả!!!”", "new": "“Mày là con nhãi ranh quái nào hả!!!”"}, {"line": 253, "old": "Gương mặt của thiếu niên tóc đen mắt đen tan chảy, và hiện ra bên dưới là một đứa trẻ tóc bạc mắt xanh như búp bê.", "new": "Gương mặt của thiếu niên tóc đen mắt đen tan biến, và hiện ra bên dưới là một đứa bé gái tóc trắng mắt xanh biếc như búp bê sứ."}, {"line": 255, "old": "Búp bê. Đúng vậy, thứ này là một con búp bê. Trông rất giống con người nhưng tuyệt đối không phải con người, chỉ là một món đồ giả tạo. Một thứ ngụy tạo.", "new": "Búp bê. Đúng vậy, thứ này thực chất là một con rối bùn. Trông thì rất giống con người nhưng tuyệt đối không phải đồng loại, chỉ là một món đồ giả tạo. Một thứ ngụy tạo tinh vi."}, {"line": 259, "old": "Lần này mới là thật. Momokawa Kotarou thật.", "new": "Lần này mới thực sự là hàng thật. Momokawa Kotarou thật sự."}, {"line": 261, "old": "Cậu ta xuất hiện từ bên trong một chiếc hộp lớn nằm lăn lóc ở góc sảnh — một chiếc Rương Kho Báu.", "new": "Cậu ta bước ra từ bên trong một chiếc hòm lớn nằm lăn lóc ở góc sảnh — một chiếc Rương Kho Báu."}, {"line": 263, "old": "Cậu ta đã trốn ở đó. Nếu kẻ giả và kẻ thật đứng cạnh nhau, chắc chắn sẽ bị phát hiện.", "new": "Cậu ta đã ẩn nấp ở đó từ đầu. Nếu kẻ giả và kẻ thật cùng đứng song song, thể nào cũng bị lộ tẩy."}, {"line": 265, "old": "Vì vậy, bản thể thật đã trốn vào trong Rương Kho Báu. Chiếc rương cổ vật có khả năng bảo quản nguyên vẹn mọi thứ từ thời cổ đại cho đến tận ngày nay cũng có khả năng ngăn chặn mọi loại dò tìm từ bên ngoài. Những thứ nằm bên trong Rương Kho Báu sẽ tuyệt đối không bị rò rỉ ma lực hay mùi hương ra ngoài.", "new": "Vì vậy, bản thể thật đã chui tọt vào trong Rương Kho Báu. Chiếc rương cổ vật mang năng lực bảo quản nguyên vẹn mọi vật chất từ thời cổ đại cho đến tận hôm nay cũng đồng thời sở hữu khả năng phong tỏa tuyệt đối mọi loại trinh sát từ bên ngoài. Những thứ nằm bên trong Rương Kho Báu sẽ tuyệt đối không để rò rỉ nửa điểm ma lực hay một chút mùi hương nào ra ngoài."}, {"line": 267, "old": "“———— 『Hắc Phát Phược』.”", "new": "“———— 『Tóc Đen Trói Buộc』.”"}, {"line": 269, "old": "Khoảnh khắc Kotarou thật niệm chú, hàng loạt sợi xích sắt loảng xoảng chuyển động như những con rắn, đồng loạt lao tới trói chặt lấy Yokomichi đang ngoạm lấy con búp bê giả.", "new": "Khoảnh khắc Kotarou thật niệm xong chú văn, hàng loạt sợi xích sắt kêu loảng xoảng lập tức uốn lượn như những con mãng xà, đồng loạt lao vút tới siết chặt lấy Yokomichi đang ngoạm chặt lấy con búp bê thế thân."}, {"line": 271, "old": "Hắn đã từng thấy chiêu thức 『Hắc Phát Phược』 này khi chạm trán trong hầm ngục lần đầu tiên. Đó là một chú thuật điều khiển các lọn tóc đen để trói chặt đối thủ.", "new": "Hắn đã từng chứng kiến chiêu thức 『Tóc Đen Trói Buộc』 này khi chạm trán trong hầm ngục lần đầu tiên. Đó chỉ là một chú thuật tầm thường điều khiển các sợi tóc đen để trói buộc đối thủ."}, {"line": 273, "old": "Vì đó chỉ là những sợi tóc thông thường nên rất dễ bị đốt cháy hoặc giật đứt. Một chiêu trói buộc không đáng bận tâm.", "new": "Bởi vì đó chỉ là những sợi tóc mong manh nên rất dễ bị phóng hỏa thiêu rụi hoặc gồng lực giật đứt. Một thứ trói buộc chẳng đáng để tâm."}, {"line": 275, "old": "Thế nhưng, thứ đang trói chặt Yokomichi lúc này lại là những sợi xích sắt vô cùng kiên cố. Không chỉ vậy, từ những chiếc thắt lưng da dày cho đến những sợi dây thừng được bện chặt, đủ loại vật dụng dạng dây đều đang quấn chặt lấy cơ thể Yokomichi.", "new": "Thế nhưng, thứ đang siết chặt lấy Yokomichi lúc này lại là những sợi xích sắt vô cùng cứng cáp. Không chỉ có xích, từ những chiếc thắt lưng da dày cộp cho đến những sợi dây thừng được bện chặt nhiều lớp, đủ loại vật dụng dạng dây trói đều đang quấn chặt lấy từng tấc thịt trên cơ thể Yokomichi."}, {"line": 277, "old": "Tất nhiên, bí mật đằng sau sự chuyển động đó chính là 『Hắc Phát Phược』.", "new": "Tất nhiên, bí mật đằng sau sự chuyển động kỳ dị đó chính là 『Tóc Đen Trói Buộc』."}, {"line": 279, "old": "Bằng cách quấn những sợi tóc đen có thể tự do điều khiển vào xích sắt và thắt lưng, cậu ta đã khiến chúng chuyển động theo. Nếu bản thân các xúc tu tóc đen không đủ độ bền, chỉ cần dùng các vật thể thực tế để bù đắp là được.", "new": "Bằng cách luồn những sợi tóc đen có thể tự do co giãn, điều khiển vào xích sắt và thắt lưng da, cậu ta đã mượn lực để khiến chúng chuyển động theo ý muốn. Nếu bản thân các sợi tóc đen không đủ độ bền cơ học, chỉ cần gia cố bằng các vật chất thực tế là giải quyết xong vấn đề."}, {"line": 281, "old": "Nhìn kỹ lại thì, đồ đạc trong sảnh lớn này đang bị bày bừa một cách vô cùng phi lý. Dù có vội vàng chạy trốn đi chăng nữa, cũng chẳng có lý do gì để phải cố tình đổ hết hành lý ra sàn nhà như thế này.", "new": "Nhìn kỹ lại thì, đồ đạc trong đại sảnh này đang bị vứt bừa bãi một cách vô cùng phi lý. Dù có vội vã tháo chạy đến đâu đi chăng nữa, cũng chẳng có lý do gì để phải cố tình trút sạch toàn bộ hành lý ra la liệt khắp mặt sàn như thế này."}, {"line": 283, "old": "Chỉ đến khi bị trói chặt thế này, hắn mới nhận ra sự bất thường của những sợi xích, thắt lưng và dây thừng nằm lăn lóc một cách đầy cố ý ở đây.", "new": "Chỉ đến khi bị gông cùm trói chặt thế này, hắn mới muộn màng nhận ra sự bất thường của những sợi xích, thắt lưng và dây thừng nằm lăn lóc một cách đầy toan tính ở đây."}, {"line": 285, "old": "Nhưng dù có chút bất thường đi nữa, trong tình cảnh dồn được con mồi thượng hạng là Kotarou vào đường cùng, lại thêm bản thân đang kiệt quệ sức lực và đói khát tột cùng, việc bắt hắn phải nhận ra điều đó là hoàn toàn bất khả thi.", "new": "Thế nhưng, dẫu có phát giác ra đôi chút bất thường, trong tình cảnh dồn ép được con mồi thượng hạng Kotarou vào ngõ cụt, cộng thêm việc bản thân đang kiệt quệ sinh lực và đói khát đến mờ mắt, việc bắt hắn phải suy xét tỉnh táo là điều hoàn toàn bất khả thi."}, {"line": 287, "old": "Vì vậy, Yokomichi đã hoàn toàn sập bẫy. Bị bắt một cách dễ dàng như một con thú chỉ biết cắm đầu lao về phía trước.", "new": "Bởi vậy, Yokomichi đã hoàn toàn sập bẫy. Bị tóm gọn một cách dễ dàng như một con thú hoang chỉ biết mù quáng cắm đầu lao về phía trước."}, {"line": 291, "old": "Bị bao bọc trong luồng ánh sáng trắng xóa, Yokomichi cuối cùng mới nhận ra rằng nơi mình đang đứng chính là trên một ma pháp trận dịch chuyển.", "new": "Bị nuốt trọn trong luồng ánh sáng trắng xóa rực rỡ, Yokomichi cuối cùng mới bàng hoàng nhận ra rằng nơi mình đang đứng chôn chân chính là tâm điểm của một ma pháp trận dịch chuyển."}]}, {"ep": 283, "title": "Tập 283: Đầu và Cánh tay phải (2)", "filename": "chuong_283_dau_va_canh_tay_phai_2.md", "replaces": 1, "changes": [{"line": 257, "old": "Dựa vào những vết cắn rõ mòn một và độ sâu của vết răng, tôi đoán kẻ đã ăn xác con voi này là một ma vật có kích thước cỡ Grimgoar, nhỏ hơn Rồng đỏ lông vũ Rồng đỏ lông vũ Rồng đỏ lông vũ Rồng đỏ lông vũ Crimson Rex một chút. Nếu là một ma vật khổng lồ cỡ khủng long bạo chúa thì chắc nó đã nuốt chửng cả con hoặc tha xác về tổ rồi.", "new": "Dựa vào những vết cắn rõ mồn một và độ sâu của vết răng, tôi đoán kẻ đã ăn xác con voi này là một ma vật có kích thước cỡ Grimgoar, nhỏ hơn Rồng đỏ lông vũ Crimson Rex một chút. Nếu là một ma vật khổng lồ cỡ khủng long bạo chúa thì chắc nó đã nuốt chửng cả con hoặc tha xác về tổ rồi."}]}, {"ep": 284, "title": "Tập 284: Mèo con", "filename": "chuong_284_am.md", "replaces": 73, "changes": [{"line": 1, "old": "*Ầm!*", "new": "# Tập 284: Mèo con"}, {"line": 2, "old": "Tôi đóng sầm cửa lại.", "new": ""}, {"line": 3, "old": "\"Boss hồi sinh rồi.\"", "new": "Quả nhiên Báo Tuyết Băng là một đối thủ vô cùng đáng gờm."}, {"line": 4, "old": "\"Thật á!? Có Boss á!?\"", "new": ""}, {"line": 5, "old": "\"Vừa mất Yokomichi xong là nó lòi ra liền, đúng là vô tích sự thật.\"", "new": "Nó liên tục phóng ra những mảnh băng sắc nhọn, chiếc đuôi dài vung vẩy tạo ra những lưỡi kiếm băng khổng lồ, và ngay cả những đòn cào hay cắn thông thường cũng kèm theo hiệu ứng đóng băng tại bất cứ nơi nào nó chạm vào. Chưa dừng lại ở đó, từ miệng nó còn có thể phun ra cả luồng hơi thở đông cực giá buốt."}, {"line": 6, "old": "Chà, không ngờ vừa mới hôm qua hôm kia mà hôm nay nó đã hồi sinh rồi.", "new": ""}, {"line": 7, "old": "Nhưng giả thuyết cho rằng ma vật Boss trong phòng Boss được hệ thống triệu hồi của hầm ngục tự động bổ sung là rất cao, nên một khi biến mất thì tất nhiên nó sẽ hồi sinh thôi.", "new": "Uy lực này đúng là tiệm cận cấp Boss. Nếu không có đầy đủ quân số ở đây thì nguy to rồi."}, {"line": 8, "old": "Tôi cứ đinh ninh có lõi của Yokomichi là kích hoạt dịch chuyển ăn sẵn rồi, nên hoàn toàn không nghĩ đến việc phải đánh Boss.", "new": ""}, {"line": 9, "old": "\"Thế giờ tính sao đây, Momokawa?\"", "new": "“Giờ thì xử lý thế nào đây?”"}, {"line": 10, "old": "\"Hayama-kun, cậu nghĩ điểm tốt của một trận chiến với Boss là gì?\"", "new": ""}, {"line": 11, "old": "\"Hả? Thì, ừm... là mọi người có thể cùng nhau chiến đấu?\"", "new": "Con báo tuyết khổng lồ dài chừng 3 mét ngã gục sau khi trúng đòn chí mạng vào yết hầu từ Kyouko. Nó nằm im bất động, chết ngay tức khắc. Nhờ hạ gục mục tiêu bằng một đòn hiểm duy nhất nên phần thân thể còn lại vẫn còn nguyên vẹn."}, {"line": 12, "old": "\"Chính xác.\"", "new": ""}, {"line": 13, "old": "Đúng vậy, Boss luôn ở trong phòng Boss. Vì thế, chúng tôi có thể chuẩn bị vô cùng kỹ lưỡng, và tất cả mọi người có thể cùng nhau khiêu chiến.", "new": "Với khả năng di chuyển linh hoạt, chạy nhảy thoăn thoắt trên nền tuyết dày lẫn trên các nhánh cây, lại cộng thêm sức mạnh của Băng ma thuật, dù chúng tôi có áp đảo về số lượng thì cũng khó lòng tung ra đòn tấn công hiệu quả. Thế nhưng, Alpha đã liều mình lao vào cắn xé quấy nhiễu, tạo thời cơ để tôi thi triển `『Tóc Đen Trói Buộc』` khóa chặt lấy nó."}, {"line": 14, "old": "Điều Hayama nói \"cùng nhau chiến đấu\" nghĩa là chúng tôi có thể tập trung toàn bộ chiến lực.", "new": ""}, {"line": 15, "old": "Hơn nữa, một điểm tốt khác của trận chiến với Boss là chỉ cần tiêu diệt được Boss là xong. Nghĩa là dù có dốc hết toàn bộ chiến lực đã tập trung để hạ gục Boss thì cũng chẳng sao cả.", "new": "Không bỏ lỡ vài giây ngắn ngủi khi con quái thú đang gồng mình chống cự bằng sức mạnh cơ bắp và lưỡi kiếm băng, Kyouko đã tung ra đòn dứt điểm `『Nham Thương』`."}, {"line": 16, "old": "Bởi vì trong tình cảnh hiện tại, chắc chắn không thể có chuyện các bạn học cũ đột kích chúng tôi sau trận chiến với Boss được nữa. Kẻ tình nghi cuối cùng có khả năng tấn công chúng tôi là Yokomichi cũng đã không còn.", "new": ""}, {"line": 17, "old": "\"Vì vậy, chỉ cần dốc toàn lực tiêu diệt Boss là được———— Hayama-kun, nhờ cậu đấy.\"", "new": "Chìa khóa chiến thắng quả nhiên nằm ở ưu thế quân số cùng sự phối hợp nhịp nhàng. Dù không trực tiếp gây sát thương dứt điểm, nhưng nhóm Hayama cũng đã hoàn thành xuất sắc nhiệm vụ bao vây, dồn ép con báo tuyết vào góc chết khiến nó không thể trốn thoát."}, {"line": 18, "old": "\"A... Ra thế. Hì hì, cứ giao cho tớ, Momokawa.\"", "new": ""}, {"line": 19, "old": "Trong thoáng chốc cậu ta có vẻ không hiểu tôi đang nói gì, nhưng ngay sau đó đã nhận ra.", "new": "Nhờ vậy, chúng tôi đã hạ gục thành công con báo tuyết mà không phải chịu bất kỳ tổn thất nào."}, {"line": 20, "old": "Đúng vậy đấy, Hayama. Bởi vì hiện tại, cậu chính là át chủ bài sở hữu hỏa lực mạnh nhất trong tổ đội này mà.", "new": ""}, {"line": 21, "old": "\"Được rồi, lên nào, Kinako, Beniwo! Linh thú hóa!\"", "new": "“Nếu biến nó thành xác sống, e là việc kiểm soát sẽ có phần bất ổn.”"}, {"line": 23, "old": "### Trích xuất thực thể mới:", "new": "Hiện tại, những con rối xác sống mà Rem đang trực tiếp duy trì toàn bộ quyền kiểm soát chỉ có Hắc Kị Sĩ và Alpha. Ngoài ra chỉ có Arachne là được sử dụng khi cần kíp. Dù không phải lúc nào cũng triệu hồi Minotaur nên mức trần kiểm soát vẫn còn dư dả, nhưng nếu nhồi thêm con báo tuyết này vào thì chưa chắc đã kham nổi."}, {"line": 24, "old": "- Nhân vật mới:", "new": ""}, {"line": 25, "old": "  - Koyuki (コユキ): Báo tuyết con (con của Báo Tuyết Băng), được Hayama Ritsuki nhặt về nuôi và đặt tên.", "new": "Dù chưa được kiểm chứng đầy đủ, nhưng đối với những chủng loại ma vật có khả năng sử dụng ma pháp, dung lượng kiểm soát yêu cầu thường cao hơn đáng kể. So với Minotaur vốn chủ yếu thiên về sức mạnh vật lý đơn thuần, một con báo tuyết vận dụng đa dạng các loại Băng ma thuật như thế này chắc chắn đòi hỏi gánh nặng ma lực điều khiển lớn hơn nhiều."}, {"line": 26, "old": "- Thuật ngữ mới:", "new": ""}, {"line": 27, "old": "  - Báo Tuyết Băng (氷のBáo Tuyết / Ice Báo Tuyết): Ma vật cấp Boss ở vùng tuyết, di chuyển linh hoạt, sử dụng đa dạng Băng ma thuật và có hơi thở đông cực.", "new": "Ngược lại, nếu để nó vận hành ở trạng thái tự lập thì hiệu quả chiến đấu cũng chẳng được bao nhiêu. Giống như Loyrops, chỉ dùng vào việc chuyên chở hành lý rồi thỉnh thoảng lao vào húc bừa thì được, chứ ở trạng thái tự lập thì chẳng thể nào phát huy nổi phân nửa thực lực lúc còn sống. Cơ chế tự lập không đồng nghĩa với việc nó sẽ hành động với đầy đủ trí tuệ và kỹ năng như sinh tiền."}, {"line": 28, "old": "  - Vô Đạo Nhất Thức (Vô Đạo Nhất Thức / Vô Đạo Nhất Thức): Cây gậy mới của Momokawa Kotarou, được chế tạo từ 『Đầu Lâu Của Thực Nhân Quỷ』 (Yokomichi Hajime), có khả năng phóng ra các xúc tu đen ngòm để nuốt chửng thịt xương ma vật.", "new": ""}, {"line": 29, "old": "  - Vòng Cổ Của Koyuki (小雪の首輪 / Koyuki's Collar): Vòng cổ da mềm đính viên Băng Tinh Thể nhỏ, chế tạo riêng cho Koyuki để hy sinh tích tụ sức mạnh tinh linh băng.", "new": "Tuy là một nguồn nguyên liệu ma vật cấp Boss vô cùng quý hiếm, nhưng cách xử lý cái xác này quả thực khiến tôi phải đau đầu. Đúng là một nỗi băn khoăn xa xỉ."}, {"line": 30, "old": "  - Linh thú hóa (Linh thú化 / Spirit Beastification): Trạng thái biến hình/tiến hóa của các đồng hành (Kinako, Beniwo) thành Linh thú khổng lồ nhờ kỹ năng Triệu Hoán Linh Thú của Hayama Ritsuki.", "new": ""}, {"line": 31, "old": "- Quy tắc xưng hô mới: Không có (vẫn giữ nguyên).", "new": "“Trước mắt cứ để Rem ghi nhận cấu trúc của nó, rồi rã xác lấy nguyên liệu là tối ưu nhất.”"}, {"line": 32, "old": "- Sự kiện chính:", "new": ""}, {"line": 33, "old": "  - Nhóm Kotarou tiêu diệt thành công Báo Tuyết Băng cấp Boss mà không chịu tổn thất.", "new": "Khi nào thực sự cần mượn đến sức mạnh của báo tuyết, chỉ việc đưa lõi ma vật cho Rem để con bé trực tiếp kiểm soát hoàn toàn, đó có lẽ là phương án tận dụng tốt nhất ở thời điểm hiện tại."}, {"line": 34, "old": "  - Kotarou thử nghiệm cây gậy mới 『Vô Đạo Nhất Thức』 chế tạo từ đầu lâu Yokomichi để nuốt chửng đống xác voi ma mút còn lại.", "new": ""}, {"line": 35, "old": "  - Hayama Ritsuki nhặt được một chú báo tuyết con trong hốc cây và thuyết phục Kotarou cho nuôi, đặt tên là Koyuki.", "new": "Nếu đã vậy thì tốt nhất là cứ vác nguyên cái xác này về rồi thong thả mổ xẻ sau. Tôi không muốn mùi máu tanh tiếp tục vương vãi khắp khu rừng nguy hiểm này thêm nữa."}, {"line": 36, "old": "  - Cả nhóm hoàn tất chuẩn bị trong 4 ngày và tiến vào phòng Boss để xuống tầng sâu nhất, nhưng phát hiện Boss phòng này đã hồi sinh.", "new": ""}, {"line": 37, "old": "  - Hayama Ritsuki chuẩn bị kích hoạt Linh thú hóa cho Kinako và Beniwo để tiêu diệt Boss.", "new": "“Được rồi mọi người, tiếp tục công việc thôi nào. Tớ sẽ cùng Rem xẻ thịt con voi ma mút, Kyouko và Hayama-kun để mắt cảnh giới xung quanh giúp tớ nhé.”"}, {"line": 39, "old": "Kiểm tra lại định dạng JSON và văn phong dịch thuật.", "new": "Nếu những kẻ địch mạnh cỡ con báo tuyết này cứ liên tục kéo đến, hoặc tệ hơn là ập tới cả đàn, thì dù có tiếc đứt ruột tớ cũng đành phải bỏ lại đống nguyên liệu voi ma mút này mà tháo chạy thôi."}, {"line": 40, "old": "Văn phong mượt mà, thuần Việt, đúng các quy tắc xưng hô.", "new": ""}, {"line": 41, "old": "Sử dụng đúng ngoặc kép kiểu Nhật `『...』` cho kỹ năng/vật phẩm.", "new": "May mắn thay, lời cầu nguyện hiếm hoi của tôi đã được đáp lại, suốt quãng thời gian sau đó không hề có thêm cuộc tập kích nào xảy ra. Giữa khu rừng tuyết tĩnh mịch, chỉ còn lại âm thanh lao động tất bật của chúng tôi, thỉnh thoảng điểm xuyết vài tiếng kêu đùa nghịch của Beniwo và Kinako."}, {"line": 42, "old": "Sử dụng đúng ngoặc kép tiếng Việt `“...”` cho lời thoại.", "new": ""}, {"line": 43, "old": "Bố cục đầu ra chuẩn xác.# Tập 284: Mèo con", "new": "Cứ như thế, công đoạn lột da và thu hoạch những phần nguyên liệu đắt giá nhất của voi ma mút đã hoàn tất mỹ mãn. Chúng tôi chất toàn bộ vật phẩm cùng xác con báo tuyết vừa săn được lên lưng Loyrops."}, {"line": 45, "old": "Quả nhiên Báo Tuyết Băng là một đối thủ đáng gờm.", "new": "Thứ còn sót lại phía sau, dù đã vơi đi một nửa, vẫn là một đống thịt và xương cốt khổng lồ."}, {"line": 47, "old": "Nó liên tục phóng ra những mảnh băng sắc nhọn, từ chiếc đuôi dài tạo ra những lưỡi kiếm băng khổng lồ vung vẩy, và ngay cả những đòn cào hay cắn thông thường cũng kèm theo hiệu ứng thuộc tính đóng băng bất cứ nơi nào nó chạm vào. Cuối cùng, nó còn phun ra cả tia đông cực từ miệng.", "new": "Thịt voi ma mút ư? Tôi cũng tò mò muốn nếm thử hương vị của nó ra sao, nhưng thứ thịt đã phơi ngoài trời ròng rã suốt cả ngày trời thế này thì ăn vào chỉ tổ rước họa... Dù trông có hơi lãng phí, song vì chẳng còn giá trị khai thác nguyên liệu nữa nên đành phải bỏ lại thôi... Khoan đã."}, {"line": 49, "old": "Sức mạnh này đúng là ngang tầm Boss. Nếu không có đầy đủ thành viên thì nguy to rồi.", "new": "“À phải rồi, nhân cơ hội này thử nghiệm món đồ mới một chút xem sao.”"}, {"line": 51, "old": "“Giờ thì xử lý thế nào đây?”", "new": "Tôi chĩa đầu cây gậy mới chế tác về phía đống xác voi ma mút còn lại."}, {"line": 53, "old": "Con báo tuyết khổng lồ dài khoảng 3 mét ngã gục sau khi trúng đòn chí mạng vào cổ họng của Kyouko. Nó nằm im bất động, chết ngay lập tức. Nhờ hạ gục bằng một đòn chí mạng vào điểm yếu nên cơ thể nó vẫn còn khá nguyên vẹn.", "new": "“Nào Yokomichi, mồi ngon dâng tận miệng đây, ăn cho thỏa thích đi.”"}, {"line": 55, "old": "Với khả năng di chuyển linh hoạt, chạy nhảy tự do trên tuyết lẫn trên cây, cộng thêm sức mạnh của Băng ma thuật, dù chúng tôi có bao vây đông thế này cũng khó lòng tung ra đòn hiệu quả. Nhưng Alpha đã liều mạng lao vào cắn xé, nhân cơ hội đó tôi dùng `『Hắc Phát Phược』` để trói chặt nó.", "new": "Cây gậy `『Vô Đạo Nhất Thức』` trên tay tôi phát ra những tiếng ma sát lách cách khô khốc, rồi từ từ mở toạc chiếc hàm dị dạng."}, {"line": 57, "old": "Không bỏ lỡ vài giây ngắn ngủi khi nó đang cố thoát khỏi sự kiềm tỏa bằng sức mạnh dã thú và lưỡi kiếm băng, Kyouko đã tung ra đòn quyết định `『Nham Thạch Thương』`.", "new": "Ngay khoảnh khắc tiếp theo, vô số xúc tu đen ngòm, to bản cuồn cuộn phóng ra từ miệng gậy. Đầu của chúng nứt toác thành những cái miệng đỏ lòm lởm chởm răng nanh, điên cuồng lao vào ngấu nghiến đống xác voi ma mút."}, {"line": 59, "old": "Quả nhiên, chìa khóa chiến thắng là số lượng và khả năng phối hợp của chúng tôi. Dù không đóng góp trực tiếp vào lượng sát thương, nhưng nhóm Hayama cũng đã làm rất tốt việc bao vây và dồn con báo tuyết vào góc để nó không thể chạy thoát.", "new": "Những xúc tu tựa như bầy đại xà hung hãn, vừa ngấu nghiến cắn xé, vừa quấn chặt lấy từng tảng thịt khổng lồ rồi từ từ kéo ngược trở lại."}, {"line": 61, "old": "Nhờ vậy, chúng tôi đã hạ gục thành công con báo tuyết mà không chịu bất kỳ tổn thất nào đáng kể.", "new": "Dù tính thế nào thì trọng lượng cơ thể của tôi khi cầm gậy và đống thịt voi ma mút kia cũng hoàn toàn chênh lệch, nhưng kỳ lạ thay, toàn bộ khối xác đồ sộ lại bị các xúc tu kéo lê về phía cây gậy một cách nhẹ nhàng. Bản thân tôi nắm giữ thân trượng cũng không hề cảm nhận phải chịu bất kỳ sức nặng hay phản lực kéo giật nào."}, {"line": 63, "old": "“Nếu biến nó thành xác sống, e là việc kiểm soát sẽ hơi bất ổn nhỉ.”", "new": "Khi đống xác voi ma mút đã bị lôi đến sát tầm với của cây gậy, một ma pháp trận khổng lồ lập tức bừng nở từ đầu trượng, ngay vị trí khảm `『Đầu Lâu Của Thực Nhân Quỷ』`. Trên vòng tròn ma pháp tỏa ra ánh sáng đỏ đen ma mị, một luồng hỗn mang đen ngòm cuộn xoáy dữ dội, thoạt nhìn rất giống cảnh tượng mỗi khi tôi thi triển `『Thi Nhân Hình』`."}, {"line": 65, "old": "Hiện tại, những xác sống mà Rem đang hoàn toàn kiểm soát chỉ có Hắc Kị Sĩ và Alpha. Còn lại chỉ là sử dụng Arachne khi cần thiết. Dù không phải lúc nào cũng triệu hồi Minotaur nên năng lực kiểm soát vẫn còn dư dả, nhưng nếu dùng thêm con báo tuyết này thì không biết có vừa vặn giới hạn hay không.", "new": "Đống xác voi ma mút cứ thế bị bầy xúc tu lôi tuột vào tâm ma pháp trận. Dù là một khối thịt xương khổng lồ vượt xa đường kính của vòng tròn ma pháp, nhưng những xúc tu đang cắn xé ấy đã nghiền nát và nuốt chửng toàn bộ vào trong không gian chứa của cây trượng mà không để sót lại lấy một mảnh vụn."}, {"line": 67, "old": "Tuy việc kiểm chứng chưa hoàn toàn đầy đủ, nhưng với những loại ma vật sử dụng ma pháp, năng lực kiểm soát yêu cầu thường có xu hướng cao hơn. Vì vậy, so với Minotaur chủ yếu thiên về sức mạnh vật lý, con báo tuyết sử dụng đa dạng Băng ma thuật chắc chắn đòi hỏi khả năng kiểm soát cao hơn nhiều.", "new": "***"}, {"line": 69, "old": "Nhưng nếu để nó ở trạng thái tự lập thì cũng không hiệu quả lắm. Giống như Loyrops, chỉ dùng để vận chuyển hành lý và lao vào húc khi cần thiết thì được, chứ ở trạng thái tự lập thì không thể phát huy nổi một nửa chỉ số của báo tuyết. Trạng thái tự lập không có nghĩa là nó sẽ hành động với tư duy và năng lực hoàn toàn giống hệt lúc sinh tiền.", "new": "*Ầm!*"}, {"line": 71, "old": "Là một ma vật cấp Boss vô cùng quý giá, nhưng cách xử lý con báo tuyết này thật đau đầu. Ôi, đúng là một sự đắn đo xa xỉ.", "new": "Tôi đóng sầm cánh cửa lớn lại."}, {"line": 73, "old": "“Trước mắt cứ để Rem ghi nhớ nó, rồi dùng làm nguyên liệu là tốt nhất nhỉ.”", "new": "“Boss hồi sinh rồi.”"}, {"line": 75, "old": "Khi nào cần đến sức mạnh của báo tuyết, chỉ cần đưa lõi cho Rem để em ấy kiểm soát hoàn toàn, đó có lẽ là cách tận dụng tối đa ở thời điểm hiện tại.", "new": "“Thật á!? Có Boss xuất hiện lại rồi á!?”"}, {"line": 77, "old": "Nếu vậy, tốt nhất là cứ mang nguyên xác về rồi từ từ rã xác sau. Tôi không muốn vương vãi mùi máu tanh trong khu rừng nguy hiểm này thêm nữa.", "new": "“Vừa mới tiêu diệt Yokomichi xong là nó lòi ra ngay, đúng là phiền phức thật đấy.”"}, {"line": 79, "old": "“Được rồi, mọi người ơi, tiếp tục công việc thôi. Tớ sẽ cùng Rem rã xác con voi ma mút, Kyouko và Hayama-kun cảnh giới xung quanh giúp tớ nhé.”", "new": "Chà, không ngờ mới chỉ trôi qua có đôi ba ngày mà nó đã tái sinh nhanh đến vậy."}, {"line": 81, "old": "Nếu những kẻ mạnh cỡ con báo tuyết này cứ liên tục tấn công, hoặc kéo đến cả đàn, thì dù là tớ cũng phải từ bỏ đống nguyên liệu voi ma mút này thôi.", "new": "Tuy nhiên, giả thuyết cho rằng ma vật Boss trong phòng Boss sẽ tự động được hệ thống triệu hồi của hầm ngục bổ sung là rất cao, nên một khi kẻ chiếm giữ căn phòng biến mất thì việc nó hồi sinh cũng là lẽ đương nhiên."}, {"line": 83, "old": "Nhưng có vẻ như lời cầu nguyện hiếm hoi của tôi đã được đáp ứng, sau đó không có cuộc tập kích nào nữa. Trong khu rừng tuyết tĩnh lặng, chỉ có tiếng chúng tôi làm việc, thỉnh thoảng xen lẫn tiếng kêu của Beniwo và Kinako.", "new": "Tôi cứ đinh ninh chỉ cần nắm giữ lõi của Yokomichi là có thể kích hoạt trận pháp dịch chuyển ăn sẵn ngay được, nên hoàn toàn không tính đến trường hợp phải đánh Boss thêm một lần nữa."}, {"line": 85, "old": "Cứ thế, công việc lột da và thu thập nguyên liệu voi ma mút đã hoàn thành tốt đẹp. Chúng tôi chất nguyên liệu và xác con báo tuyết vừa hạ lên lưng Loyrops.", "new": "“Thế giờ tính sao đây, Momokawa?”"}, {"line": 87, "old": "Thứ còn lại phía sau, dù đã mất một nửa, vẫn là một lượng thịt và xương khổng lồ.", "new": "“Hayama-kun, cậu nghĩ điểm thuận lợi lớn nhất của một trận chiến trong phòng Boss là gì?”"}, {"line": 89, "old": "Thịt voi ma mút à, tôi cũng muốn ăn thử xem sao, nhưng để ngoài trời cả ngày trời rồi mới ăn thì hơi... Dù thấy hơi lãng phí, nhưng vì không còn giá trị nguyên liệu nữa nên đành phải bỏ lại thôi... Khoan đã.", "new": "“Hả? Thì, ừm... là tất cả mọi người có thể cùng nhau hợp lực chiến đấu?”"}, {"line": 91, "old": "“À phải rồi, nhân cơ hội này thử nghiệm chút xem sao.”", "new": "“Chính xác.”"}, {"line": 93, "old": "Tôi hướng cây gậy mới về phía đống xác voi ma mút còn lại.", "new": "Đúng vậy, Boss luôn cố định ở bên trong phòng Boss. Vì thế, chúng tôi hoàn toàn có thể chuẩn bị sách lược vô cùng kỹ lưỡng, và tất cả mọi người có thể đồng loạt xông vào khiêu chiến."}, {"line": 95, "old": "“Nào Yokomichi, mồi ngon đây, ăn cho thỏa thích đi.”", "new": "Điều Hayama nói “cùng nhau chiến đấu” đồng nghĩa với việc chúng tôi có thể dồn toàn bộ chiến lực tinh nhuệ nhất vào một mục tiêu."}, {"line": 97, "old": "Cây gậy `『Vô Đạo Nhất Thức』` trên tay tôi phát ra những tiếng lách cách, mở ra chiếc hàm dị dạng.", "new": "Hơn nữa, một điểm tuyệt vời khác của trận chiến với Boss là chỉ cần tiêu diệt được mục tiêu duy nhất đó là xem như kết thúc. Nghĩa là dù có phải dốc cạn toàn bộ át chủ bài và ma lực để đè bẹp Boss trong một lượt thì cũng chẳng có vấn đề gì."}, {"line": 99, "old": "Ngay khoảnh khắc tiếp theo, những xúc tu đen ngòm, to bản phóng ra từ miệng gậy. Đầu của chúng mở toác ra những chiếc miệng đỏ lòm lởm chởm răng nanh, liên tục lao vào đống xác voi ma mút.", "new": "Bởi lẽ trong hoàn cảnh hiện tại, chắc chắn không thể có chuyện đám bạn học cũ bất ngờ phục kích chúng tôi sau trận chiến được nữa. Kẻ tình nghi cuối cùng có khả năng tập kích chúng tôi là Yokomichi cũng đã bị xóa sổ hoàn toàn."}, {"line": 101, "old": "Những xúc tu như những con đại xà vừa ngấu nghiến cắn xé, vừa quấn chặt lấy khối thịt khổng lồ rồi từ từ kéo lại gần.", "new": "“Vì vậy, chúng ta chỉ cần dốc toàn lực nghiền nát con Boss là xong———— Trận này nhờ cả vào cậu đấy, Hayama-kun.”"}, {"line": 103, "old": "Dù nghĩ thế nào thì trọng lượng của tôi đang cầm gậy và đống thịt voi ma mút cũng không hề cân bằng, nhưng thật kỳ lạ, đống xác lại bị các xúc tu kéo lê về phía cây gậy. Bản thân tôi khi cầm gậy lại không hề cảm thấy sức nặng hay phản lực nào.", "new": "“A... Ra là vậy! Hì hì, cứ giao hết cho tớ, Momokawa!”"}, {"line": 105, "old": "Khi đống xác voi ma mút đã đến đủ gần tầm với của cây gậy, một ma pháp trận khổng lồ mở ra từ đầu gậy, nơi khảm `『Đầu Lâu Của Thực Nhân Quỷ』`. Trên vòng tròn ma pháp tỏa ra ánh sáng đỏ đen ma mị, một luồng hỗn mang đen ngòm cuộn xoáy, trông rất giống lúc tôi thi triển `『Thi Nhân Hình』`.", "new": "Trong thoáng chốc, cậu ta có vẻ chưa hiểu hết hàm ý của tôi, nhưng ngay sau đó đã lập tức thông suốt."}, {"line": 107, "old": "Đống xác voi ma mút cứ thế bị các xúc tu kéo tuột vào trong ma pháp trận. Rõ ràng đó là một khối thịt xương khổng lồ hơn hẳn đường kính của ma pháp trận, nhưng những xúc tu đang cắn xé", "new": "Đúng thế đấy, Hayama. Bởi vì ở thời điểm hiện tại, cậu chính là quân bài tẩy sở hữu hỏa lực bộc phá mạnh nhất trong tổ đội này."}]}, {"ep": 294, "title": "Tập 294: Chiến dịch thâm nhập chung (2)", "filename": "chuong_294_chien_dich_tham_nhap_chung_2.md", "replaces": 63, "changes": [{"line": 3, "old": "Chà, thật sự là may mắn khi Natsukawa gia nhập nhóm. Không ngờ lại có thể xâm nhập vào tận vương cung một cách dễ dàng thế này.", "new": "Chà, đúng là may mắn khi Natsukawa-san gia nhập nhóm. Không ngờ chúng tôi lại có thể xâm nhập vào tận sâu bên trong vương cung một cách dễ dàng đến thế này."}, {"line": 5, "old": "Hiện tại, chúng tôi đang ẩn nấp ở phía trên trần nhà của đại sảnh nơi đặt sáu phiến đá cổ. Đây là một lối đi ẩn chật hẹp giống như đường ống thông gió mà ngay cả lũ Goma cũng không hề hay biết.", "new": "Hiện tại, chúng tôi đang ẩn nấp ở phía trên trần nhà của đại sảnh — nơi đặt sáu phiến đá cổ. Đây là một lối đi ẩn chật hẹp giống như đường ống thông gió mà ngay cả lũ Goma cũng chẳng hề hay biết."}, {"line": 7, "old": "Việc chúng tôi xâm nhập được vào vương cung là nhờ Natsukawa đã nhanh chóng phát hiện ra các lối đi ẩn, và đường ống này cũng do chính cô ấy tìm ra.", "new": "Việc thâm nhập thành công vào vương cung hoàn toàn là nhờ công của Natsukawa-san với khả năng phát hiện các lối đi bí mật cực nhanh, và đường ống này cũng do chính cô ấy tìm ra."}, {"line": 9, "old": "Cô ấy nói rằng di tích này dường như vẫn còn hoạt động rất tốt, và cô cảm nhận được vô số cơ quan cạm bẫy ở đẳng cấp hoàn toàn khác biệt so với những nơi khác. Nhờ vậy, chúng tôi đã phát hiện ra một lượng lớn lối đi và cửa ẩn.", "new": "Cô ấy bảo rằng di tích này dường như vẫn còn hoạt động rất tốt, và cảm nhận được vô số cơ quan cạm bẫy ở đẳng cấp hoàn toàn khác biệt so với những nơi khác. Nhờ thế, chúng tôi đã lần ra được hàng loạt lối đi và cửa ẩn."}, {"line": 11, "old": "Nếu tận dụng triệt để những lối đi này, chúng tôi có thể an toàn khám phá bên trong vương cung, bất chấp việc lính canh được bố trí dày đặc và cảnh giác nghiêm ngặt khắp nơi. Có quá nhiều điểm mù mà kẻ địch không hề hay biết thế này thì đúng là một \"tựa game siêu dễ\" rồi.", "new": "Nếu tận dụng triệt để những tuyến đường bí mật này, chúng tôi có thể thoải mái khám phá vương cung mà chẳng lo chạm trán lính canh đang tuần tra dày đặc khắp nơi. Có quá nhiều điểm mù mà kẻ địch không hề hay biết thế này thì đúng là một \"tựa game chế độ siêu dễ\" rồi."}, {"line": 13, "old": "“Momokawa-kun, cậu có thể khai thác được thông tin gì từ những phiến đá xếp hàng kia không?”", "new": "“Momokawa-kun, cậu có thể trích xuất được thông tin gì từ những phiến đá xếp hàng kia không?”"}, {"line": 15, "old": "“Nếu truy cập được vào đó, chắc chắn sẽ có gì đó. Đây là lần đầu tiên tớ thấy các phiến đá được bố trí như vậy, có khi nó giống như một phòng máy chủ...”", "new": "“Nếu chạm tay vào đó thì chắc chắn sẽ ra được gì đó thôi. Đây là lần đầu tiên tớ thấy các phiến đá được bố trí thành hàng dài như vậy, có khi nó đóng vai trò như một phòng máy chủ cũng nên...”"}, {"line": 17, "old": "Trong lúc hé mở cửa ẩn trên trần nhà để quan sát đại sảnh vắng người, tiếng bước chân nặng nề cùng tiếng nói chuyện ồn ào bỗng vang lên từ phía cổng lớn. Nín thở, chúng tôi tiếp tục dán mắt theo dõi.", "new": "Trong lúc hé mở khe cửa ẩn trên trần nhà để quan sát đại sảnh vắng người, tiếng bước chân nặng nề cùng những âm thanh ồn ào bỗng vang lên từ phía cổng lớn. Nín thở, chúng tôi dán mắt theo dõi động tĩnh phía dưới."}, {"line": 19, "old": "Kẻ đầu tiên xuất hiện là một tên Gove già nua nhăn nheo với bộ râu trắng xóa, đi bên cạnh là một tên Gove khác khoác trên mình bộ giáp mũ sặc sỡ. Hóa ra ngoài Oh-ma ra, tộc Goma vẫn còn những lão già khú đế như thế này sao. Còn gã mặc giáp kia thì trông cũng không có gì quá đặc biệt.", "new": "Kẻ đầu tiên xuất hiện là một tên Gove già nua nhăn nheo với bộ râu trắng xóa, đi bên cạnh là một tên Gove khác khoác trên mình bộ giáp nón sặc sỡ. Hóa ra ngoài Oh-ma ra, tộc Goma vẫn còn những lão già khú đế như thế này. Còn gã mặc giáp kia thì trông cũng không có gì quá nổi bật."}, {"line": 21, "old": "Cả hai trông đều giống Gove, nhưng hành động cúi chào đầy cung kính của những con GoGame Mastera gác cổng đã chứng minh địa vị cao quý của chúng. Có lẽ chúng cũng tương tự như tên Gove tướng mà tôi từng dùng chiến thuật MPK (dẫn quái giết người) để tiêu diệt trong trận chiến với Yokomichi.", "new": "Cả hai thoạt nhìn đều giống Gove, nhưng hành động cúi chào đầy cung kính của những con Gogma gác cổng đã chứng minh địa vị cao quý của chúng. Có lẽ chúng cũng tương đương với tên Gove chỉ huy mà tôi từng dùng chiến thuật kéo quái để tiêu diệt trong trận chiến với Yokomichi."}, {"line": 23, "old": "Mang theo bầu không khí kiêu ngạo đó, hai tên Goma đi thẳng vào giữa đại sảnh... rồi thản nhiên ngồi phịch lên phiến đá cổ.", "new": "Mang theo bầu không khí ngạo mạn đó, hai tên Goma sải bước vào giữa đại sảnh... rồi thản nhiên ngồi phịch lên phiến đá cổ."}, {"line": 25, "old": "Đúng là lũ Goma. Chúng dám coi một thiết bị thông tin cổ đại là ghế ngồi. Đúng là lũ đần độn, gọi chúng là lũ dã man xem ra vẫn còn là một lời khen.", "new": "Đúng là lũ Goma dã man. Dám coi một thiết bị lưu trữ thông tin cổ đại làm ghế ngồi. Lũ đần độn này, gọi chúng là man di xem ra vẫn còn là một lời khen ngợi."}, {"line": 29, "old": "Dù tôi vẫn không hiểu tiếng Goma, nhưng...", "new": "Dù tôi vẫn chẳng hiểu nổi thứ ngôn ngữ của loài Goma, nhưng..."}, {"line": 35, "old": "“Làm sao tớ hiểu được chứ.”", "new": "“Làm sao tớ hiểu nổi chứ.”"}, {"line": 37, "old": "Trong đợt thâm nhập này, tôi đã dành rất nhiều thời gian để \"luyện nghe\" các cuộc hội thoại hàng ngày của lũ Goma.", "new": "Trong đợt thâm nhập này, tôi đã dành rất nhiều thời gian để \"luyện nghe\" các cuộc hội thoại thường nhật của lũ Goma."}, {"line": 39, "old": "Không phải chỉ nghe tai này lọt tai kia theo kiểu mấy phương pháp học ngoại ngữ thần tốc, tôi đã phân tích chúng một cách cực kỳ nghiêm túc... Thế nhưng, dù có suy luận thế nào thì lũ này vẫn phát âm những từ có cùng ý nghĩa bằng những âm thanh hoàn toàn khác biệt.", "new": "Không phải chỉ nghe lướt tai theo mấy phương pháp học ngoại ngữ cấp tốc, tôi đã phân tích chúng một cách cực kỳ nghiêm túc... Thế nhưng, dù có suy luận thế nào thì lũ này vẫn phát âm những từ có cùng một ý nghĩa bằng các âm thanh hoàn toàn khác nhau."}, {"line": 41, "old": "Khi rình mò ở khu chợ một lúc, tôi nhận ra đối với những giao dịch trao đổi vật phẩm của lũ Goma kém thông minh này, nội dung chắc chắn sẽ quanh đi quẩn lại mấy thứ giống nhau, và ít nhất các từ liên quan đến mua bán phải xuất hiện với tần suất cao. Thế nhưng, nếu chỉ dựa vào phát âm đơn thuần, tôi hầu như không tìm thấy bất kỳ điểm tương đồng nào.", "new": "Lúc rình mò ở khu chợ, tôi nhận ra đối với các giao dịch trao đổi vật phẩm của lũ Goma kém thông minh này, nội dung chắc chắn chỉ quanh đi quẩn lại vài thứ đơn giản, và ít nhất các từ liên quan đến mua bán phải xuất hiện với tần suất rất cao. Thế nhưng, nếu chỉ dựa vào phát âm đơn thuần, tôi hầu như không tìm thấy bất kỳ điểm tương đồng nào."}, {"line": 43, "old": "Cụ thể, một chủ tiệm Goma khi chỉ vào tấm da thú thương phẩm có thể nói là \"Gabaa\" hoặc \"Gebaa\", nhưng kẻ khác lại gọi là \"Zongara\" hay \"Buzadoo\", cùng vô số cách gọi kỳ lạ khác. Thật sự không thể hiểu nổi. Tôi không tin là vốn từ vựng chỉ một tấm da thú lại phong phú đến thế, và các đồ vật khác cũng gặp tình trạng tương tự.", "new": "Cụ thể, một chủ tiệm Goma khi chỉ vào tấm da thú thương phẩm có thể nói là \"Gabaa\" hoặc \"Gebaa\", nhưng kẻ khác lại gọi là \"Zongara\" hay \"Buzadoo\", cùng vô số cách gọi kỳ quặc khác. Thật sự không tài nào hiểu nổi. Tôi không tin vốn từ vựng chỉ một tấm da thú của chúng lại phong phú đến thế, và các đồ vật khác cũng gặp tình trạng tương tự."}, {"line": 45, "old": "Có lẽ bản thân phát âm của tiếng Goma không hề mang ý nghĩa. Rất có thể chúng hiểu nhau qua cao độ, âm vực, hoặc những tần số âm thanh mà tai người không thể nào phân biệt được.", "new": "Có lẽ bản thân phát âm của tiếng Goma không hề chứa đựng ý nghĩa. Rất có thể chúng hiểu nhau qua cao độ, âm vực, hoặc những tần số âm thanh mà tai người bình thường không thể nào phân biệt được."}, {"line": 47, "old": "Vì vậy, dù tôi có cố gắng ghi chép lại lời chúng nói rồi đối chiếu phát âm với ý nghĩa đến thế nào đi nữa thì cũng chỉ hoài công. Bởi lẽ, đối với thính giác của con người, những âm thanh phát ra từ miệng chúng hoàn toàn vô nghĩa.", "new": "Vì vậy, dù tôi có cố gắng ghi chép lại rồi đối chiếu phát âm với ý nghĩa đến đâu đi nữa thì cũng chỉ phí công vô ích. Bởi lẽ, đối với thính giác của con người, những âm thanh phát ra từ miệng chúng hoàn toàn vô nghĩa."}, {"line": 49, "old": "“But, không hiểu sao, riêng tên của chúng thì tớ lại nghe ra được.”", "new": "“Nhưng không hiểu sao, riêng tên của chúng thì tớ lại nghe ra được.”"}, {"line": 51, "old": "Đúng vậy, chỉ riêng tên gọi của lũ Goma là một ngoại lệ kỳ lạ. Nhờ thế, tôi có thể nghe rõ mồn một khi chúng gọi nhau là \"Jijigogo\" và \"Bandon\", từ đó biết được danh tính của hai tên này.", "new": "Đúng vậy, chỉ riêng tên gọi của lũ Goma là một ngoại lệ kỳ lạ. Nhờ thế, tôi có thể nghe rõ mồn một khi chúng gọi nhau là \"Jijigogo\" và \"Bandon\", từ đó nắm được danh tính của hai tên này."}, {"line": 53, "old": "And số lượng kẻ sở hữu tên riêng trong chủng tộc này rất hạn chế. Chúng chắc chắn là những cá thể đặc biệt có tên (Named), sở hữu địa vị cao quý đến mức khiến lũ GoGame Mastera cũng phải cúi đầu.", "new": "Hơn nữa, số lượng kẻ sở hữu tên riêng trong chủng tộc này rất hạn chế. Chúng chắc chắn là những cá thể đặc biệt có tên, nắm giữ địa vị cao quý đến mức khiến lũ Gogma cũng phải cúi đầu phủ phục."}, {"line": 55, "old": "Nếu vậy, khả năng cao hai tên này cũng là những Gira-GoGame Mastera giống như Zagan.", "new": "Nếu vậy, khả năng cao hai tên này cũng là những 『Gira-Gogma』 giống như Zagan."}, {"line": 59, "old": "Đúng như lời Natsukawa, có thêm ba tên Gove nữa bước vào đại sảnh.", "new": "Đúng như lời Natsukawa-san, có thêm ba tên Gove nữa bước vào đại sảnh."}, {"line": 61, "old": "Kẻ đi đầu với những bước sải dài là một tên Gove bán khỏa thân, chỉ đeo một chiếc vòng cổ bằng vàng và quấn độc một mảnh khố màu đỏ tươi. Hắn sở hữu thân hình vạm vỡ, cơ bắp cuồn cuộn đặc trưng của loài Gove, nhưng điểm gây chú ý nhất chính là những hình xăm màu đỏ rực chằng chịt khắp cơ thể. Tôi không nghĩ đó chỉ là sở thích làm đẹp đơn thuần. Chắc chắn những hoa văn đó đóng vai trò như một dạng ma pháp trận. Bởi lẽ, tôi có thể nhận ra một vài ký tự Goma quen thuộc được khắc lẫn trong đó.", "new": "Kẻ đi đầu với những bước sải dài là một tên Gove bán khỏa thân, chỉ đeo một chiếc vòng cổ bằng vàng và quấn độc một mảnh khố màu đỏ tươi. Hắn sở hữu thân hình vạm vỡ, cơ bắp cuồn cuộn đặc trưng của loài Gove, nhưng điểm gây chú ý nhất chính là những hình xăm màu đỏ rực chằng chịt khắp cơ thể. Tôi không nghĩ đó chỉ là sở thích làm đẹp đơn thuần. Chắc chắn những hoa văn đó đóng vai trò như một dạng ma pháp trận. Bởi lẽ, tôi có thể nhận ra một vài ký tự Goma quen thuộc được khắc lẫn bên trong."}, {"line": 65, "old": "Dù vẫn có cơ bắp của loài Gove, nhưng cơ thể hắn lại thuộc kiểu gầy guộc săn chắc. Hắn khoác một chiếc áo choàng rộng thùng thình phanh ngực, rất có thể thuộc nhóm ma thuật sư.", "new": "Dù vẫn có cơ bắp của loài Gove, nhưng cơ thể hắn lại thuộc kiểu gầy gò săn chắc. Hắn khoác một chiếc áo choàng rộng thùng thình phanh ngực, rất có thể thuộc nhóm ma thuật sư."}, {"line": 67, "old": "Kẻ thứ ba đi cuối cùng là một gã có kích thước lỡ cỡ, khó mà phân biệt được là Gove hay GoGame Mastera. Nhìn thoáng qua, hắn có thân hình hộ pháp như một võ sĩ Sumo giống lũ GoGame Mastera, nhưng kích thước lại nhỏ hơn hẳn. Dẫu vậy, nếu so với một tên Gove thông thường, hắn vẫn cao hơn đến hai cái đầu.", "new": "Kẻ thứ ba đi cuối cùng là một gã có kích thước lỡ cỡ, khó mà phân biệt được là Gove hay Gogma. Nhìn thoáng qua, hắn có thân hình hộ pháp như một võ sĩ Sumo giống lũ Gogma, nhưng kích thước lại nhỏ hơn hẳn. Dẫu vậy, nếu so với một tên Gove thông thường, hắn vẫn cao hơn đến hai cái đầu."}, {"line": 73, "old": "Đặc biệt là gã xăm đỏ kia, hắn nói rất to và ồn ào. Dù không hiểu ngôn ngữ của chúng, tôi vẫn có thể nhận ra hắn đang cố hết sức để ra oai, tinh tướng với lão già và gã mặc giáp đến trước.", "new": "Đặc biệt là gã xăm đỏ kia, hắn nói rất to và huyên náo. Dù không hiểu ngôn ngữ của chúng, tôi vẫn có thể nhận ra hắn đang cố hết sức để ra oai, làm phách với lão già và gã mặc giáp đến trước."}, {"line": 79, "old": "“Đừng có nhìn tớ với vẻ mặt ái ngại thế chứ, đáng lẽ cậu phải khen tớ một câu thật lòng mới đúng.”", "new": "“Đừng có nhìn tớ với vẻ mặt ái ngại thế chứ, đáng lẽ cậu phải khen ngợi tớ một câu thật lòng mới đúng.”"}, {"line": 81, "old": "Thật là, tôi đã phải cố gắng hết sức để lắng nghe thứ ngôn ngữ Goma bẩn thỉu chói tai đó chỉ để thu thập chút thông tin hữu ích, vậy mà lại bị đối xử thế này.", "new": "Thật tình, tôi đã phải vắt kiệt sức lực để lắng nghe thứ ngôn ngữ Goma bẩn thỉu chói tai đó chỉ để thu thập chút thông tin hữu ích, vậy mà lại bị nhìn bằng ánh mắt kỳ thị thế này."}, {"line": 91, "old": "Ngoại hình của hắn không có quá nhiều khác biệt so với loài Gove, chỉ là có phần to lớn hơn một chút.", "new": "Ngoại hình của hắn không có quá nhiều khác biệt so với loài Gove, chỉ là có phần to lớn và bệ vệ hơn một chút."}, {"line": 93, "old": "Tuy nhiên, chiếc áo choàng khoác trên cơ thể vạm vỡ đầy hình xăm, kết hợp với những chiếc lông vũ trang trí sặc sỡ cùng trang sức bằng vàng và đá quý lấp lánh, tạo nên một vẻ ngoài lộng lẫm chỉ xếp sau mỗi Vua Oh-ma. Chỉ riêng trang phục thôi cũng đủ để khẳng định địa vị tối cao của hắn... nhưng hơn cả thế, bản thân tên Gove đó tỏa ra một luồng áp lực và sức mạnh thâm sâu khôn lường.", "new": "Tuy nhiên, chiếc áo choàng khoác trên cơ thể vạm vỡ đầy hình xăm, kết hợp với những chiếc lông vũ trang trí sặc sỡ cùng trang sức bằng vàng và đá quý lấp lánh, tạo nên một vẻ ngoài lộng lẫy chỉ xếp sau mỗi Vua Oh-ma. Riêng trang phục thôi cũng đủ để khẳng định địa vị tối cao của hắn... nhưng hơn cả thế, bản thân tên Gove đó tỏa ra một luồng áp lực và sức mạnh thâm sâu khôn lường."}, {"line": 95, "old": "Không sai vào đâu được. Hắn chính là kẻ đứng đầu lũ đang có mặt ở đây.", "new": "Không sai vào đâu được. Hắn chính là kẻ đứng đầu đám quái vật đang có mặt ở đây."}, {"line": 101, "old": "“— Nhìn kìa Natsukawa-san, đúng là một cuộc họp ban điều hành của phe địch.”", "new": "“— Nhìn kìa Natsukawa-san, đúng chuẩn một cuộc họp cán bộ cấp cao của phe địch luôn.”"}, {"line": 103, "old": "“Họp ban điều hành phe địch?”", "new": "“Họp cán bộ cấp cao phe địch?”"}, {"line": 105, "old": "“Là kiểu các thủ lĩnh cấp cao của kẻ thù tụ họp lại, rồi thảo luận với vẻ mặt vô cùng nghiêm trọng ấy. Cậu chưa từng thấy cảnh này trong manga bao giờ à?”", "new": "“Là kiểu các thủ lĩnh đầu sỏ của kẻ thù tụ họp lại, rồi thảo luận với vẻ mặt vô cùng nghiêm trọng ấy. Cậu chưa từng thấy cảnh này trong manga bao giờ à?”"}, {"line": 109, "old": "“Mà thôi kệ đi. Dù sao thì, qua chuyện này chúng ta đã biết được vương quốc này có tổng cộng sáu tên 『Gira-GoGame Mastera』 mạnh nhất... và quả nhiên, tên kia chính là 『Zagan』.”", "new": "“Mà thôi kệ đi. Dù sao thì, qua chuyện này chúng ta đã biết được vương quốc này có tổng cộng sáu tên 『Gira-Gogma』 mạnh nhất... và quả nhiên, tên kia chính là 『Zagan』.”"}, {"line": 113, "old": "Zagan, kẻ thủ ác đã sát hại Nakai và Nonomiya theo lời kể của mọi người. Lũ Goma kia liên tục gọi tên thủ lĩnh của chúng là “Zagan”. Mà thực ra, ngay cả khi chúng không gọi tên, Natsukawa cũng đã từng chạm trán hắn trước đây nên chỉ cần nhìn thoáng qua là cô ấy nhận ra ngay lập tức.", "new": "Zagan — kẻ thủ ác đã sát hại Nakai và Nonomiya theo lời kể của mọi người. Lũ Goma kia liên tục gọi tên thủ lĩnh của chúng là “Zagan”. Mà thực ra, ngay cả khi chúng không gọi tên, Natsukawa-san cũng đã từng chạm trán hắn trước đây nên chỉ cần nhìn thoáng qua là cô ấy nhận ra ngay lập tức."}, {"line": 115, "old": "Dù vậy, việc tôi có thể trực tiếp tận mắt chứng kiến diện mạo của Zagan — kẻ đáng gờm nhất ở đây — quả là một sự may mắn lớn. Hơn thế nữa, việc xác nhận được năm tên còn lại đều thuộc chủng tộc 『Gira-GoGame Mastera』 cũng là một thu hoạch khổng lồ.", "new": "Dù vậy, việc tôi có thể trực tiếp tận mắt chứng kiến diện mạo của Zagan — kẻ đáng gờm nhất ở đây — quả là một thu hoạch lớn. Hơn thế nữa, việc xác nhận được năm tên còn lại đều thuộc chủng tộc 『Gira-Gogma』 cũng là một tin tức vô cùng giá trị."}, {"line": 117, "old": "Vì chúng có thể nói chuyện ngang hàng với Zagan, khả năng cao tất cả đều là 『Gira-GoGame Mastera』. Dù phán đoán này có sai lệch đi chăng nữa, thì lũ này chắc chắn cũng không thể nào là hạng tép riu được.", "new": "Vì chúng có thể nói chuyện ngang hàng với Zagan, khả năng cao tất cả đều là 『Gira-Gogma』. Dù phán đoán này có sai lệch đi chăng nữa, thì lũ này chắc chắn cũng chẳng phải hạng tép riu."}, {"line": 125, "old": "Ba kẻ còn lại là Zagan, Jijigogo và Bandon tiếp tục trò chuyện với vẻ mặt nghiêm túc thêm một lúc nữa, rồi cũng nhanh chóng đứng dậy rời khỏi phòng.", "new": "Ba kẻ còn lại là Zagan, Jijigogo và Bandon tiếp tục trò chuyện với vẻ mặt nghiêm nghị thêm một lúc nữa, rồi cũng nhanh chóng đứng dậy rời phòng."}, {"line": 131, "old": "Việc tận mắt chứng kiến dàn thủ lĩnh cấp cao dưới trướng Zagan quả là một sự may mắn ngoài ý muốn, nhưng mục tiêu ban đầu của tôi vẫn là thu thập thông tin từ các phiến đá cổ.", "new": "Việc tận mắt chứng kiến dàn thủ lĩnh cấp cao dưới trướng Zagan quả là một sự may mắn ngoài dự tính, nhưng mục tiêu ban đầu của tôi vẫn là thu thập thông tin từ các phiến đá cổ."}, {"line": 139, "old": "Ra dấu tay cái như muốn nói \"cứ tin ở tớ\", tôi bám theo chiếc thang dây được tạo ra từ chú thuật 『Hắc Phát Phược』, nhẹ nhàng đáp xuống nền đá của đại sảnh.", "new": "Ra dấu ngón tay cái như muốn nói \"cứ tin ở tớ\", tôi bám theo chiếc thang dây được dệt từ chú thuật 『Tóc Đen Trói Buộc』, nhẹ nhàng đáp xuống nền đá của đại sảnh."}, {"line": 141, "old": "Vì lũ Goma thường xuyên sử dụng nơi này làm phòng họp thường nhật nên chắc chắn không có cạm bẫy nào được kích hoạt. Natsukawa cũng đã dò quét kỹ lưỡng khu vực này từ trước.", "new": "Vì lũ Goma thường xuyên sử dụng nơi này làm phòng họp nên chắc chắn không có cạm bẫy nào được kích hoạt. Natsukawa-san cũng đã dò quét kỹ lưỡng khu vực này từ trước."}, {"line": 145, "old": "“Nào, để xem có thông tin quý giá nào ẩn giấu ở đây không đây...”", "new": "“Nào, để xem có thông tin quý giá nào ẩn giấu ở đây...”"}, {"line": 151, "old": "“Không có gì đâu, tớ cũng nhờ có Momokawa-kun mới biết được những thông tin ghi trên phiến đá mà.”", "new": "“Không có gì đâu, tớ cũng nhờ có Momokawa-kun mới hiểu được những thông tin ghi trên phiến đá mà.”"}, {"line": 155, "old": "Natsukawa thực sự đã giúp đỡ tôi rất nhiều. Không chỉ ở việc phát hiện các lối đi ẩn, mà khả năng cảm nhận hiện diện cực kỳ nhạy bén cùng tài tìm kiếm sơ ở để lách qua tầm mắt kẻ địch của cô ấy phải nói là ở đẳng cấp thần sầu. Với năng lực này, cô ấy hoàn toàn có thể trở thành một 『Đạo Tặc』 huyền thoại có thể đột nhập vào bất kỳ nơi nào trên thế giới. Tôi tuyệt đối không bao giờ muốn phải đối đầu với cô ấy với tư cách kẻ thù.", "new": "Natsukawa-san thực sự đã giúp đỡ tôi rất nhiều. Không chỉ ở việc phát hiện các lối đi ẩn, mà khả năng cảm nhận hiện diện cực kỳ nhạy bén cùng tài tìm kiếm sơ hở để lách qua tầm mắt kẻ địch của cô ấy phải nói là ở đẳng cấp thần sầu. Với năng lực này, cô ấy hoàn toàn có thể trở thành một 『Đạo Tặc』 huyền thoại có thể đột nhập vào bất kỳ nơi nào trên thế giới. Tôi tuyệt đối không bao giờ muốn phải đối đầu với cô ấy với tư cách kẻ thù."}, {"line": 159, "old": "“Rắc rối thật đấy, cảnh vệ bên ngoài nghiêm ngặt quá mức rồi.”", "new": "“Rắc rối thật đấy, lính gác bên ngoài nghiêm ngặt quá mức rồi.”"}, {"line": 161, "old": "Hiện tại, chúng tôi đang tạm thời ẩn náu trong một căn phòng ẩn nhỏ nằm ở một góc của pháo đài. Nằm ở độ cao tương đương với một tòa nhà năm tầng, đây là một vị trí đắc địa giúp chúng tôi có thể phóng tầm mắt quan sát toàn bộ quang cảnh bên trong pháo đài cũng như thị trấn trải dài phía dưới qua khe hở của một ô cửa sổ ẩn.", "new": "Hiện tại, chúng tôi đang tạm thời ẩn náu trong một căn phòng bí mật nhỏ nằm ở một góc của pháo đài. Nằm ở độ cao tương đương với một tòa nhà năm tầng, đây là vị trí đắc địa giúp chúng tôi có thể phóng tầm mắt quan sát toàn bộ quang cảnh bên trong pháo đài cũng như thị trấn trải dài phía dưới qua khe hở của một ô cửa sổ ẩn."}, {"line": 163, "old": "Thế nhưng, đập vào mắt chúng tôi lúc này là cảnh tượng lũ lính Goma đang đi tuần tra với số lượng và tần suất dày đặc, hoàn toàn vượt trội so với ba ngày trước.", "new": "Thế nhưng, đập vào mắt chúng tôi lúc này là cảnh tượng lũ lính Goma đang tuần tra với số lượng và tần suất dày đặc, hoàn toàn vượt trội so với ba ngày trước."}, {"line": 167, "old": "“Đúng vậy, hành tung của chúng ta đã bị bọn chúng phát hiện từ lâu rồi mà...”", "new": "“Đúng vậy, hành tung của chúng ta đã bị bọn chúng phát hiện từ trước rồi mà...”"}, {"line": 177, "old": "Theo lời kể của Natsukawa, pháo đài cổ đại mà bọn họ rút vào sau khi nhốt năm người kia ở ngoài có vẻ cực kỳ tiện nghi và thoải mái. Sự đầy đủ về nhu yếu phẩm cũng như điều kiện sinh hoạt ở đó thậm chí còn vượt xa cả Học Viện Tháp mà chúng tôi đã phải đổ bao mồ hai xương máu để gầy dựng... Khốn kiếp thật, Takanashi, quả nhiên tớ không thể để cô ta sống yên ổn được. Lòng đố kỵ của tớ đang bùng cháy dữ dội đây này.", "new": "Theo lời kể của Natsukawa-san, pháo đài cổ đại mà bọn họ rút vào sau khi nhốt năm người kia ở ngoài có vẻ cực kỳ tiện nghi và thoải mái. Sự đầy đủ về nhu yếu phẩm cũng như điều kiện sinh hoạt ở đó thậm chí còn vượt xa cả Học Viện Tháp mà chúng tôi đã phải đổ bao mồ hôi xương máu để gầy dựng... Khốn kiếp thật, Takanashi, quả nhiên tớ không thể để cô ta sống yên ổn được. Lòng đố kỵ của tớ đang bùng cháy dữ dội đây này."}, {"line": 179, "old": "Tuy nhiên, nếu họ vẫn đang ở trong một môi trường khép kín và an toàn như vậy, thì trước mắt Mei sẽ không bị Takanashi làm hại và mọi chuyện vẫn giữ nguyên hiện trạng. Nếu ả ta muốn ra tay loại bỏ ai đó, chắc chắn phải đợi đến lúc họ rời khỏi pháo đài để bắt đầu tiến hành chinh phục các tầng tiếp theo.", "new": "Tuy nhiên, nếu họ vẫn đang ở trong một môi trường khép kín và an toàn như vậy, thì trước mắt Mei-chan sẽ không bị Takanashi làm hại và mọi chuyện vẫn giữ nguyên hiện trạng. Nếu ả ta muốn ra tay loại bỏ ai đó, chắc chắn phải đợi đến lúc họ rời khỏi pháo đài để bắt đầu tiến hành chinh phục các tầng tiếp theo."}, {"line": 185, "old": "Dù Natsukawa có tài giỏi đến đâu, nhưng một khi kẻ địch không để lộ bất kỳ sơ hở nào thì cô cũng đành bó tay. Trừ phi sở hữu thiết bị ngụy trang tàng hình như mấy gã quái thú ngoài hành tinh thích đi săn trong phim ảnh, bằng không chẳng ai có thể thoát khỏi sự giám sát tuyệt đối bằng mắt thường của lũ lính canh.", "new": "Dù Natsukawa-san có tài giỏi đến đâu, nhưng một khi kẻ địch không để lộ bất kỳ sơ hở nào thì cô cũng đành bó tay. Trừ phi sở hữu thiết bị ngụy trang tàng hình như mấy gã quái thú ngoài hành tinh trong phim viễn tưởng, bằng không chẳng ai có thể thoát khỏi sự giám sát trực diện bằng mắt thường của lũ lính canh."}, {"line": 189, "old": "Nếu chỉ đối phó với khoảng ba tên đi lẻ, sự phối hợp giữa tôi và Natsukawa hoàn toàn có thể tiễn chúng lên đường mà không kịp hé răng nửa lời. Thế nhưng, số lượng lính tuần tra đi theo nhóm nhỏ như vậy hiện tại chỉ là thiểu số.", "new": "Nếu chỉ đối phó với khoảng ba tên đi lẻ, sự phối hợp giữa tôi và Natsukawa-san hoàn toàn có thể tiễn chúng lên đường mà không kịp hé răng nửa lời. Thế nhưng, số lượng lính tuần tra đi theo nhóm nhỏ như vậy hiện tại chỉ là thiểu số."}, {"line": 195, "old": "“Thật là, cứ hễ có chuyện là cậu lại đùn đẩy hết việc lên kế hoạch cho tớ...”", "new": "“Thật tình, cứ hễ có chuyện là cậu lại đùn đẩy hết việc lên kế hoạch cho tớ...”"}, {"line": 197, "old": "*But được người khác tin tưởng thế này cảm giác cũng không tệ chút nào. Chà chà, quả nhiên không có mình thì mọi chuyện chẳng đâu vào đâu cả mà. (Vẻ mặt đắc ý).*", "new": "*Nhưng được người khác tin tưởng thế này cảm giác cũng không tệ chút nào. Chà chà, quả nhiên không có mình thì mọi chuyện chẳng đâu vào đâu cả mà.*"}, {"line": 209, "old": "Nhân loại bình thường có trí tuệ, khả năng tư duy, trí tưởng tượng và năng lực phán đoán tiệm cận với con người chỉ có thể là dàn thủ lĩnh cấp cao — lũ Gira-GoGame Mastera. Còn lũ GoGame Mastera thông thường tuy là những cá thể mạnh mẽ, nhưng điểm thuộc tính của chúng đã dồn hết vào sức mạnh chiến đấu rồi, tôi có quan sát thế nào cũng chẳng tìm ra được chút dấu vết của sự thông minh nào ở chúng. Cùng lắm, bọn chúng chỉ biết tuyệt đối phục tùng những kẻ có đẳng cấp cao hơn mình mà thôi.", "new": "Những kẻ có trí tuệ, khả năng tư duy, trí tưởng tượng và năng lực phán đoán tiệm cận với con người chỉ có thể là dàn thủ lĩnh cấp cao — lũ Gira-Gogma. Còn lũ Gogma thông thường tuy là những cá thể mạnh mẽ, nhưng chỉ số của chúng đã dồn hết vào sức mạnh chiến đấu rồi, tôi có quan sát thế nào cũng chẳng tìm ra được chút dấu vết thông minh nào ở chúng. Cùng lắm, bọn chúng chỉ biết tuyệt đối phục tùng những kẻ có đẳng cấp cao hơn mình mà thôi."}, {"line": 215, "old": "Thế nhưng, một khi đối thủ của chúng là một con người mang đầy ác ý, kẻ sẵn sàng vắt kiệt trí óc để bày mưu hãm hại đối phương, thì mọi chuyện sẽ hoàn toàn khác... Ta sẽ cho lũ sinh vật hạ đẳng các ngươi nếm trải sự đáng sợ của con người là thế nào.", "new": "Thế nhưng, một khi đối thủ của chúng là một con người mang đầy ác ý, kẻ sẵn sàng vắt kiệt trí óc để bày mưu hãm hại đối phương, thì mọi chuyện sẽ hoàn toàn khác... Ta sẽ cho lũ sinh vật hạ đẳng các ngươi nếm trải sự đáng sợ của con người."}, {"line": 261, "old": "Bản thân Zagan vốn không mấy bận tâm đến những thứ trang phục hay vẻ ngoài để thể hiện địa vị của mình. Ông sở hữu lối suy nghĩ điển hình của một chiến binh thực thụ: chỉ cần có đủ trang bị để ra trận là được.", "new": "Bản thân Zagan vốn không mấy bận tâm đến những thứ trang phục hay vẻ ngoài để thể hiện địa vị của mình. Chàng sở hữu lối suy nghĩ điển hình của một chiến binh thực thụ: chỉ cần có đủ trang bị để ra trận là được."}, {"line": 305, "old": "“— Abracadabra (『Hắc Phát Phược』).”", "new": "“— 『Tóc Đen Trói Buộc』.”"}, {"line": 313, "old": "“Fuu, gigu, goburazuga (Phù, cậu mà hét lên là rắc rối lắm đấy).”", "new": "“Fuu, gigu, goburazuga (Phù, cô mà hét lên là rắc rối lắm đấy).”"}]}, {"ep": 295, "title": "Tập 295: Chiến dịch xâm nhập chung (3)", "filename": "chuong_295_chien_dich_xam_nhap_chung_3.md", "replaces": 17, "changes": [{"line": 5, "old": "Trên đường hướng tới xưởng rèn, vì có một con Goma cái đứng ở vị trí bắt buộc phải loại bỏ, tôi đã định ra tay nhanh gọn như một kẻ sát nhân qua đường, nhưng không hiểu sao cây độc châm lại bị nảy ra.", "new": "Trên đường hướng tới xưởng rèn, vì có một con Goma cái đứng ở vị trí bắt buộc phải loại bỏ, tôi đã định ra tay nhanh gọn như một kẻ sát nhân qua đường, nhưng không hiểu sao cây độc châm lại bị nảy ngược ra ngoài."}, {"line": 9, "old": "Dù sức cánh tay của tôi có yếu đuối đến mức nào đi nữa, cũng không lý nào lại không đâm thủng được da của một con Goma bằng cây độc châm sắc nhọn này.", "new": "Dù lực tay của tôi có yếu đuối đến mức nào đi nữa, cũng vô lý hết sức nếu không đâm thủng được da của một con Goma bằng cây độc châm sắc nhọn này."}, {"line": 13, "old": "Trước mắt, tôi phải nhanh chóng dọn dẹp nó đã. Nguyên nhân thì đáng tò mò thật, nhưng cứ để sau hãy nghĩ.", "new": "Trước mắt, tôi phải nhanh chóng dọn dẹp nó đã. Nguyên nhân thì đáng tò mò thật, nhưng cứ để sau hãy tính."}, {"line": 15, "old": "Thế là, tôi lấy lại tinh thần và đâm mạnh một phát.", "new": "Thế là, tôi lấy lại tư thế và đâm mạnh thêm một phát."}, {"line": 17, "old": "“Tặc lưỡi, vẫn bị nảy ra. Hửm, cảm giác này giống kết giới của Sakura-chan ghê... Ồ, xuyên qua rồi.”", "new": "“Chậc, vẫn bị nảy ra. Hửm, cảm giác này giống kết giới của Sakura-chan ghê... Ồ, xuyên qua rồi.”"}, {"line": 19, "old": "Sau một hồi đâm liên tục nghe tiếng cành cạch, cây độc châm cuối cùng cũng cắm phập vào một cách trơn tru. Cảm giác xuyên qua da thịt truyền lại y hệt như những lần tôi hạ gục lũ Goma cản đường trước đây.", "new": "Sau một hồi đâm liên tục nghe tiếng cành cạch, cây độc châm cuối cùng cũng cắm phập vào một cách trơn tru. Cảm giác mũi kim xuyên qua da thịt truyền lại y hệt như những lần tôi hạ gục lũ Goma cản đường trước đây."}, {"line": 23, "old": "Nhìn xác con Goma lặng lẽ chết vì trúng độc trong lúc bọt máu phun ra như thường lệ, tôi nhanh chóng kiểm tra để tìm ra chân tướng của lớp phòng ngự bí ẩn kia. Hóa ra chẳng có gì to tát, sợi dây chuyền mà con Goma cái này đeo trên cổ chính là một vật phẩm ma pháp thuộc hệ phòng ngự.", "new": "Nhìn cái xác con Goma lặng lẽ chết vì trúng độc trong lúc bọt máu sùi ra như thường lệ, tôi nhanh chóng kiểm tra để tìm ra chân tướng của lớp phòng ngự bí ẩn kia. Hóa ra chẳng có gì to tát, sợi dây chuyền mà con Goma cái này đeo trên cổ chính là một vật phẩm ma pháp thuộc hệ phòng ngự."}, {"line": 25, "old": "Khác với khả năng giảm một lượng sát thương cố định như `『Nhẫn Phòng Ngự』` được tích hợp trên bộ đồng phục cường hóa của tôi, loại này có vẻ như vô hiệu hóa hoặc giảm nhẹ đòn tấn công theo số lần giới hạn. Vì vậy, chỉ cần tôi đâm liên tục liên hồi, hiệu ứng của nó sẽ cạn kiệt và kim độc có thể xuyên qua.", "new": "Khác với khả năng giảm trừ một lượng sát thương cố định như 『Nhẫn Phòng Ngự』 được tích hợp trên bộ đồng phục cường hóa của tôi, loại này có vẻ như vô hiệu hóa hoặc giảm nhẹ đòn tấn công theo số lần giới hạn. Vì vậy, chỉ cần tôi đâm dồn dập liên hồi, hiệu ứng của nó sẽ cạn kiệt và kim độc có thể xuyên qua."}, {"line": 27, "old": "“Chỉ là một con cái bình thường mà cũng được cho mang vật phẩm ma pháp... Được yêu chiều gớm nhỉ.”", "new": "“Chỉ là một con cái bình thường mà cũng được cho mang vật phẩm ma pháp... Được cưng chiều gớm nhỉ.”"}, {"line": 29, "old": "Nhìn bộ quần áo màu trắng không một vết bẩn này là đủ hiểu nó có địa vị rất cao trong số các con cái. Chắc hẳn là phu nhân hoặc tiểu thư của một tên tai to mặt lớn nào đó rồi.", "new": "Nhìn bộ quần áo màu trắng không một vết bẩn này là đủ hiểu ả có địa vị rất cao trong số các con cái. Chắc hẳn là phu nhân hoặc tiểu thư của một tên tai to mặt lớn nào đó rồi."}, {"line": 31, "old": "Mà, sao cũng được. Giai cấp của lũ Goma, nếu không liên quan đến sức mạnh thì hoàn toàn chẳng có giá trị gì với chúng tôi cả. Lũ tận hưởng vinh hoa phú quý trong vương cung hay lũ đang chờ chết ở bãi phế thải, tất cả đều nên chết đi thì hơn. Goma tốt chỉ có Goma đã chết.", "new": "Mà, sao cũng được. Giai cấp của lũ Goma, nếu không liên quan đến sức mạnh chiến đấu thì hoàn toàn chẳng có chút giá trị nào với chúng tôi cả. Lũ tận hưởng vinh hoa phú quý trong vương cung hay lũ đang chờ chết ở bãi phế thải, tất cả đều nên chết đi thì hơn. Goma tốt chỉ có Goma đã chết."}, {"line": 35, "old": "Lần này tôi không có thời gian để phi tang xác chết, nên cái xác của con Goma cái này chắc chắn sẽ sớm bị phát hiện. Để đỡ gây chú ý, tôi dùng tóc đen quấn chặt lấy nó, rồi dùng `『Hư Ảnh』` ngụy trang thành một đống rác rưởi rồi vứt đại vào ven đường hẻm.", "new": "Lần này tôi không có thời gian để phi tang xác chết, nên cái xác của con Goma cái này chắc chắn sẽ sớm bị phát hiện. Để đỡ gây chú ý, tôi dùng tóc đen quấn chặt lấy nó, rồi dùng 『Hư Ảnh』 ngụy trang thành một đống rác rưởi rồi vứt đại vào ven đường hẻm."}, {"line": 59, "old": "Xưởng rèn này có một nửa là tận dụng lại kiến trúc từ di tích cổ. Phần di tích đã bị phá hủy một nửa, nên họ chỉ sử dụng phần tường và một phần trần nhà. Những phần còn lại được bổ sung bằng những bức tường đá thô sơ do lũ Goma tự xây dựng, hoặc các công trình bằng gỗ.", "new": "Xưởng rèn này có một nửa là tận dụng lại kiến trúc từ di tích cổ. Phần di tích đã bị phá hủy phân nửa, nên họ chỉ sử dụng phần tường và một phần trần nhà. Những phần còn lại được bổ sung bằng những bức tường đá thô sơ do lũ Goma tự xây dựng, hoặc các công trình bằng gỗ."}, {"line": 117, "old": "Hét lên câu thoại kinh điển mà bất kỳ thằng con trai nào cũng muốn nói một lần trong đời, tôi đá văng các thùng dầu xuống khỏi xe đẩy. Khi các thùng dầu lăn lông lốc vào giữa xưởng đúc————tôi lập tức kích hoạt `『Hắc Phát Phược』`.", "new": "Hét lên câu thoại kinh điển mà bất kỳ thằng con trai nào cũng muốn nói một lần trong đời, tôi đá văng các thùng dầu xuống khỏi xe đẩy. Khi các thùng dầu lăn lông lốc vào giữa xưởng đúc————tôi lập tức kích hoạt 『Tóc Đen Trói Buộc』."}, {"line": 119, "old": "Từ những ma pháp trận được vẽ sẵn trên nắp thùng, vô số sợi tóc đen của `『Hắc Phát Phược』` bung ra. Những sợi tóc đen xuất hiện ngay lập tức giật tung nắp thùng, khiến lượng dầu chứa đầy bên trong bắn tung tóe khắp nơi.", "new": "Từ những ma pháp trận được vẽ sẵn trên nắp thùng, vô số sợi tóc đen của 『Tóc Đen Trói Buộc』 bung ra. Những sợi tóc đen xuất hiện ngay lập tức giật tung nắp thùng, khiến lượng dầu chứa đầy bên trong bắn tung tóe khắp nơi."}, {"line": 151, "old": "Tôi dồn sức tung thêm một đòn `『Hắc Phát Phược』` bồi vào.", "new": "Tôi dồn sức tung thêm một đòn 『Tóc Đen Trói Buộc』 bồi vào."}, {"line": 219, "old": "Kể từ khi tiến hóa thành Gira-GoGame Mastera, anh chưa từng gặp phải một trận chiến nào khiến bản thân cảm nhận được cái chết cận kề. Mang trên mình niềm kiêu hãnh và trách nhiệm của kẻ mạnh nhất vương quốc, Zagan đã đối đầu với mọi ma vật hùng mạnh nhất.", "new": "Kể từ khi tiến hóa thành Gira-Gogma, anh chưa từng gặp phải một trận chiến nào khiến bản thân cảm nhận được cái chết cận kề. Mang trên mình niềm kiêu hãnh và trách nhiệm của kẻ mạnh nhất vương quốc, Zagan đã đối đầu với mọi ma vật hùng mạnh nhất."}]}, {"ep": 299, "title": "Chương 299: Kẻ diệt khổng lồ (1)", "filename": "chuong_299_chuong_299_ke_diet_khong_lo_1.md", "replaces": 110, "changes": [{"line": 5, "old": "“Cậu sao thế đột ngột vậy, Kotarou?”", "new": "“Cậu sao thế, đột ngột vậy, Kotarou?”"}, {"line": 9, "old": "Không hề tỏ ra nghi ngờ khi tôi đột nhiên hét lên, Kyouko lập tức hành động ngay. Sự phối hợp nhịp nhàng này khiến tôi cảm nhận được mối quan hệ sâu sắc giữa hai đứa.", "new": "Không hề tỏ ra nghi ngờ khi tôi đột nhiên thốt lên, Kyouko lập tức hành động ngay. Sự phối hợp nhịp nhàng này khiến tôi cảm nhận được mối liên kết sâu sắc giữa hai đứa."}, {"line": 11, "old": "Để mặc Kyouko đi gọi mọi người, tôi gọi Rem đứng bên cạnh rồi trải tấm bản đồ lên chiếc bàn lớn ở Quảng trường Tinh Linh giống như hôm nọ. Tuy nhiên, tấm bản đồ lần này không phải của Vương quốc Goma, mà là bản đồ toàn bộ khu vực tầng sâu nhất này.", "new": "Để mặc Kyouko đi gọi mọi người, tôi gọi Rem đang đứng bên cạnh rồi trải tấm bản đồ lên chiếc bàn lớn ở Quảng trường Tinh Linh giống như hôm nọ. Tuy nhiên, tấm bản đồ lần này không phải của riêng Vương quốc Goma, mà là bản đồ toàn bộ khu vực tầng sâu nhất."}, {"line": 21, "old": "Dù ai nấy đều nói năng tự do theo ý mình, nhưng chưa đầy năm phút, toàn bộ các bạn học đã tập hợp đông đủ. Như thường lệ, tôi đứng ở vị trí chủ tọa của buổi họp lớp, nhìn lướt qua mọi người rồi tuyên bố:", "new": "Dù ai nấy đều bàn tán tự do theo ý mình, nhưng chưa đầy năm phút, toàn bộ các bạn học đã tập hợp đông đủ. Như thường lệ, tôi đứng ở vị trí chủ tọa của buổi họp lớp, đưa mắt nhìn lướt qua mọi người rồi tuyên bố:"}, {"line": 23, "old": "“Chúng ta chuẩn bị đi tiêu diệt một con Gira-GoGame Mastera.”", "new": "“Chúng ta chuẩn bị đi tiêu diệt một con Gira-Gogma.”"}, {"line": 27, "old": "“Này. Gira-GoGame Mastera... là tên Zagan đó sao?”", "new": "“Này... Gira-Gogma... là tên Zagan đó sao?”"}, {"line": 29, "old": "“Không, là một đứa khác.”", "new": "“Không, là một tên khác.”"}, {"line": 31, "old": "Thế nên trước tiên cậu cứ bình tĩnh đã, Yoshizaki. Dù là một nữ sinh cấp ba xinh đẹp thừa sức làm mẫu ảnh tạp chí, nhưng ánh mắt cô ấy lúc này hoàn toàn là của một chiến binh đã thề sẽ phục thù. Thôi đi mà, bộ cậu định làm Rambo đồ sát Zagan như phim Hollywood chắc!", "new": "Thế nên trước tiên cậu cứ bình tĩnh đã, Yoshizaki. Dù là một nữ sinh cấp ba xinh đẹp thừa sức làm mẫu ảnh tạp chí, nhưng ánh mắt cô ấy lúc này hoàn toàn là của một chiến binh đã thề sẽ phục thù. Thôi đi mà, bộ cậu định hóa thân thành Rambo đồ sát Zagan như phim Hollywood chắc!"}, {"line": 35, "old": "Trước hết, hệ thống cảnh giác của chúng đã trở nên nghiêm ngặt hơn. Nhờ vậy, tôi chỉ có thể trốn trong lối đi bí mật của phòng máy chủ hoàng cung mà hầu như không thể nhúc nhích.", "new": "Trước hết, hệ thống cảnh giác của chúng đã trở nên nghiêm ngặt hơn rất nhiều. Nhờ vậy, tôi chỉ có thể ẩn nấp trong lối đi bí mật của phòng máy chủ vương cung mà hầu như không thể nhúc nhích."}, {"line": 37, "old": "Việc thu thập thông tin hoàn toàn phải dựa vào đội Rem chim. Từ trên trời, chúng tôi chỉ có thể nắm bắt được những chuyển động đại khái của bọn chúng.", "new": "Việc thu thập thông tin hoàn toàn phải dựa vào đội Rem chim. Từ trên bầu trời, chúng tôi chỉ có thể nắm bắt được những chuyển động đại khái của bọn chúng."}, {"line": 39, "old": "Tuy nhiên, tên Oh-ma đó, dù chắc chắn chưa phát hiện ra trò cải trang Goma của tôi là giả, nhưng rõ ràng hắn đang bắt đầu cuộc điều tra dựa trên giả định rằng có kẻ đang giả dạng Goma. Hắn ra lệnh cho toàn bộ binh lính trong pháo đài phải tháo mũ giáp để lộ mặt, đồng thời cấm tiệt lũ Goma sống trong thành phố đội mũ hay trùm khăn che mặt.", "new": "Tuy nhiên, tên Oh-ma đó, dù chắc chắn chưa phát hiện ra thuật cải trang Goma của tôi là giả, nhưng rõ ràng hắn đang bắt đầu cuộc điều tra dựa trên giả định rằng có kẻ đang giả dạng đồng loại. Hắn ra lệnh cho toàn bộ binh lính trong pháo đài phải tháo mũ giáp để lộ mặt, đồng thời cấm tiệt lũ Goma sống trong thành phố đội mũ hay trùm khăn che đầu."}, {"line": 45, "old": "Tất nhiên, tôi luôn cho Rem chim bám sát các đội tìm kiếm. Không chỉ vị trí của chúng, tôi còn ghi chép lại cẩn thận phạm vi những nơi chúng đã lục soát từ trước đến nay.", "new": "Tất nhiên, tôi luôn cho Rem chim bám sát các đội tìm kiếm. Không chỉ vị trí của chúng, tôi còn ghi chép lại cẩn thận phạm vi những nơi chúng từng lục soát từ trước đến nay."}, {"line": 47, "old": "Vì vậy, sau vụ khủng bố xưởng rèn và màn đại náo của Zagan, tôi cũng biết việc các đội tìm kiếm tạm thời rút lui và trở về Vương quốc. Dù không thể trực tiếp xác nhận do bị kẹt ở hoàng cung, nhưng chắc chắn các Gira-GoGame Mastera dẫn đầu các đội đã yết kiến Oh-ma và nhận được mệnh lệnh mới. Sự thay đổi lần này chính là kết quả của việc đó.", "new": "Vì vậy, sau vụ phá hoại xưởng rèn và màn đại náo của Zagan, tôi cũng nắm được việc các đội tìm kiếm tạm thời rút lui và trở về Vương quốc. Dù không thể trực tiếp xác nhận do bị kẹt ở vương cung, nhưng chắc chắn các Gira-Gogma dẫn đầu các đội đã yết kiến Oh-ma và nhận được mệnh lệnh mới. Sự thay đổi lần này chính là kết quả của việc đó."}, {"line": 49, "old": "“Trong số ba đội tìm kiếm, đội của Bazuzu và đội của Gizagins rõ ràng đã bắt đầu lục soát lại khu vực lân cận Vương quốc mà chúng từng tìm kiếm trước đây.”", "new": "“Trong số ba đội tìm kiếm, đội của Bazuzu và đội của Gizaginzu rõ ràng đã bắt đầu lục soát lại khu vực lân cận Vương quốc mà chúng từng tìm kiếm trước đây.”"}, {"line": 51, "old": "Cho đến nay, chuyển động của các đội tìm kiếm vẫn theo kiểu tự nhiên, tức là lấy Vương quốc làm trung tâm rồi dần dần mở rộng ra bên ngoài.", "new": "Cho đến nay, chuyển động của các đội tìm kiếm vẫn diễn ra theo kiểu tuần tự, tức là lấy Vương quốc làm trung tâm rồi dần dần mở rộng bán kính ra bên ngoài."}, {"line": 53, "old": "Dù lũ Goma có ngốc đến mấy thì chúng cũng phải biết mình đã tìm đến đâu rồi chứ. Nếu tái khởi động cuộc tìm kiếm, lẽ ra chúng phải tìm ở những nơi xa Vương quốc hơn... thế nhưng chúng lại không chịu rời khỏi khu vực xung quanh Vương quốc.", "new": "Dù lũ Goma có ngốc đến mấy thì chúng cũng phải biết mình đã sục sạo đến đâu rồi chứ. Nếu tái khởi động cuộc tìm kiếm, lẽ ra chúng phải tìm ở những nơi xa Vương quốc hơn... thế nhưng chúng lại không chịu rời khỏi khu vực xung quanh thành phố."}, {"line": 55, "old": "“Nhưng riêng đội của Bon thì lại đang di chuyển ra rất xa Vương quốc. Chúng không hề tìm kiếm chúng ta, mà rõ ràng đang đi thẳng băng về một điểm đến ở đằng xa.”", "new": "“Nhưng riêng đội của Bon thì lại đang di chuyển ra rất xa Vương quốc. Chúng không hề tìm kiếm chúng ta, mà rõ ràng đang hành quân thẳng tắp về một điểm đến ở đằng xa.”"}, {"line": 57, "old": "“Này này, không lẽ tung tích của tụi mình đã bị lộ rồi chứ?!”", "new": "“Này này, không lẽ tung tích của tụi mình đã bị lộ rồi sao?!”"}, {"line": 59, "old": "“Không có chuyện đó đâu, Hayama-kun. Nếu lộ thì chúng đã tràn xuống đường hầm ngầm từ lâu rồi.”", "new": "“Không có chuyện đó đâu, Hayama-kun. Nếu lộ thì chúng đã tràn xuống đường hầm ngầm này từ lâu rồi.”"}, {"line": 65, "old": "Nói thẳng ra, hắn ta đang đi đâu tôi cũng không quan tâm lắm. Điều quan trọng là chỉ có duy nhất một đội này bắt đầu di chuyển ra xa. Đây chính là hành động mà tôi đã chờ đợi.", "new": "Nói thẳng ra, hắn ta đang đi đâu tôi cũng không bận tâm lắm. Điều quan trọng là chỉ có duy nhất một đội này bắt đầu tách lẻ ra xa. Đây chính là thời cơ mà tôi đã dày công chờ đợi."}, {"line": 71, "old": "Con rồng đỏ bay phun lửa, một con Salamander mang đậm phong cách rồng thần thoại. Tất nhiên tôi cũng biết nó đang bay lượn ở khu vực tầng sâu nhất này. Một con quái vật khổng lồ như thế bay trên trời thì có muốn không chú ý cũng không được.", "new": "Con rồng đỏ bay phun lửa, một con Salamander mang đậm dáng dấp loài rồng thần thoại. Tất nhiên tôi cũng biết nó đang bay lượn ở khu vực tầng sâu nhất này. Một con quái vật khổng lồ như thế sải cánh trên trời thì có muốn không chú ý cũng chẳng được."}, {"line": 73, "old": "Và sự hiện diện của Salamander có lẽ cũng là một kẻ thù phiền toái đối với tộc Goma.", "new": "Và sự hiện diện của Salamander ắt hẳn là cái gai trong mắt tộc Goma."}, {"line": 75, "old": "Salamander dường như làm tổ trên đỉnh ngọn núi sừng sững ở rìa phía Tây khu vực—một ngọn núi có hình dáng vuông vức đến kỳ lạ, chắc chắn là nhân tạo.", "new": "Salamander dường như làm tổ trên đỉnh ngọn núi sừng sững ở rìa phía Tây khu vực—một ngọn núi có hình dáng vuông vức đến kỳ lạ, chắc chắn là công trình nhân tạo."}, {"line": 77, "old": "Có lẽ chúng muốn gửi đội quân do Gira-GoGame Mastera Bon dẫn đầu đến để nhanh chóng tiêu diệt nó trước khi nó kịp sinh sôi. Đối với Salamander, Vương quốc Goma chẳng khác nào một bãi săn mồi béo bở. Bức tường thành kiên cố kia cũng trở nên vô dụng trước một con rồng bay lượn trên bầu trời.", "new": "Có lẽ chúng muốn phái đội quân do Gira-Gogma Bon dẫn đầu đến để nhanh chóng trừ khử nó trước khi nó kịp sinh sôi. Đối với Salamander, Vương quốc Goma chẳng khác nào một bãi săn mồi béo bở. Bức tường thành kiên cố kia cũng hoàn toàn vô dụng trước một con rồng thống trị bầu trời."}, {"line": 79, "old": "Tôi cũng đã tìm hiểu kỹ rồi, ở đó không hề có chức năng ma pháp phòng thủ phòng không hoành tráng nào kiểu như triển khai kết giới quy mô lớn cả.", "new": "Tôi cũng đã tìm hiểu kỹ rồi, ở đó không hề có chức năng ma pháp phòng không hoành tráng nào kiểu như triển khai kết giới quy mô lớn cả."}, {"line": 81, "old": "“Gira-GoGame Mastera tổng cộng có sáu con. Ngoài Zagan ra, con nào cũng là những cá thể cực mạnh sở hữu năng lực Khổng Lồ Hóa.”", "new": "“Gira-Gogma tổng cộng có sáu con. Ngoài Zagan ra, con nào cũng là những cá thể cực mạnh sở hữu năng lực 『Khổng Lồ Hóa』.”"}, {"line": 83, "old": "Về ba con Bazuzu, Gizagins và Bon, tôi đã tận mắt chứng kiến chúng chiến đấu trong trạng thái khổng lồ hóa. Vì là đội tìm kiếm nên chúng hoạt động bên ngoài Vương quốc. Khi đó, đương nhiên chúng cũng phải chiến đấu với ma vật hoang dã.", "new": "Về ba con Bazuzu, Gizaginzu và Bon, tôi đã tận mắt chứng kiến chúng chiến đấu trong trạng thái khổng lồ hóa. Vì là đội tìm kiếm nên chúng hoạt động bên ngoài Vương quốc. Khi đó, đương nhiên chúng cũng phải va chạm với ma vật hoang dã."}, {"line": 85, "old": "Lũ Goma không có đầu óc để giấu giếm thông tin, nên hễ có ma vật xuất hiện là các Gira-GoGame Mastera sẽ tiên phong xông vào chiến đấu. Nếu phải nói thì chỉ có Gizagins là thường giao việc cho cấp dưới... nhưng khi chạm trán với ma vật mạnh có khả năng gây tổn thất lớn, hắn sẽ lập tức tham chiến ngay. Đó là kẻ có trí khôn để đánh giá đúng thực lực đối thủ. Trong các đội tìm kiếm, tên này có lẽ là kẻ khó nhằn nhất.", "new": "Lũ Goma không có đầu óc để giấu giếm thông tin, nên hễ có ma vật xuất hiện là các Gira-Gogma sẽ tiên phong xông vào nghiền nát đối thủ. Nếu phải nói thì chỉ có Gizaginzu là thường giao việc cho cấp dưới... nhưng khi chạm trán với ma vật mạnh có khả năng gây tổn thất lớn, hắn sẽ lập tức tham chiến ngay. Đó là kẻ có trí khôn để đánh giá đúng thực lực đối thủ. Trong các đội tìm kiếm, tên này có lẽ là kẻ khó nhằn nhất."}, {"line": 87, "old": "“Một trong sáu cá thể quý giá mà chúng sở hữu lại cất công rời khỏi Vương quốc, hơn nữa còn đi khiêu chiến với một kẻ thù mạnh như Salamander. Đây là cơ hội ngàn năm có một.”", "new": "“Một trong sáu cá thể mạnh nhất mà chúng sở hữu lại cất công rời khỏi Vương quốc, hơn nữa còn đi khiêu chiến với một kẻ thù nguy hiểm như Salamander. Đây là cơ hội ngàn năm có một.”"}, {"line": 89, "old": "“Ra là vậy, chúng ta sẽ nhắm vào lúc hắn ta suy yếu sau khi chiến đấu với con rồng!”", "new": "“Ra là vậy, chúng ta sẽ nhắm vào lúc hắn ta suy yếu sau khi huyết chiến với con rồng!”"}, {"line": 93, "old": "Sức mạnh của Salamander thì tôi cũng đã từng thấy tận mắt nên có thể hình dung được. Dù có là Gira-GoGame Mastera đi chăng nữa thì chắc chắn cũng không thể lành lặn mà rút lui.", "new": "Sức mạnh của Salamander thì tôi cũng đã từng thấy tận mắt nên có thể hình dung được. Dù có là Gira-Gogma đi chăng nữa thì chắc chắn cũng không thể lành lặn mà rút lui."}, {"line": 95, "old": "Nhưng việc tên Oh-ma đó chỉ giao việc cho một mình hắn chứng tỏ Bon cũng sở hữu sức mạnh đủ để đảm bảo chiến thắng.", "new": "Nhưng việc tên Oh-ma đó chỉ giao nhiệm vụ cho một mình hắn chứng tỏ Bon cũng sở hữu thực lực đủ để đảm bảo chiến thắng."}, {"line": 97, "old": "Mà quả thực, nhìn màn đại náo của Zagan thì có thể tin chắc rằng chúng đủ sức hạ gục cả rồng.", "new": "Mà quả thực, nhìn màn đại náo của Zagan thì có thể tin chắc rằng chúng đủ sức đè bẹp cả loài rồng."}, {"line": 99, "old": "“Gira-GoGame Mastera là những đối thủ cực kỳ nguy hiểm. Chỉ riêng việc khiêu chiến đã mang lại rủi ro rồi, nhưng khi chúng ta tấn công Vương quốc, khả năng cao là chúng sẽ đứng ra cản đường ở đâu đó. Trước khi thực hiện kế hoạch chính, chúng ta cần tiêu hao lực lượng mạnh nhất của chúng càng nhiều càng tốt.”", "new": "“Gira-Gogma là những đối thủ cực kỳ nguy hiểm. Chỉ riêng việc khiêu chiến đã tiềm ẩn rủi ro lớn rồi, nhưng khi chúng ta tấn công Vương quốc, khả năng cao là chúng sẽ đứng ra cản đường ở đâu đó. Trước khi thực hiện kế hoạch chính, chúng ta cần bào mòn lực lượng tinh nhuệ nhất của chúng càng nhiều càng tốt.”"}, {"line": 101, "old": "Mục tiêu của tôi là bằng mọi giá phải tiêu diệt từng con một trong số ba kẻ dẫn đầu các đội tìm kiếm.", "new": "Mục tiêu của tôi là bằng mọi giá phải bẻ gãy từng nhánh một trong số ba kẻ dẫn đầu các đội tìm kiếm."}, {"line": 103, "old": "Ngay lúc này, khi đội của Bon đang hoạt động độc lập, chính là cơ hội tuyệt vời nhất, và hắn cũng là đối thủ thích hợp nhất để hạ gục đầu tiên.", "new": "Ngay lúc này, khi đội của Bon đang tác chiến độc lập, chính là thời cơ tuyệt vời nhất, và hắn cũng là con mồi thích hợp nhất để hạ gục đầu tiên."}, {"line": 105, "old": "“Hơn nữa, chúng ta đã mất đi hai người dưới tay Zagan. Đó là một kẻ thù mạnh đến mức gây chấn thương tâm lý... Chính vì vậy, chúng ta phải tự tay tiêu diệt một Gira-GoGame Mastera để xây dựng phương án đối phó.”", "new": "“Hơn nữa, chúng ta đã mất đi hai người bạn dưới tay Zagan. Đó là một kẻ thù mạnh đến mức để lại bóng ma tâm lý... Chính vì vậy, chúng ta phải tự tay tiêu diệt một Gira-Gogma để xây dựng phương án đối phó và giải tỏa gánh nặng tinh thần.”"}, {"line": 109, "old": "Tác động tâm lý từ một thất bại không thể cứu vãn tuy vô hình nhưng lại vô cùng lớn. Đặc biệt là với nhóm Ueta, những người đã trực tiếp có mặt tại hiện trường lúc đó. Đến thời điểm quyết định, nếu họ bị nỗi sợ hãi làm cho đông cứng người thì cũng không có gì lạ.", "new": "Tác động tâm lý từ một thất bại đẫm máu tuy vô hình nhưng lại vô cùng nặng nề. Đặc biệt là với nhóm Ueta, những người đã trực tiếp có mặt tại hiện trường lúc đó. Đến thời khắc quyết định, nếu họ bị nỗi sợ hãi làm cho đông cứng tay chân thì cũng chẳng có gì lạ."}, {"line": 111, "old": "Chính vì thế, chúng ta phải chứng minh rằng mình có thể chiến thắng Gira-GoGame Mastera trong trận chiến lần này.", "new": "Chính vì thế, chúng ta phải chứng minh rằng mình hoàn toàn đủ sức chiến thắng Gira-Gogma trong trận chiến lần này."}, {"line": 113, "old": "“Trước hết là một con. Tiêu diệt một Gira-GoGame Mastera sẽ là bước đi đầu tiên để chinh phục Vương quốc.”", "new": "“Trước hết là một tên. Tiêu diệt một Gira-Gogma sẽ là bước đi đầu tiên để chúng ta san bằng Vương quốc.”"}, {"line": 119, "old": "Hướng về phía mặt trời đang tỏa sáng rực rỡ ngay trên đỉnh đầu, một tiếng gầm khổng lồ vang lên trên đỉnh núi.", "new": "Hướng về phía mặt trời đang tỏa sáng rực rỡ ngay trên đỉnh đầu, một tiếng gầm vang dội cất lên từ đỉnh núi."}, {"line": 123, "old": "“Quả không hổ danh Đại chiến sĩ!”", "new": "“Quả không hổ danh Đại Chiến Sĩ!”"}, {"line": 125, "old": "“Đại chiến sĩ Bon-sama vạn tuế!”", "new": "“Đại Chiến Sĩ Bon-sama vạn tuế!”"}, {"line": 127, "old": "Đội quân của Bon đang sục sôi trong niềm phấn khích chiến thắng, họ đã thành công tiêu diệt con rồng làm tổ trên đỉnh núi.", "new": "Đội quân của Bon đang sục sôi trong niềm phấn khích chiến thắng tột độ khi đã thành công tiêu diệt con rồng làm tổ trên đỉnh núi."}, {"line": 129, "old": "Con rồng bị hạ gục là một con hỏa long có vảy đỏ rực. Kích thước của nó không quá lớn cũng không quá nhỏ, thuộc cỡ thông thường. Chính vì thế, nó đã phát huy được trọn vẹn sức mạnh của loài rồng. Dù là một Đại chiến sĩ sở hữu năng lực hóa khổng lồ vượt trội, nhưng việc chiến đấu với rồng vẫn là một thử thách cận kề cái chết.", "new": "Con rồng bị hạ gục là một con hỏa long có vảy đỏ rực. Kích thước của nó không quá lớn cũng chẳng quá nhỏ, thuộc cỡ tiêu chuẩn. Nhờ thế, nó đã phát huy được trọn vẹn sự linh hoạt và uy lực của loài rồng. Dù là một Đại Chiến Sĩ sở hữu năng lực hóa khổng lồ vượt trội, việc đối đầu với rồng lửa vẫn là một thử thách cận kề cái chết."}, {"line": 131, "old": "May mắn thay, ở đây chỉ có một con duy nhất. Nếu có một cặp hai con, vết thương Bon phải chịu sẽ còn sâu hơn, và thiệt hại của đội quân chắc chắn sẽ vô cùng thảm khốc.", "new": "May mắn thay, ở đây chỉ có một con duy nhất. Nếu là một cặp hai con, thương tích Bon phải gánh chịu sẽ còn sâu hơn nhiều, và thiệt hại của đội quân chắc chắn sẽ vô cùng thảm khốc."}, {"line": 133, "old": "Dù sao thì sau khi ăn mừng chiến thắng một hồi, đội của Bon bắt đầu chuẩn bị rút lui.", "new": "Dù sao thì sau khi reo hò mừng chiến công một hồi, đội của Bon bắt đầu chuẩn bị thu quân."}, {"line": 135, "old": "Họ chất xác rồng lên một chiếc xe kéo khổng lồ đã chuẩn bị sẵn, và toàn bộ số trứng trong tổ cũng được thu hồi. Có vẻ như chưa có con non nào chào đời, nên công việc kết thúc nhanh chóng chỉ với việc nhặt trứng.", "new": "Chúng chất xác rồng lên một chiếc xe kéo khổng lồ đã chuẩn bị sẵn, đồng thời gom sạch toàn bộ số trứng trong tổ. Có vẻ như chưa có con non nào chào đời, nên công việc thu dọn kết thúc nhanh chóng chỉ với việc nhặt trứng."}, {"line": 139, "old": "Dù trên người đầy vết thương hở và vết bỏng nổi bật, Bon vẫn vui vẻ bắt đầu xuống núi.", "new": "Dù trên thân thể chằng chịt vết thương hở và những mảng bỏng rát rụa, Bon vẫn hớn hở dẫn đầu đoàn quân xuống núi."}, {"line": 141, "old": "Đội của Bon sẽ cứ thế tiến thẳng về Vương quốc trong khúc khải hoàn, dâng hiến hỏa long và trứng cho Oh-ma. Sau đó, hắn chắc chắn sẽ nhận được phần thưởng khổng lồ cho việc săn rồng.", "new": "Đội của Bon sẽ cứ thế tiến thẳng về Vương quốc trong khúc khải hoàn, dâng hiến hỏa long và trứng rồng cho Oh-ma. Sau đó, hắn chắc chắn sẽ nhận được phần thưởng hậu hĩnh cho chiến tích săn rồng vẻ vang này."}, {"line": 143, "old": "Dù đội quân đã kiệt sức sau trận chiến ác liệt với rồng, nhưng bước chân của họ vẫn nhẹ nhàng nhờ chiến thắng vẻ vang.", "new": "Dù cả đoàn quân đều đã kiệt sức sau trận huyết chiến với ma vật hùng mạnh, nhưng bước chân của chúng vẫn nhẹ nhõm nhờ men say chiến thắng."}, {"line": 145, "old": "Và rồi, ngay khi đội quân đầy thương tích của Bon kiêu hãnh đi xuống đến chân núi.", "new": "Và rồi, ngay khi đội quân đầy thương tích của Bon kiêu hãnh đặt chân xuống đến chân núi."}, {"line": 153, "old": "Đột nhiên xuất hiện phía trước là một con người.", "new": "Đột ngột chắn phía trước là một bóng người."}, {"line": 155, "old": "Không, chỉ nhìn thấy một kẻ, nhưng những kẻ khác vẫn đang ẩn nấp. Lũ con người hèn hạ đã giăng bẫy mai phục sẵn ở đây.", "new": "Không, chỉ nhìn thấy một kẻ lộ diện, nhưng những kẻ khác vẫn đang mai phục trong bóng tối. Lũ con người hèn hạ đã giăng sẵn cạm bẫy ở nơi này."}, {"line": 157, "old": "“Khốn kiếp, khói gì thế này!”", "new": "“Khốn kiếp, khói gì thế này?!”"}, {"line": 163, "old": "“Này, đừng tự ý di chuyển, đội hình————Gwaaaaaah!”", "new": "“Này, đừng tự ý di chuyển, giữ vững đội hình————Gwaaaaaah!”"}, {"line": 165, "old": "Làn khói trắng xóa đột ngột lan rộng. Trong tầm nhìn mờ mịt bởi khói mù mịt, những tiếng la hét bắt đầu vang lên khắp nơi.", "new": "Làn khói trắng xóa đột ngột bùng lên dày đặc. Trong tầm nhìn bị phong tỏa mù mịt, những tiếng thét xé họng bắt đầu vang lên khắp nơi."}, {"line": 167, "old": "Họ biết kẻ thù đang lợi dụng làn khói để tấn công, nhưng thậm chí không thể phân biệt được đó là những nhát chém, mũi tên hay ma pháp bắn vào.", "new": "Chúng biết kẻ thù đang lợi dụng làn khói để tập kích, nhưng thậm chí không thể phân biệt nổi đó là những nhát chém, mũi tên hay ma pháp bắn tới."}, {"line": 169, "old": "“Uwooo... Con người! Ta sẽ ăn thịt các ngươi, ta sẽ nuốt chửng các ngươi!”", "new": "“Uwooo... Con người! Ta sẽ ăn thịt các ngươi, ta sẽ nuốt chửng toàn bộ các ngươi!”"}, {"line": 171, "old": "Không hề dao động trước cuộc tập kích bất ngờ, Bon gầm lên.", "new": "Không hề nao núng trước cuộc phục kích bất ngờ, Bon gầm lên thịnh nộ."}, {"line": 173, "old": "Đối mặt với kẻ thù không đội trời chung, ý chí chiến đấu của Bon bùng lên như một ngọn lửa giận dữ bộc phát.", "new": "Đối mặt với kẻ thù truyền kiếp, ý chí chiến đấu của Bon bùng lên như một ngọn lửa cuồng nộ."}, {"line": 175, "old": "Đập vào mắt hắn là một con người cầm kiếm đang lao lên phía trước và hét lớn. Xung quanh tên đó không có khói, nên hắn không thể mất dấu.", "new": "Đập vào mắt hắn là một tên người cầm kiếm đang xông lên phía trước hét lớn. Xung quanh tên đó không có khói bao phủ, nên hắn không thể nào mất dấu."}, {"line": 177, "old": "Chỉ nhắm vào tên kiếm sĩ con người đang liên tục chém giết binh lính Goma đi đầu, Bon vung cây đại côn bổng yêu thích của mình lên, bước một bước thật dài về phía trước————", "new": "Chỉ nhắm vào tên kiếm sĩ con người đang liên tục chém giết binh lính Goma đi đầu, Bon vung cây đại côn bổng hộ thân lên, bước một bước dài sấm sét về phía trước————"}, {"line": 183, "old": "Hai đòn tấn công liên tiếp cực mạnh giáng thẳng vào lưng Bon.", "new": "Hai đòn tấn công liên hoàn cực nặng giáng thẳng vào sau lưng Bon."}, {"line": 185, "old": "Dù sở hữu thân hình khổng lồ ngang ngửa một GoGame Mastera, nhưng Bon vẫn bị thổi bay, lăn lộn về phía trước dưới uy lực khủng khiếp của võ kỹ vừa nện vào người.", "new": "Dù sở hữu thân hình đồ sộ ngang ngửa một con Gogma, Bon vẫn bị thổi bay, lăn lộn về phía trước dưới uy lực khủng khiếp của hai võ kỹ vừa nện trúng người."}, {"line": 187, "old": "Vừa phun máu và những mảnh thịt vụn từ sau lưng, Bon vừa nhanh chóng nhỏm dậy. Không hề tỏ ra đau đớn, hắn gầm lên với những mạch máu nổi đầy trên mặt vì giận dữ.", "new": "Vừa hộc máu và bắn tung tóe những mảng thịt vụn từ sau lưng, Bon vừa nhanh chóng bật dậy. Không hề lộ vẻ đau đớn, hắn gầm rống với những đường gân máu hằn rõ trên mặt vì tức giận tột cùng."}, {"line": 189, "old": "“N-Ngươi dám đánh lén từ phía sau sao?! Hèn hạ! Guuu, không tha thứ, ta sẽ không bao giờ tha thứ cho lũ con người các ngươi!”", "new": "“N-Ngươi dám đánh lén từ phía sau sao?! Đê tiện! Guuu, không tha thứ, ta sẽ không bao giờ tha thứ cho lũ con người các ngươi!”"}, {"line": 195, "old": "Gira-GoGame Mastera dù chưa hóa khổng lồ vẫn sở hữu năng lực chiến đấu vượt trội hơn cả GoGame Mastera. Sinh mệnh lực của chúng cũng vậy. Chỉ cần tránh được những điểm yếu chí mạng như não hay tim, chúng vẫn có thể tiếp tục chiến đấu với cơ thể đẫm máu nhờ sức chịu đựng dẻo dai.", "new": "Gira-Gogma dù chưa hóa khổng lồ vẫn sở hữu năng lực cận chiến vượt xa Gogma thông thường. Sinh mệnh lực của chúng cũng vậy. Miễn là tránh được những điểm yếu chí mạng như não bộ hay tim phổi, chúng vẫn có thể tiếp tục vung vũ khí với cơ thể đẫm máu nhờ sức chịu đựng dẻo dai phi lý."}, {"line": 197, "old": "Bon lườm hai tên con người hèn hạ vừa đánh lén sau lưng mình, nhưng trong chiến đấu, trực giác nhạy bén như thú dữ đã phản xạ giúp cơ thể hắn di chuyển.", "new": "Bon trừng mắt lườm hai tên con người hèn hạ vừa đánh lén sau lưng mình, nhưng trong chiến đấu, trực giác thú dữ sắc bén đã thúc đẩy cơ thể hắn phản xạ tức thì."}, {"line": 201, "old": "Ngay khi hắn vừa quay lại, tên kiếm sĩ con người mà hắn nhắm tới đầu tiên đã tung ra một nhát chém sắc lẹm.", "new": "Ngay khi hắn vừa xoay người, tên kiếm sĩ con người mà hắn nhắm tới ban đầu đã tung ra một nhát trảm kích sắc lẹm."}, {"line": 203, "old": "Theo trực giác, Bon vung cây côn bổng vẫn đang nắm chặt trong tay, gạt phăng đòn tấn công của tên kiếm sĩ con người.", "new": "Theo bản năng, Bon vung cây côn bổng vẫn đang nắm chặt trong tay, gạt phăng đường kiếm hiểm hóc của tên kiếm sĩ."}, {"line": 209, "old": "“Ugooo! Dù có bao nhiêu con người đi chăng nữa, ta cũng không thua đâu!”", "new": "“Ugooo! Dù có bao nhiêu con người đi chăng nữa, ta cũng tuyệt đối không thua!”"}, {"line": 211, "old": "Tên cầm rìu và tên mặc giáp vừa đánh lén phía sau cùng xông lên tấn công. Đồng thời, tên kiếm sĩ cũng phối hợp với chuyển động của hai tên kia để một lần nữa áp sát.", "new": "Tên cầm rìu và tên mang giáp vừa đánh lén phía sau cùng đồng loạt lao lên tiếp ứng. Đồng thời, tên kiếm sĩ cũng phối hợp nhịp nhàng với bước di chuyển của hai kẻ kia để một lần nữa áp sát tầm gần."}, {"line": 213, "old": "“Guboo, benjigazundoraa!” *(Khốn kiếp, chưa biến hình mà đã mạnh thế này rồi sao!)*", "new": "“Guboo, benjigazundoraa!” *(Khốn kiếp, chưa biến hình mà đã trâu bò thế này rồi sao!)*"}, {"line": 217, "old": "Vung vẩy cây côn bổng, Bon cản phá toàn bộ đòn tấn công phối hợp của ba tên con người.", "new": "Vung loạn cây côn bổng, Bon cản phá toàn bộ đợt tấn công phối hợp của ba tên con người."}, {"line": 219, "old": "Lũ con người biết dùng võ kỹ và di chuyển nhanh nhẹn, nhưng sức mạnh và tầm đánh của Bon hoàn toàn vượt trội. Với sức mạnh quái vật của Bon—kẻ có thể bóp nát một con GoGame Mastera thông thường chỉ bằng một tay—cây đại côn bổng được vung lên với tốc độ kinh hoàng. Trước cơn bão thép từ những cú vung liên tiếp, lũ con người không thể bước vào tầm đánh của hắn.", "new": "Lũ con người biết thi triển võ kỹ và di chuyển linh hoạt, nhưng sức mạnh và tầm đánh của Bon hoàn toàn áp đảo. Với lực tay quái vật của Bon—kẻ có thể bóp nát đầu một con Gogma thông thường chỉ bằng một bàn tay—cây đại côn bổng xé gió vung lên với tốc độ kinh hoàng. Đứng trước cơn bão thép cuồng bạo từ những cú quất liên hoàn, ba tên con người không tài nào bước chân nổi vào vòng chiến của hắn."}, {"line": 221, "old": "“Uhahaha! Ta mạnh lắm! Ta sẽ nghiền nát tất cả lũ con người các ngươi!”", "new": "“Uhahaha! Ta mạnh lắm! Ta sẽ nghiền nát tất cả lũ sâu bọ các ngươi!”"}, {"line": 223, "old": "Bon liên tục vung côn bổng không biết mệt mỏi, hắn tin chắc vào ưu thế tuyệt đối của mình. Rõ ràng hắn đang áp đảo ba tên con người.", "new": "Bon liên tục vung côn bổng không biết mệt mỏi, hắn tin chắc vào ưu thế tuyệt đối của mình. Rõ ràng hắn đang dồn ép ba tên con người vào thế phòng ngự."}, {"line": 225, "old": "Và phía bên kia không còn đòn tấn công nào vượt qua được cuộc tập kích đầu tiên nữa. Cứ đà này, dù đối thủ có là con người đi chăng nữa thì cũng chẳng khác gì những cuộc săn ma vật thông thường.", "new": "Và phía đối phương không còn tung ra được đòn tấn công nào xuyên qua nổi như đợt tập kích ban đầu nữa. Cứ đà này, dù đối thủ có là con người đi chăng nữa thì cũng chẳng khác gì những con mồi săn thông thường."}, {"line": 227, "old": "Quả nhiên lũ con người chỉ là những sinh vật yếu ớt, hèn nhát và đê tiện. Chẳng cần phải dùng đến Khổng Lồ Hóa————", "new": "Quả nhiên con người chỉ là những sinh vật yếu ớt, hèn nhát và đê tiện. Chẳng cần phải viện đến 『Khổng Lồ Hóa』————"}, {"line": 231, "old": "Cùng với tiếng hét của tên kiếm sĩ con người, cả ba tên đồng loạt nhảy lùi lại một khoảng lớn.", "new": "Cùng với tiếng thét của tên kiếm sĩ, cả ba tên đồng loạt đạp đất nhảy lùi lại một khoảng lớn."}, {"line": 233, "old": "Phía bên kia nơi chúng lùi lại vẫn là làn khói dày đặc đang bao phủ, khiến Bon mất dấu chúng.", "new": "Phía sau lưng nơi chúng vừa rút lui vẫn là làn sương khói dày đặc bao phủ, khiến Bon lập tức mất dấu mục tiêu."}, {"line": 235, "old": "“Lũ khốn này, đừng hòng chạy!”", "new": "“Lũ khốn kiếp, đừng hòng chạy thoát!”"}, {"line": 237, "old": "Nhận ra không thắng nổi nên bỏ chạy sao. Ba tên con người vừa nhảy lùi lại vừa ném thứ gì đó về phía hắn.", "new": "Nhận ra không đánh lại nên định tháo chạy sao. Ba tên con người vừa nhảy lùi vừa vung tay ném thứ gì đó về phía hắn."}, {"line": 239, "old": "Tên kiếm sĩ ném những con dao găm phun lửa. Tên cầm rìu và tên mặc giáp thì ném những quả cầu nhỏ phát nổ.", "new": "Tên kiếm sĩ ném ra những phi đao phun lửa. Tên cầm rìu và tên bọc giáp thì ném những quả cầu nhỏ phát nổ."}, {"line": 241, "old": "Chúng được ném chính xác về phía mặt Bon, nhưng hắn không chậm chạp đến mức trúng phải những thứ đó. Chỉ với một cú vung tay, hắn đã gạt phăng cả ba thứ, chỉ có một chút lửa bắn ra làm cản trở tầm nhìn trong thoáng chốc.", "new": "Chúng bay thẳng tắp về phía mặt Bon, nhưng thân thủ của hắn không chậm chạp đến mức trúng phải những món đồ chơi đó. Chỉ bằng một cú gạt tay, hắn đã đánh văng cả ba thứ, chỉ để lại một chút tia lửa bùng lên cản trở tầm nhìn trong thoáng chốc."}, {"line": 243, "old": "Không thèm bận tâm, ngay khi hắn đang lườm qua làn khói để đuổi theo lũ con người vừa chạy trốn————", "new": "Chẳng thèm bận tâm, ngay khi hắn đang gườm mắt xuyên qua làn khói định lao theo nghiền nát lũ con người vừa tháo lui————"}, {"line": 249, "old": "Kẻ lao ra không phải con người, mà là một con quái vật hình người có đầu bò—Ngưu ma nhân.", "new": "Kẻ xé toạc màn khói lao ra không phải con người, mà là một con quái vật nhân hình mang đầu bò—Ngưu ma nhân."}, {"line": 251, "old": "Đó là loài ma vật thỉnh thoảng mới thấy ở các di tích, tuy to lớn và có sức mạnh vượt trội trong số các ma vật hình người, nhưng không phải đối thủ của Bon. Thịt của loài này rất ngon nên là món khoái khẩu của hắn.", "new": "Đó là loài ma vật thỉnh thoảng vẫn xuất hiện ở các di tích tàn phá, tuy to lớn và có sức mạnh vượt trội trong số các loài ma vật dạng người, nhưng hoàn toàn không phải đối thủ của Bon. Thịt của loài này rất ngon nên vốn là món khoái khẩu của hắn."}, {"line": 253, "old": "“Ngươi cũng đến để làm mồi cho ta sao!”", "new": "“Ngươi cũng mò đến để nộp mạng làm mồi cho ta sao!”"}, {"line": 255, "old": "Bon đón đỡ trực diện con Ngưu ma nhân đang lao thẳng tới. Dù con Ngưu ma nhân đã hạ thấp trọng tâm và đâm sầm vào với toàn bộ tốc độ, nhưng nó không thể làm Bon lùi lại dù chỉ một bước.", "new": "Bon dang tay đón đỡ trực diện con Ngưu ma nhân đang lao thẳng tới. Dù con quái vật đã hạ thấp trọng tâm và tông sầm vào với toàn bộ quán tính lao dốc, nó vẫn không thể đẩy lùi Bon dù chỉ nửa bước."}, {"line": 257, "old": "Quả nhiên mình mạnh hơn hẳn, hắn vừa nghĩ vậy thì một thứ kỳ lạ đập vào mắt.", "new": "Quả nhiên sức mạnh của mình vượt trội hoàn toàn, hắn vừa đắc thắng nghĩ vậy thì một điểm bất thường đập thẳng vào mắt."}, {"line": 259, "old": "“Hửm? Ngươi mang cái gì trên lưng thế kia?”", "new": "“Hửm? Ngươi vác cái thứ gì trên lưng thế kia?”"}, {"line": 261, "old": "Ngưu ma nhân thỉnh thoảng có cầm vũ khí, nhưng chưa bao giờ mặc giáp hay đội mũ. Dù không phải vậy thì việc nó cõng một chiếc hộp lớn vô cùng nổi bật trên lưng cũng khiến người ta phải chú ý dù muốn hay không.", "new": "Ngưu ma nhân thỉnh thoảng có mang vũ khí thô sơ, nhưng chưa từng thấy con nào mặc giáp hay đội nón. Dù không tính đến chuyện đó thì việc nó cõng một chiếc rương lớn dị thường trên lưng cũng khiến kẻ khác phải chú ý dù muốn hay không."}, {"line": 263, "old": "“————Abracadabra *(Hắc Phát Phược)*”", "new": "“————*Abracadabra* *(Tóc Đen Trói Buộc)*”"}, {"line": 265, "old": "Hắn cảm giác như vừa nghe thấy một giọng nói nhỏ đang niệm chú, và ngay khoảnh khắc tiếp theo.", "new": "Hắn cảm giác như vừa thoáng nghe thấy một thanh âm thì thầm niệm chú kỳ quái, và ngay khoảnh khắc tiếp theo."}, {"line": 267, "old": "Từ chiếc hộp trên lưng con Ngưu ma nhân, vô số sợi xích sắt lao ra với tiếng loảng xoảng chói tai.", "new": "Từ chiếc rương trên lưng con Ngưu ma nhân, vô số sợi xích sắt đen ngòm lao vút ra với tiếng kim loại va đập leng keng chói tai."}, {"line": 269, "old": "“Cái gì?! X-Xích sắt này từ đâu ra thế này?!”", "new": "“Cái gì?! X-Xích sắt này từ đâu chui ra thế này?!”"}, {"line": 271, "old": "Trong lúc còn đang kinh ngạc trước những sợi xích tự chuyển động như rắn, chúng đã quấn chặt và trói buộc toàn thân Bon.", "new": "Trong lúc hắn còn đang bàng hoàng trước những sợi xích tự uốn lượn như bầy mãng xà, chúng đã siết chặt và khóa cứng toàn thân Bon."}, {"line": 273, "old": "Những sợi xích sắt to bản, chắc chắn quấn quanh cơ thể khổng lồ của Bon đến mười vòng, hai mươi vòng... nhưng thứ đó không thể ngăn cản được Đại chiến sĩ.", "new": "Những sợi xích sắt bản dày, nặng trịch quấn chặt quanh thân hình đồ sộ của Bon đến mười vòng, hai mươi vòng... thế nhưng chừng đó vẫn chưa đủ để cầm chân một Đại Chiến Sĩ."}, {"line": 275, "old": "“Nueeei! Không biết là cái gì nhưng phiền phức quá! Với 『Khổng Lồ Hóa』 của ta————”", "new": "“Nueeei! Không biết là trò ma quỷ gì nhưng phiền phức quá rồi đấy! Với 『Khổng Lồ Hóa』 của ta————”"}, {"line": 277, "old": "Một luồng ma lực mãnh liệt đột ngột bộc phát từ cơ thể Bon, cùng với một ma pháp trận tỏa sáng đỏ rực.", "new": "Một luồng ma lực cuồng bạo đột ngột bùng nổ từ sâu trong cơ thể Bon, cùng với một ma pháp trận rực sáng đỏ thẫm dưới chân."}, {"line": 279, "old": "『Khổng Lồ Hóa』. Đó là ma pháp cường hóa mạnh nhất do Vua Oh-ma vĩ đại ban tặng, chỉ dành riêng cho Gira-GoGame Mastera—chủng tộc cấp cao vượt trội hơn cả GoGame Mastera.", "new": "『Khổng Lồ Hóa』. Đó là ma pháp cường hóa tối thượng do Vua Oh-ma vĩ đại ban phát, đặc quyền chỉ dành riêng cho Gira-Gogma—chủng tộc thượng cấp vượt trội hơn hẳn loài Gogma tầm thường."}, {"line": 281, "old": "Nó không chỉ phóng to cơ thể của bản thân mà còn khổng lồ hóa cả trang bị, giúp tăng năng lực chiến đấu lên gấp nhiều lần trong chớp mắt.", "new": "Nó không chỉ phóng đại kích thước cơ thể mà còn biến hóa cả trang bị vũ khí, giúp khuếch đại chiến lực lên gấp bội lần trong chớp mắt."}, {"line": 283, "old": "Chỉ cần có thứ này, hắn có thể đối đầu trực diện ngay cả với loài rồng mạnh mẽ, đây chính là sức mạnh thực sự mà Đại chiến sĩ tự hào.", "new": "Chỉ cần kích hoạt thứ này, hắn có thể tay đôi đè bẹp cả loài rồng hùng mạnh, đây chính là sức mạnh tối cao mà một Đại Chiến Sĩ luôn tự hào."}, {"line": 285, "old": "Bon chuẩn bị giải phóng nó ngay bây giờ————", "new": "Bon chuẩn bị giải phóng nó ngay lập tức————"}, {"line": 289, "old": "Ngay khoảnh khắc tiếng hét dũng mãnh đó vang lên, ý thức của Bon hoàn toàn bị cắt đứt.", "new": "Ngay khoảnh khắc tiếng gầm dũng mãnh đầy uy lực đó vang lên, toàn bộ ý thức của Bon lập tức bị dập tắt hoàn toàn."}, {"line": 291, "old": "Bon thậm chí còn không kịp nhận ra chuyện gì đã xảy ra.", "new": "Bon thậm chí còn không kịp hiểu chuyện quái quỷ gì vừa giáng xuống đầu mình."}, {"line": 293, "old": "Bởi vì, khi cơ thể bằng xương bằng thịt của hắn còn chưa kịp hóa khổng lồ, một khối đá khổng lồ, vô cùng khổng lồ, đã lao thẳng vào hắn với tốc độ kinh hoàng.", "new": "Bởi vì, khi cơ thể bằng xương bằng thịt của hắn còn chưa kịp hoàn tất quá trình phóng to, một khối cự thạch khổng lồ, to lớn đến mức che khuất cả bầu trời, đã xé gió lao thẳng xuống với tốc độ kinh hoàng."}, {"line": 295, "old": "Từ đầu đến bụng, toàn bộ nửa thân trên của hắn bị khối đá bay tới đập nát bấy————Đại chiến sĩ Bon tử trận ngay lập tức.", "new": "Từ đỉnh đầu xuống tận bụng dưới, toàn bộ nửa thân trên của hắn bị tảng đá bay tới nghiền nát thành một đống thịt vụn bầy nhầy————Đại Chiến Sĩ Bon tử trận tại chỗ ngay tức khắc."}]}, {"ep": 322, "title": "Tập 322: Vương quốc sụp đổ", "filename": "chuong_322_vuong_quoc_sup_do.md", "replaces": 2, "changes": [{"line": 93, "old": "Tôi đã dùng 『Hắc Phát Phược』 trói chặt nó lại như một con nhện rồi treo lên trần nhà từ trước. Giờ chỉ đơn giản là giải trừ chú thuật và thả nó xuống trước mặt Oh-ma.", "new": "Tôi đã dùng 『Tóc Đen Trói Buộc』 trói chặt nó lại như một con nhện rồi treo lên trần nhà từ trước. Giờ chỉ đơn giản là giải trừ chú thuật và thả nó xuống trước mặt Oh-ma."}, {"line": 191, "old": "Những xúc tu tóc mang sắc đỏ đen độc hại phóng ra, đây là một biến thể của 『Hắc Phát Phược』 mang tính axit ăn mòn cực mạnh tương tự như 『Đầm Lầy Thối Rữa』. Dù có thể dùng để tấn công nhưng vì không có tính sát thương tức thời nên tôi ít khi sử dụng. Tuy nhiên, nếu là để lấy đầu lão ta thì thay vì dùng lưỡi kiếm, dùng thứ này để ăn mòn và làm đứt lìa sẽ dễ dàng hơn nhiều.", "new": "Những xúc tu tóc mang sắc đỏ đen độc hại phóng ra, đây là một biến thể của 『Tóc Đen Trói Buộc』 mang tính axit ăn mòn cực mạnh tương tự như 『Đầm Lầy Thối Rữa』. Dù có thể dùng để tấn công nhưng vì không có tính sát thương tức thời nên tôi ít khi sử dụng. Tuy nhiên, nếu là để lấy đầu lão ta thì thay vì dùng lưỡi kiếm, dùng thứ này để ăn mòn và làm đứt lìa sẽ dễ dàng hơn nhiều."}]}, {"ep": 329, "title": "Tập 329: Buổi họp lớp cuối cùng (4)", "filename": "chuong_329_buoi_hop_lop_cuoi_cung_4.md", "replaces": 2, "changes": [{"line": 335, "old": "“Làm ơn, nếu các cậu ở đó, hãy đáp lại tôi. Tinh linh bóng tối, hãy thay tôi bện tóc———— 『Hắc Phát Phược』.”", "new": "“Làm ơn, nếu các cậu ở đó, hãy đáp lại tôi. Tinh linh bóng tối, hãy thay tôi bện tóc———— 『Tóc Đen Trói Buộc』.”"}, {"line": 363, "old": "Mái tóc đen quấn quanh chiếc cổ thon thả của Takanashi và bắt đầu siết mạnh. Đây gần như là cách duy nhất để kết liễu đối phương bằng 『Hắc Phát Phược』.", "new": "Mái tóc đen quấn quanh chiếc cổ thon thả của Takanashi và bắt đầu siết mạnh. Đây gần như là cách duy nhất để kết liễu đối phương bằng 『Tóc Đen Trói Buộc』."}]}, {"ep": 331, "title": "Tập 331: Sự trở lại của bậc quân vương", "filename": "chuong_331_su_tro_lai_cua_bac_quan_vuong.md", "replaces": 2, "changes": [{"line": 69, "old": "『Xác nhận mã Mã Mã Mã General Code. Do ban bố tình trạng thiết quân luật khẩn cấp, ưu tiên áp dụng quân lệnh Emerodia. Ngừng hoạt động toàn bộ cổng dịch chuyển của Albion.』", "new": "『Xác nhận mã Mã Mã Mã Mã Mã General Code. Do ban bố tình trạng thiết quân luật khẩn cấp, ưu tiên áp dụng quân lệnh Emerodia. Ngừng hoạt động toàn bộ cổng dịch chuyển của Albion.』"}, {"line": 83, "old": "『Hiện tại, ngài \"Ryuuichi Tendou\" đã được bổ nhiệm làm Chỉ huy trưởng lâm thời của Căn cứ Albion. Như một biện pháp đặc biệt dưới tình trạng thiết quân luật khẩn cấp, quyền chỉ huy tạm thời đã được cấp cho ngài. Trong trường hợp muốn bãi nhiệm hoặc chuyển giao quyền hạn, yêu cầu phải được phê duyệt bởi người sở hữu mã Mã Mã Mã General Code cấp cao hơn, hoặc theo mệnh lệnh từ Bộ Tổng Tham mưu Liên hợp Emerodia, hoặc thông qua thương thảo.』", "new": "『Hiện tại, ngài \"Ryuuichi Tendou\" đã được bổ nhiệm làm Chỉ huy trưởng lâm thời của Căn cứ Albion. Như một biện pháp đặc biệt dưới tình trạng thiết quân luật khẩn cấp, quyền chỉ huy tạm thời đã được cấp cho ngài. Trong trường hợp muốn bãi nhiệm hoặc chuyển giao quyền hạn, yêu cầu phải được phê duyệt bởi người sở hữu mã Mã Mã Mã Mã Mã General Code cấp cao hơn, hoặc theo mệnh lệnh từ Bộ Tổng Tham mưu Liên hợp Emerodia, hoặc thông qua thương thảo.』"}]}, {"ep": 333, "title": "Tập 333: Đô thị cổ đại Albion", "filename": "chuong_333_do_thi_co_dai_albion.md", "replaces": 13, "changes": [{"line": 7, "old": "Quả nhiên, nơi này được kết nối bằng một lối đi bí mật không hề được ghi chép trên bản đồ đường hầm ngầm mà chúng tôi thu thập được từ tòa tháp. Có lẽ nhờ các chức năng vẫn còn hoạt động hoàn hảo, lối đi khổng lồ dạng đường hầm dẫn từ mặt đất đến pháo đài được thắp sáng trưng bởi ánh đèn trắng, không một vết bụi bẩn.", "new": "Quả nhiên, nơi này được kết nối bằng một lối đi bí mật không hề được ghi chép trên bản đồ đường hầm ngầm mà chúng tôi thu thập được từ tòa tháp. Nhờ các chức năng của di tích vẫn còn hoạt động hoàn hảo, lối đi khổng lồ dạng đường hầm dẫn từ mặt đất đến pháo đài được thắp sáng trưng bởi ánh đèn trắng, không một hạt bụi bặm."}, {"line": 11, "old": "Nơi này từng do một tay Kotori quản lý, nhưng hiện tại quyền lực của cô ta đã không còn chạm tới được nữa. Bởi nếu cô ta vẫn còn quyền thao tác, cánh cổng này chắc chắn đã bị khóa chặt.", "new": "Nơi này từng do một tay Kotori quản lý, nhưng hiện tại quyền kiểm soát của cô ta đã không còn chạm tới được nữa. Bởi nếu cô ta vẫn còn quyền thao tác, cánh cổng này chắc chắn đã bị khóa chặt."}, {"line": 13, "old": "“Tendou-kun, thế nào rồi?”", "new": "“Tendou-kun, tình hình thế nào rồi?”"}, {"line": 17, "old": "“Cái gọi là `『Mã Mã Mã General Code』` là quyền hạn liên quan đến quân sự hả? Còn của Kotori là `『Sinclair Code』`, nghĩa là dân sự, hay đúng hơn là dành cho hành chính?”", "new": "“Cái gọi là `『Mã General Code』` là quyền hạn liên quan đến quân sự hả? Còn của Kotori là `『Sinclair Code』`, nghĩa là dân sự, hay đúng hơn là quyền hạn hành chính?”"}, {"line": 27, "old": "“Momokawa-kun, cậu đứng gần Ryuuichi quá... Quả nhiên là hai người...”", "new": "“Momokawa-kun, cậu đứng gần Ryuuichi quá đấy... Quả nhiên là hai người...”"}, {"line": 29, "old": "“Tớ tránh ra rồi mà! Tớ tránh ra rồi nên không sao đâu, Ryouko-chan, nhé?”", "new": "“Tớ tránh ra rồi mà! Tớ tránh ra rồi nên không sao đâu, Lớp trưởng, nhé?”"}, {"line": 33, "old": "Và chỉ cần có quyền hạn quân sự mang tên `『Mã Mã Mã General Code』` của Tendou, chúng tôi có thể sử dụng các trang thiết bị cũng như chức năng của pháo đài mà không gặp bất kỳ trở ngại nào. Mọi sự chuẩn bị để khai thác triệt để nơi này đã hoàn tất.", "new": "Và chỉ cần có quyền hạn quân sự mang tên `『Mã General Code』` của Tendou, chúng tôi có thể sử dụng các trang thiết bị cũng như chức năng của pháo đài mà không gặp bất kỳ trở ngại nào. Mọi sự chuẩn bị để khai thác triệt để nơi này đã hoàn tất."}, {"line": 39, "old": "Cũng giống như lối đi bên ngoài, bên trong pháo đài vô cùng sạch sẽ. Tuy nhiên, việc nơi này phảng phất chút hơi thở sinh hoạt của con người có lẽ là do nhóm của Souma đã thực sự sống ở đây cho đến tận sáng nay.", "new": "Cũng giống như lối đi bên ngoài, bên trong pháo đài vô cùng sạch sẽ. Tuy nhiên, việc nơi này phảng phất chút hơi thở sinh hoạt của con người có lẽ là do nhóm của Souma đã thực sự sinh sống ở đây cho đến tận sáng nay."}, {"line": 43, "old": "Mei đi tiên phong, dẫn đường cho chúng tôi đi quanh pháo đài như thể cô đã quá quen thuộc với nơi này.", "new": "Mei-chan đi tiên phong, dẫn đường cho chúng tôi đi quanh pháo đài như thể cô đã quá quen thuộc với nơi này."}, {"line": 53, "old": "Dù cô ấy nói là “chỉ”, nhưng việc uống thứ thuốc cấm `『Berserk X』` rồi một mình cầm chân Zagan thì không thể dùng từ “chỉ” để khái quát được. Dù chúng tôi đã phải chiến đấu liên tục từ sáng sớm, nhưng Mei cũng đã phải chịu đựng sự mệt mỏi không hề kém cạnh.", "new": "Dù cô ấy nói là “chỉ”, nhưng việc uống thứ thuốc cấm `『Berserk X』` rồi một mình cầm chân Zagan thì không thể dùng từ “chỉ” để khái quát được. Dù chúng tôi đã phải chiến đấu liên tục từ sáng sớm, nhưng Mei-chan cũng đã phải chịu đựng sự mệt mỏi không hề kém cạnh."}, {"line": 89, "old": "Mei, người đã nhanh chóng chấp nhận sự hiện diện của Momoko, vừa xoa đầu cô nàng hầu gái đang đưa ra lời đề nghị giúp đỡ bằng giọng điệu kiêu kỳ kia. Động tác vuốt ve đó chẳng khác nào cách Hayama cưng nựng Beniwo.", "new": "Mei-chan, người đã nhanh chóng chấp nhận sự hiện diện của Momoko, vừa xoa đầu cô nàng hầu gái đang đưa ra lời đề nghị giúp đỡ bằng giọng điệu kiêu kỳ kia. Động tác vuốt ve đó chẳng khác nào cách Hayama cưng nựng Beniwo."}, {"line": 111, "old": "Sau khi thưởng thức món ăn tuyệt hảo do chính tay Mei chuẩn bị sau một thời gian dài, chúng tôi chuẩn bị đi ngủ. Ai nấy đều đã kiệt sức, nên trước mắt cứ để họ nghỉ ngơi càng sớm càng tốt.", "new": "Sau khi thưởng thức món ăn tuyệt hảo do chính tay Mei-chan chuẩn bị sau một thời gian dài, chúng tôi chuẩn bị đi ngủ. Ai nấy đều đã kiệt sức, nên trước mắt cứ để họ nghỉ ngơi càng sớm càng tốt."}, {"line": 135, "old": "Nếu vậy, khả năng con rồng này sau này học được nhân hóa chi thuật để biến thành hình người là cực kỳ cao. Mà nếu thế, kiểu gì nó cũng sẽ trở thành một bà lão trong thân xác loli cho xem. Với chất giọng và cách nói chuyện này, nếu không phải thế thì đúng là một cú lừa ngoạn mục.", "new": "Nếu vậy, khả năng con rồng này sau này học được thuật nhân hóa để biến thành hình người là cực kỳ cao. Mà nếu thế, kiểu gì nó cũng sẽ trở thành một bà lão trong thân xác loli cho xem. Với chất giọng và cách nói chuyện này, nếu không phải thế thì đúng là một cú lừa ngoạn mục."}]}, {"ep": 344, "title": "Tập 344: Món đồ thần thánh hằng mong đợi", "filename": "chuong_344_mon_do_than_thanh_hang_mong_doi.md", "replaces": 1, "changes": [{"line": 41, "old": "“Gây ra bao nhiêu chuyện xấu mà không thèm hối cải chút nào. Xem ra phải phạt cô thôi —— 『Hắc Phát Phược』!”", "new": "“Gây ra bao nhiêu chuyện xấu mà không thèm hối cải chút nào. Xem ra phải phạt cô thôi —— 『Tóc Đen Trói Buộc』!”"}]}, {"ep": 349, "title": "Tập 349: Chinh phục Tháp Trung Tâm (2)", "filename": "chuong_349_chinh_phuc_thap_trung_tam_2.md", "replaces": 2, "changes": [{"line": 45, "old": "`『Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm』`: Món vũ khí được cải tiến và cường hóa mạnh mẽ từ vũ khí chính ban đầu của cô ấy là `『Hắc Thiết Kích』`. Lớp sắt đen cứng và nặng được nấu chảy cùng với `『Thần Thiết』`—loại kim loại hiếm chiết xuất từ vũ khí thu được ở pháo đài ẩn—để tạo thành một loại hợp kim mới có độ bền vượt trội. Thêm vào đó, yếu tố tạo nên thuộc tính bão tố của món vũ khí này chính là hai cây rìu thuộc tính Lôi của Jiji-Gogo. Đúng như mong đợi từ vũ khí của một Gira-GoGame Mastera đại diện cho vương quốc, chúng là những món vũ khí ma pháp chất lượng cao vượt xa vũ khí của GoGame Mastera bốn tay. Một cây vẫn còn cắm trên tường thành, cây còn lại được thu hồi dưới đáy vực, cả hai đều được đem đi luyện kim để truyền vào nguồn sức mạnh thuộc tính Lôi cực mạnh.", "new": "`『Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm』`: Món vũ khí được cải tiến và cường hóa mạnh mẽ từ vũ khí chính ban đầu của cô ấy là `『Hắc Thiết Kích』`. Lớp sắt đen cứng và nặng được nấu chảy cùng với `『Thần Thiết』`—loại kim loại hiếm chiết xuất từ vũ khí thu được ở pháo đài ẩn—để tạo thành một loại hợp kim mới có độ bền vượt trội. Thêm vào đó, yếu tố tạo nên thuộc tính bão tố của món vũ khí này chính là hai cây rìu thuộc tính Lôi của Jiji-Gogo. Đúng như mong đợi từ vũ khí của một Gira-GoGame Mastera đại diện cho vương quốc, chúng là những món vũ khí ma pháp chất lượng cao vượt xa vũ khí của GoGame Mastera bốn tay. Một cây vẫn còn cắm trên tường thành, cây còn lại được thu hồi dưới đáy vực, cả hai đều được đem đi luyện kim để truyền vào nguồn sức mạnh thuộc tính Lôi cực mạnh."}, {"line": 49, "old": "Khi được truyền ma lực, Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm sẽ phóng ra những tia sét màu đỏ đen, nhưng vì cô ấy vẫn chưa hề nghiêm túc nên hiện tại chỉ đơn giản là đang vung vẩy cây kích siêu cứng đó mà thôi. Dẫu vậy, sức tàn phá của nó vẫn đủ để tạo nên một cơn mưa máu thịt màu xanh lam.", "new": "Khi được truyền ma lực, Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm sẽ phóng ra những tia sét màu đỏ đen, nhưng vì cô ấy vẫn chưa hề nghiêm túc nên hiện tại chỉ đơn giản là đang vung vẩy cây kích siêu cứng đó mà thôi. Dẫu vậy, sức tàn phá của nó vẫn đủ để tạo nên một cơn mưa máu thịt màu xanh lam."}]}, {"ep": 351, "title": "Tập 351: Thảm Thực Vật Ma Vật (1)", "filename": "chuong_351_tham_thuc_vat_ma_vat_1.md", "replaces": 7, "changes": [{"line": 13, "old": "Đã bắt được rồi, 『Hắc Phát Phược』.", "new": "Đã bắt được rồi, 『Tóc Đen Trói Buộc』."}, {"line": 15, "old": "Chiêu thức phát huy trọn vẹn công dụng vốn có của nó: trói chặt kẻ địch và phong tỏa cử động. Tôi đã trói được một trong bốn chiếc chân đang lao đi trên mặt đất của nó, thành công khóa chặt khả năng di chuyển của con quái vật, dù chỉ là tạm thời.", "new": "Chiêu thức phát huy trọn vẹn công dụng vốn có của nó: trói chặt kẻ địch và phong tỏa cử động. Tôi đã quấn được một trong bốn chiếc chân đang phi nước đại của nó, thành công khóa chặt khả năng di chuyển của con quái vật, dù chỉ là trong thoáng chốc."}, {"line": 23, "old": "Sức mạnh từ võ kỹ được cường hóa bởi thuộc tính Quang bộc phát, chém thẳng vào hai cái đầu của con chó săn hai đầu 『Orthros』. Hai chiếc đầu đứt lìa, lăn lông lốc trên đất cùng những tia máu xanh nhạt bắn tung tóe.", "new": "Sức mạnh từ võ kỹ được cường hóa bởi thuộc tính Quang bộc phát, chém thẳng vào hai cái đầu của con chó săn hai đầu 『Orthros』. Hai chiếc đầu đứt lìa, lăn lông lốc trên mặt đất cùng những tia máu xanh nhạt bắn tung tóe."}, {"line": 31, "old": "Nàng Thánh Nữ giờ đã chuyển chức thành một tiên phong máu lửa, có vẻ như vì quá say máu chiến đấu trước mắt mà cô nàng đã đánh mất đi tầm nhìn của một người hỗ trợ trị liệu vốn có.", "new": "Nàng Thánh Nữ giờ đã chuyển sang phong cách của một quân tiên phong máu lửa. Có vẻ như vì quá say máu chiến đấu trước mắt mà cô nàng đã đánh mất đi tầm nhìn bao quát của một trị liệu sư hỗ trợ vốn có."}, {"line": 51, "old": "Điểm chung của những con Boss ma vật tập trung ở đây là chúng đều có màu da và dòng máu xanh lam, tương tự như lũ Rối Ma Pháp.", "new": "Điểm chung của những con Boss ma vật tập trung ở đây là chúng đều có màu da và dòng máu xanh lam, tương tự như lũ Ma Đạo Nhân Hình."}, {"line": 129, "old": "Tôi phát hiện ra con Arachne đang ẩn nấp trên trần nhà là nhờ mạng lưới giám sát của lũ Rem chim mà tôi đã thả đi khắp nơi từ trước khi trận chiến bắt đầu. Chính trong những trận hỗn chiến thế này, ta càng phải cảnh giác độ trước những đòn đánh lén từ góc khuất.", "new": "Tôi phát hiện ra con Arachne đang ẩn nấp trên trần nhà là nhờ mạng lưới giám sát của lũ Rem chim mà tôi đã thả đi khắp nơi từ trước khi trận chiến bắt đầu. Chính trong những trận hỗn chiến thế này, ta càng phải cảnh giác cao độ trước những đòn đánh lén từ góc khuất."}, {"line": 197, "old": "And một điểm đặc biệt nữa, để tương thích với yếu tố Tinh linh, khẩu súng này được thiết kế để tối ưu hóa việc thi triển ma pháp hệ Thổ thông qua sự hỗ trợ của các tinh linh.", "new": "Và một điểm đặc biệt nữa, để tương thích với yếu tố Tinh linh, khẩu súng này được thiết kế để tối ưu hóa việc thi triển ma pháp hệ Thổ thông qua sự hỗ trợ của các tinh linh."}]}, {"ep": 367, "title": "Tập 367: Khổng Nhân VS Thánh Thú (2)", "filename": "chuong_367_khong_nhan_vs_thanh_thu_2.md", "replaces": 4, "changes": [{"line": 183, "old": "Mục tiêu thực sự của tôi là cho Yokomichi ăn càng nhiều 『Hắc Phát Phược』 càng tốt.", "new": "Mục tiêu thực sự của tôi là cho Yokomichi ăn càng nhiều 『Tóc Đen Trói Buộc』 càng tốt."}, {"line": 189, "old": "Vì lẽ đó, để gia tăng khối lượng “mồi” cho Yokomichi bằng bất cứ thứ gì có thể, tôi đã liên tục cho nó ăn 『Hắc Phát Phược』 cho đến khi cạn kiệt ma lực.", "new": "Vì lẽ đó, để gia tăng khối lượng “mồi” cho Yokomichi bằng bất cứ thứ gì có thể, tôi đã liên tục cho nó ăn 『Tóc Đen Trói Buộc』 cho đến khi cạn kiệt ma lực."}, {"line": 191, "old": "Chưa kể, Yokomichi vốn dĩ cực kỳ chấp niệm với việc nuốt chửng tôi, và ngay cả khi đã biến thành gậy phép, nó vẫn giữ cái tính khí ích kỷ là không chịu tung hết sức nếu không được dâng hiến máu tươi. Do đó, dù không biết đống tóc từ chú thuật có được tính là tóc thật hay không, tôi vẫn cất công kích hoạt 『Hắc Phát Phược』 ngay trên đầu mình để biến thành một mái tóc siêu dài rồi cho nó ăn trực tiếp, nhằm nâng cao chất lượng bữa ăn để Yokomichi cảm thấy hài lòng nhất có thể. *Này tên kia, nếu ngươi chỉ biết ăn cho sướng mồm mà không mang lại hiệu quả gì thì đừng hòng ta cho ăn thêm lần nào nữa đấy.*", "new": "Chưa kể, Yokomichi vốn dĩ cực kỳ chấp niệm với việc nuốt chửng tôi, và ngay cả khi đã biến thành gậy phép, nó vẫn giữ cái tính khí ích kỷ là không chịu tung hết sức nếu không được dâng hiến máu tươi. Do đó, dù không biết đống tóc từ chú thuật có được tính là tóc thật hay không, tôi vẫn cất công kích hoạt 『Tóc Đen Trói Buộc』 ngay trên đầu mình để biến thành một mái tóc siêu dài rồi cho nó ăn trực tiếp, nhằm nâng cao chất lượng bữa ăn để Yokomichi cảm thấy hài lòng nhất có thể. *Này tên kia, nếu ngươi chỉ biết ăn cho sướng mồm mà không mang lại hiệu quả gì thì đừng hòng ta cho ăn thêm lần nào nữa đấy.*"}, {"line": 197, "old": "Giờ đây tôi đã sở hữu lượng ma lực vượt trội tương xứng với một ma pháp sư thực thụ, và độ thuần thục của 『Hắc Phát Phược』 — chú thuật có từ thuở ban đầu — cũng đã đạt đến cấp độ tối cao. Tôi có thể giải phóng ra một lượng tóc đen cực kỳ khủng khiếp. Việc liên tục thực hiện điều đó cho đến khi cận kề giới hạn ma lực khiến chính tôi cũng không thể đong đếm được mình đã cho nó ăn bao nhiêu ký tóc nữa.", "new": "Giờ đây tôi đã sở hữu lượng ma lực vượt trội tương xứng với một ma pháp sư thực thụ, và độ thuần thục của 『Tóc Đen Trói Buộc』 — chú thuật có từ thuở ban đầu — cũng đã đạt đến cấp độ tối cao. Tôi có thể giải phóng ra một lượng tóc đen cực kỳ khủng khiếp. Việc liên tục thực hiện điều đó cho đến khi cận kề giới hạn ma lực khiến chính tôi cũng không thể đong đếm được mình đã cho nó ăn bao nhiêu ký tóc nữa."}]}, {"ep": 378, "title": "Tập 378: Quyết Chiến Cuối Cùng (2)", "filename": "chuong_378_quyet_chien_cuoi_cung_2.md", "replaces": 2, "changes": [{"line": 19, "old": "Meiko cầm `『Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm』` ở tay phải và `『Zagan's Pride』` ở tay trái. Cả hai đều là song phủ biến dị có nguồn gốc từ tộc Goma.", "new": "Meiko cầm `『Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm』` ở tay phải và `『Zagan's Pride』` ở tay trái. Cả hai đều là song phủ biến dị có nguồn gốc từ tộc Goma."}, {"line": 23, "old": "“Gầm vang đi, Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm.”", "new": "“Gầm vang đi, Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Hắc Lam Kiếm Phủ Gilastorm.”"}]}, {"ep": 388, "title": "Tập 388: Bậc Thầy Nguyên Tố", "filename": "chuong_388_bac_thay_nguyen_to.md", "replaces": 2, "changes": [{"line": 139, "old": "Giữa lúc cảm giác tuyệt vọng đen tối chuẩn bị nuốt chửng tầm nhìn của tôi, một bức tường đá đồ sộ đột ngột trồi lên sừng sững ngay trước mặt. Kẻ có thể thi triển Thổ ma pháp xuất sắc đến mức độ này trong lớp 2-7 chỉ có duy nhất một người.", "new": "Giữa lúc cảm giác tuyệt vọng đen tối chuẩn bị nuốt chửng tầm nhìn của tôi, một bức tường đá đồ sộ đột ngột trồi lên sừng sững ngay trước mặt. Kẻ có thể thi triển Thổ ma thuật xuất sắc đến mức độ này trong lớp 2-7 chỉ có duy nhất một người."}, {"line": 229, "old": "Ngoảnh đi ngoảnh lại, cô đã mạnh mẽ hơn xưa gấp bội. Cô có thể tùy ý điều khiển Thổ ma pháp để kiến tạo nên đủ mọi thứ công sự kỳ tích. Randou Kyouko đã vươn mình trở thành một át chủ bài thuộc hàng ngũ ma thuật sư hàng đầu mà bất kỳ ai cũng phải ngả mũ công nhận.", "new": "Ngoảnh đi ngoảnh lại, cô đã mạnh mẽ hơn xưa gấp bội. Cô có thể tùy ý điều khiển Thổ ma thuật để kiến tạo nên đủ mọi thứ công sự kỳ tích. Randou Kyouko đã vươn mình trở thành một át chủ bài thuộc hàng ngũ ma thuật sư hàng đầu mà bất kỳ ai cũng phải ngả mũ công nhận."}]}, {"ep": 393, "title": "Chương 393: Chú thuật sư VS Hiền giả (1)", "filename": "chuong_393_chuong_393_chu_thuat_su_vs_hien_gia_1.md", "replaces": 3, "changes": [{"line": 143, "old": "Bằng cách dùng 『Hắc Phát Phược』 điều khiển tự do để bắt các sợi tóc quấn lấy vũ khí sắc bén và tấn công từ xa, phương pháp này nếu ở thế giới thực thì chỉ có những bậc thầy xích liêm mới làm được... Thế nhưng, chiêu này chỉ có tác dụng với lũ Goma thông thường đại diện cho đám tép riu mà thôi. À, và cả cậu bạn Hayama nữa.", "new": "Bằng cách dùng 『Tóc Đen Trói Buộc』 điều khiển tự do để bắt các sợi tóc quấn lấy vũ khí sắc bén và tấn công từ xa, phương pháp này nếu ở thế giới thực thì chỉ có những bậc thầy xích liêm mới làm được... Thế nhưng, chiêu này chỉ có tác dụng với lũ Goma thông thường đại diện cho đám tép riu mà thôi. À, và cả cậu bạn Hayama nữa."}, {"line": 151, "old": "Nhìn cách Arachne giăng những sợi tơ cứng để tạo thành bẫy cắt đứt kẻ thù, tôi đã sáng tạo ra một chiêu thức biến thể từ 『Hắc Phát Phược』 gọi là 『Ngân Phát Trảm』. Tuy nhiên, vào thời điểm học được chiêu này, nhờ có những người đồng đội đáng tin cậy bên cạnh, cơ hội để tôi phải trực tiếp chiến đấu ở tuyến đầu đã giảm đi rất nhiều. Kết quả là chiêu thức này đã bị xếp xó và không có cơ hội thực chiến.", "new": "Nhìn cách Arachne giăng những sợi tơ cứng để tạo thành bẫy cắt đứt kẻ thù, tôi đã sáng tạo ra một chiêu thức biến thể từ 『Tóc Đen Trói Buộc』 gọi là 『Ngân Phát Trảm』. Tuy nhiên, vào thời điểm học được chiêu này, nhờ có những người đồng đội đáng tin cậy bên cạnh, cơ hội để tôi phải trực tiếp chiến đấu ở tuyến đầu đã giảm đi rất nhiều. Kết quả là chiêu thức này đã bị xếp xó và không có cơ hội thực chiến."}, {"line": 161, "old": "Nếu đã biết về 『Hắc Phát Phược』 của tôi, phản ứng đó của cô ta cũng là dễ hiểu. Thứ phóng ra từ đầu ngón tay không phải là những búi tóc dạng dây thừng, mà chỉ là những sợi tóc đơn lẻ mảnh như sợi thép. Tổng cộng chỉ có mười sợi phóng ra từ mười đầu ngón tay của hai bàn tay. Vì là những sợi tóc bạc lấp lánh nên mắt thường mới có thể lờ mờ nhìn thấy được. Đầu sợi tóc cũng chẳng gắn dao găm hay vật sắc nhọn nào, thực sự chỉ là những sợi tóc đơn thuần.", "new": "Nếu đã biết về 『Tóc Đen Trói Buộc』 của tôi, phản ứng đó của cô ta cũng là dễ hiểu. Thứ phóng ra từ đầu ngón tay không phải là những búi tóc dạng dây thừng, mà chỉ là những sợi tóc đơn lẻ mảnh như sợi thép. Tổng cộng chỉ có mười sợi phóng ra từ mười đầu ngón tay của hai bàn tay. Vì là những sợi tóc bạc lấp lánh nên mắt thường mới có thể lờ mờ nhìn thấy được. Đầu sợi tóc cũng chẳng gắn dao găm hay vật sắc nhọn nào, thực sự chỉ là những sợi tóc đơn thuần."}]}]}, "Tôi Đáng Lẽ Chỉ Là Một Ác Nữ Phản Diện Thông Thường Mà": {"novel_name": "Tôi Đáng Lẽ Chỉ Là Một Ác Nữ Phản Diện Thông Thường Mà", "novel_key": "Tôi Đáng Lẽ Chỉ Là Một Ác Nữ Phản Diện Thông Thường Mà", "timestamp": "2026-08-28 23:44:36", "total_scanned": 35, "total_modified": 0, "total_replaces": 0, "chapters": []}};
